-- New employee-facing topics use the same active-account role rules as the Help UI.
CREATE OR REPLACE FUNCTION public.help_can_read(needs_admin boolean, audience text, feature_area text)
RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=(SELECT auth.uid()) AND p.company_id IS NOT NULL AND coalesce(p.is_active,true)
    AND CASE WHEN p.role IN ('owner','admin') THEN true
      WHEN coalesce(needs_admin,false) OR audience='admin' THEN false
      WHEN p.role IN ('manager','office') THEN true
      WHEN p.role IN ('employee','subcontractor','user') THEN audience IS DISTINCT FROM 'office' AND feature_area IN
        ('Account','Employee Portal','Timesheets','Inventory','Daily Logs','Tasks','Notifications','Help & Support','Warranty','Documents')
      ELSE false END);
$$;
REVOKE ALL ON FUNCTION public.help_can_read(boolean,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.help_can_read(boolean,text,text) TO authenticated,service_role;

-- Source-verified guides and corrected quick answers share the canonical help table.
-- Stable slugs preserve existing IDs; updated answers are immediately used by AI.
INSERT INTO public.help_faqs (slug,feature_area,audience,question,answer_short,answer_long,route,search_terms,priority,requires_admin,is_active,last_verified_at,article_type,read_minutes,related_slugs,source_key)
SELECT slug,feature_area,audience,question,answer_short,answer_long,route,search_terms,priority,requires_admin,is_active,last_verified_at,article_type,read_minutes,related_slugs,source_key
FROM jsonb_to_recordset($articles$[{"slug":"guide-getting-started","feature_area":"Account","audience":"all","question":"Getting started with FuzedFlow","answer_short":"Find your workspace, understand your role, and follow your first workflow from the correct starting point.","answer_long":"## Choose the correct workspace\nIf you are joining an existing company, use the invitation sent by its administrator. Creating a separate company account does not automatically put you on that company's team. Sign in using the same method you used when joining: email and password, or **Sign in with Google**.\n\nOffice and project staff normally begin in the main workspace. Employees and subcontractors use the **Employee Portal**. The menu reflects your role and your company's permissions; a missing menu item does not mean your work was deleted.\n\n## Start with your role\n1. Open the navigation menu. On a phone, use the menu button at the top left.\n2. For office work, start with **Leads**, **Clients**, or **Quotes**. Check the client and site before creating a document.\n3. For project coordination, use **PM Dashboard**, **PM Projects**, or **Project Timeline**.\n4. For field work, open **Employee Portal** and choose the relevant section, such as **Clock In**, **My Projects**, or **My Tasks**.\n5. Owners and administrators can review company branding, financial defaults, notifications, and team access in **Settings** before sending customer documents.\n\n## Follow a complete workflow\nA typical office workflow moves from lead information to a client, then to a quote, project work, and invoicing. These are separate records and actions. Changing a lead stage does not by itself prove that a quote was accepted, a project was created, or an invoice was paid.\n\nBefore sending or approving a document, check its record number, recipient, project, and preview. Return to its list after saving and confirm that the new record or status appears.\n\n## Find help without leaving your task\nUse **Help → Help Articles** in the top navigation. Search for the screen name or the action you need, open a guide, and use its related-page link where available. **Quick answers & FAQ** offers shorter answers. AI Help can explain the same published articles and link you back to a guide.\n\n## If access or records are missing\nConfirm that you signed into the intended company account, clear active list filters, and ask your administrator to check your role or assignments. Keep the page name and any error text when contacting support. Never send passwords or payment card details.","route":"/HelpArticles","search_terms":["getting started","first steps","setup","onboarding","workspace","company","new subscriber"],"priority":100,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-mobile-navigation","guide-troubleshooting","guide-navigation-search"],"source_key":"help_articles_portal"},{"slug":"guide-mobile-navigation","feature_area":"Help & Support","audience":"all","question":"Using FuzedFlow on a phone or tablet","answer_short":"Navigate the mobile menu, read guides, and keep track of work when space is limited.","answer_long":"## Open the mobile navigation\nUse the menu button at the top left to open the sidebar. Office navigation groups related screens under **CRM**, **Quotes**, **Project Management**, **Financial**, and **Resources**. Tap a group to reveal its pages, then tap the page you want. Selecting a page closes the sidebar so your workspace is visible again.\n\nThe exact options depend on your role. Field users work through **Employee Portal** rather than the office navigation. Turning the device sideways may make a wide table easier to inspect, but does not change your permissions.\n\n## Find help from any supported workspace\n1. Tap **Help** in the top navigation.\n2. Choose **Help Articles** for detailed instructions or **Quick answers & FAQ** for a short answer.\n3. Enter a screen name or a few useful words in the search field.\n4. Narrow the topic or article type if there are many matches.\n5. Open an article and use **Jump to section** to reach the part you need.\n\nThe portal uses large search and filter controls and wraps article text within the screen. Long lists load in groups; use **Show more** rather than expecting every article to appear at once.\n\n## Work with forms and lists\nBefore saving, review fields above and below the keyboard. Close the keyboard when you need more room to inspect a form. Scroll within a table if a screen provides horizontal scrolling, and check that an action belongs to the intended row before tapping it.\n\nIf a list looks empty, clear its search, date, status, project, or assignee filters. A mobile section selector may replace the tabs or sidebar shown on desktop; look for the section name above the content.\n\n## Use AI Help comfortably\nTap the yellow **AI Help** button. Type one task or issue at a time and include the page name. Answers support numbered steps, readable lists, and related article links. Follow a related article to read the longer explanation. Close the helper to return to your work.\n\n## If the page is difficult to use\nSave or copy your unfinished text before refreshing. Try closing an open menu or keyboard, then reopen the section. If a control still cannot be reached, note the page, device/browser, and what you were trying to do when contacting support. A screenshot of the layout can help; leave private customer and payment details out.","route":"/HelpArticles","search_terms":["mobile","phone","tablet","menu","navigation","keyboard","touch","small screen"],"priority":98,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-navigation-search","guide-troubleshooting"],"source_key":"help_articles_portal"},{"slug":"guide-troubleshooting","feature_area":"Help & Support","audience":"all","question":"Troubleshooting missing records, failed actions, and loading problems","answer_short":"Use a practical checklist to resolve common issues and give support the details it needs when a problem remains.","answer_long":"## First check the current state\nBefore repeating an action, confirm what actually happened. A toast or changed label alone may not prove that an email was delivered, a payment was collected, or another record was updated. Return to the record list, reopen the item, and check the saved values or status.\n\nKeep unfinished form text somewhere safe before refreshing or navigating away. Avoid repeated payment, send, create, or approval clicks while a request is still running; duplicates are harder to diagnose.\n\n## A record or task is missing\n1. Confirm the company account and page you are using.\n2. Clear search text and narrow filters, including dates, statuses, projects, and assignees.\n3. Check other pages of a paginated list.\n4. For field work, ask your manager to check the project/task assignment and enabled portal sections.\n5. If a page is unavailable, ask an administrator to check role and permissions. Do not create a second company account to recover access.\n\n## A page will not load\nCheck your connection. If the help page offers **Try again**, use that action first. If the problem persists, preserve your form details and refresh once. Sign in again if the app reports that your session has expired. Note whether one page fails or the whole workspace is affected.\n\n## A save, upload, or send fails\nCheck required fields and the selected client/project. For uploads, keep the original file and note its type and size. Inspect the record list before repeating a creation action. For a send action, check the recipient address and any saved delivery/status information; do not treat a status change as proof of external delivery.\n\nSome pages include actions marked **Coming soon** or incomplete workflows. Search the article for that feature to check its current availability before trying again. A different entry point may have different capabilities, so include the exact page and action in your report.\n\n## A document total or report looks wrong\nCompare the source document, quantities, tax settings, selected options, and recorded payments. Review the customer-facing preview before sending. Do not infer payment collection or accounting synchronization from a dashboard figure alone.\n\n## Give support a useful report\nOpen **Help → Contact support** and include the page, record number, expected result, actual result, error text, and steps already tried. Include the approximate time and device/browser. **Open email app** prepares a draft; review and send it from your mail app. Never include passwords, secret links, or full payment card information.","route":"/Contact","search_terms":["troubleshooting","not working","failed","missing","load","empty","save","error","support","refresh"],"priority":99,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-getting-started","guide-mobile-navigation","guide-feature-availability"],"source_key":"help_articles_portal"},{"slug":"guide-navigation-search","feature_area":"Help & Support","audience":"all","question":"Finding pages and records with navigation and search","answer_short":"Understand the navigation groups and use record search separately from help search.","answer_long":"## Understand the workspace menu\nThe office sidebar groups screens by job: **CRM** contains leads and clients; **Quotes** contains quotes and templates; **Project Management** contains project views and approvals; **Financial** includes the financial pages your role can access; and **Resources** includes tasks, products, inventory, project notes, forms, reports, and HR where permitted.\n\n**Employee Portal** provides field tools. **Settings** is the company configuration entry point for authorized roles. On desktop the sidebar can collapse; on mobile the menu button opens it and group headings expand their pages.\n\n## Search your business records\n1. Use the search control in the top navigation. On desktop, **Ctrl+K** or **Command+K** toggles the search.\n2. Enter part of a quote title/number, client name/email, lead name/email, project name/number, or invoice number.\n3. Use the search filters when you need a particular record type, status, date range, or amount range.\n4. Select a result to open its record view.\n5. Press **Escape** or close search to return to the workspace.\n\nSearch uses records in the signed-in company. It is a shortcut to supported record types, rather than a search of every attachment or every word inside every document. A screen's own list search may offer a more specific way to find an item.\n\n## Search instructions instead of records\nUse **Help → Help Articles** to find instructions. Help search looks through article titles, summaries, text, topics, and keywords. Search for an action such as creating a quote, filtering assigned tasks, or recording time. Topic and article-type filters can narrow the results.\n\n## If search returns no results\nTry a shorter identifying term and clear filters. Confirm that the record is in the company you are signed into. Check its own page and pagination. If a result opens a page your role cannot access, ask your administrator to review access rather than changing the URL or assuming the record is gone.\n\n## Keep page names with your question\nDifferent records can have similar names. Include the screen name and record number when asking AI Help or support. For example, say whether you are searching the general **Tasks** screen or a project's **Staff & Tasks** list.","route":"/HelpArticles","search_terms":["navigation","search","find","record","Ctrl K","Command K","menu","filter"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-getting-started","guide-mobile-navigation"],"source_key":"help_articles_portal"},{"slug":"guide-access-permissions","feature_area":"Account","audience":"all","question":"Understanding missing menu items and role-based access","answer_short":"Recognize the difference between your role, company permissions, and work assignments.","answer_long":"## Access depends on your role\nFuzedFlow uses **Owner**, **Admin**, **Project Manager**, **Office Staff**, **Employee**, and **Subcontractor** roles. Owners and administrators have broad company access. Managers and office staff use operational pages subject to their role and configured permissions. Employees and subcontractors are directed to the **Employee Portal** for field work.\n\nThe invoice and HR routes allow owners, administrators, and office staff; managers do not automatically have those routes. Company settings is available to owners, administrators, and managers, with a smaller set of settings shown to managers. A menu label by itself does not override a page's access rules.\n\n## Diagnose a missing section\n1. Confirm that you joined the intended company using its invitation.\n2. Check whether you are in the office workspace or Employee Portal.\n3. Ask an administrator to review your current role and permissions.\n4. For field work, also check project/task assignments and enabled portal features.\n5. Sign out and back in if your administrator changed access and the screen still shows old options.\n\nPermission checks and assignment checks answer different questions: permission controls whether a tool is available; assignment controls which work is relevant to you. Neither guarantees that every record appears under the active list filters.\n\n## Read help for your access level\nSigned-in company users can open Help Articles, FAQ, tutorials, and Contact support. The portal hides admin-only content from non-admin roles. Field users receive field-related topics and general help rather than the full office library. AI Help uses the same access rules when choosing articles.\n\n## Avoid creating a second account as a workaround\nA new company registration does not restore membership or assignments in the existing company. Ask the administrator who invited you to confirm the email, role, and invitation status. Keep your existing account details private.\n\n## When an access error continues\nSend support the page name and the message shown, along with the role you expect to have. Leave passwords and invitation links out of the message. Support can help investigate the screen, while your company administrator remains the contact for deciding the access you should receive.","route":"/HelpArticles","search_terms":["permissions","access","role","missing menu","employee","manager","office","admin","invitation"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-getting-started","guide-troubleshooting"],"source_key":"help_articles_portal"},{"slug":"guide-approvals-review","feature_area":"Projects","audience":"office","question":"Reviewing quotes, change orders, and purchase orders in Approvals","answer_short":"Choose the approval record type, review its status, and distinguish approvals from document signing and delivery.","answer_long":"## Choose the record type\nOpen **Approvals** from Project Management. Use the view selector to choose **Quote Approvals**, **Change Orders**, or **Purchase Orders**. Each view uses its own search and status filters, so an empty list may simply reflect the selected view or filter.\n\nThis is an office/project coordination screen. Field users should ask their manager about approval status rather than expect the Approvals page in the Employee Portal.\n\n## Review a quote approval\n1. Choose **Quote Approvals**.\n2. Search for a quote or signer and choose the desired status filter.\n3. Compare the quote number, signer information, status, and dates with the intended quote.\n4. Open the related quote through the **Quotes** page when you need to inspect its current contents.\n5. Confirm customer-facing details before sending another customer link.\n\nThe quote approval list includes statuses such as **Pending**, **Sent**, **Viewed**, **Signed**, **Declined**, and **Expired**. A status label is a record state; it is not a guarantee that every document in the company has a captured signature.\n\n## Review change orders and purchase orders\nSwitch the view selector and search for the intended record. Use **View Details** to inspect the document. Where status controls are available, check the record and your authorization before changing an approval state. Return to the document and project to verify any associated values; an approval does not by itself prove all project, accounting, or external systems have synchronized.\n\n## Treat resend and copied-link actions carefully\nThe Approvals screen's **Resend Link** updates the stored approval status and sent time. It should not be treated as evidence that a message was actually delivered. The copied quote-approval URL from this screen is not a confirmed working customer route in the current app. Use the quote's supported preview/share/send workflow and verify the intended public view instead.\n\n## If an approval is missing or inconsistent\nClear the view's filters, confirm the source document and company, and compare the current status on the document. If a link does not open or approval information disagrees, keep the quote/change-order/purchase-order number and page name for support. Avoid repeated approvals while the issue is unresolved.\n\n## Internal review is separate from customer acceptance\nSaved Quote and Change Order builders offer **Actions → Request Internal Review** for eligible drafts/sent documents. It saves content before setting Pending Review. In **Approvals**, choose **Internal Review**, then **Open document**, **Approve for sending** or **Return for changes**. Both decisions return the document to Draft with the independent review result. Neither is customer acceptance or an electronic signature. Customer document pages separately support accepting, requesting changes and declining, including an optional reason.","route":"/Approvals","search_terms":["approvals","pending","signed","declined","resend","change order","purchase order","status"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-feature-availability","guide-troubleshooting"],"source_key":"help_articles_portal"},{"slug":"guide-client-forms-resources","feature_area":"Resource Library","audience":"office","question":"Uploading and finding client forms and shared resources","answer_short":"Store a company document, optionally link it to a project, and understand what a document upload does.","answer_long":"## What Client Forms stores\n**Client Forms** stores company resources such as flyers, forms, certificates, and reference documents. A resource can be a general document or linked to a project. Uploading a file does not create a document-signature request or submit a warranty claim.\n\nUse this page for reference material your company intends to make available. The current resource workflow produces a public file URL, so do not use it for passwords, private identity documents, or other files that require a private sharing process.\n\n## Upload a resource\n1. Open **Client Forms** from **Resources**.\n2. Choose **Upload File** to open **Upload New Resource**.\n3. Enter a clear **Document Name**.\n4. Under **Link to Project (Optional)**, choose a project or **General Document (Available for all)**.\n5. Select an **Attachment** using **Click to browse**. The picker describes PDF, DOCX, and images; keep the original file in your own records.\n6. Choose **Save Document** and wait for the upload to finish.\n7. Confirm that the resource appears in the list and use **View** to verify the file you selected.\n\n## Find an existing document\nUse the page's search to find the resource name and move through the list pages if necessary. Check the project association, file name, and upload date before opening or distributing a document. A newer file with a similar name may be a different resource rather than an automatic replacement of the old one.\n\n## If an upload fails\nCheck the required name and file, your connection, and your company access. Preserve the original file and any error text. Check the list before repeating the upload because a file transfer and its saved resource record are separate steps. If the file opens incorrectly, note the file type and resource name when contacting support.\n\n## Remove a resource carefully\nThe delete action asks for confirmation. Confirm the selected document before deleting and make sure you have the original file if the company still needs it. Removing a saved resource record should not be interpreted as a promise that every previously shared public file URL becomes unavailable.","route":"/ClientForms","search_terms":["client forms","resource","upload file","document","certificate","PDF","attachment","public file"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-feature-availability","guide-troubleshooting"],"source_key":"help_articles_portal"},{"slug":"guide-feature-availability","feature_area":"Help & Support","audience":"all","question":"Feature availability: signing, warranties, videos, and integrations","answer_short":"Check the current limits of features that can otherwise be mistaken for completed workflows.","answer_long":"## Approval and general document signing\nQuote and change-order approvals are supported workflows in specific document views. Saved project documents now support **Quotes & Docs → Reviews & signatures → Request review / signature**. The recipient explicitly records review or electronic-signature consent through a private expiring link; other catalogs and sales approvals remain separate. A label, notification, or uploaded form is not by itself proof that a signed document has been captured.\n\nIf a signature is required, use the signing process your company and customer agreed to and retain the resulting signed file. Check the guide for the exact document type and entry point before relying on an approval action.\n\n## Warranty claims\nYou can retain project notes and supporting documents. **Warranty** now provides dedicated claim intake, assignment, response deadlines, repair visits, customer confirmation and reopening. Use the warranty page and its private customer links to record that workflow. Uploading a warranty document or adding a project note does not formally submit a claim.\n\n## QuickBooks and accounting synchronization\nThe QuickBooks connection action in Settings is marked **Coming soon**. Do not assume that invoices, payments, or customer records are synchronizing with QuickBooks. Continue the accounting process your company currently uses and reconcile source records when comparing figures.\n\n## Video tutorials and reports export\nThe video tutorials page is a coming-soon page. Help Articles and FAQ provide current written guidance. The Reports export action currently displays a preparation/completion message without producing a confirmed report file. Use the available on-screen figures and source records rather than treating that message as a downloaded accounting export.\n\n## Notifications and delivery\nIn-app notifications are the alerts shown by the app's notification centre. Optional personal email, SMS and browser-device push are selected under **My notifications** and need configured delivery plus valid contact/device permission. In-app history alone does not prove an external delivery. Some status buttons update records without performing external delivery. Check the specific send workflow and recipient when delivery matters.\n\n## Legacy or bookmarked pages\nSome older pages and controls may not be available through the current navigation or may not complete their displayed action. Start from the supported navigation menu and consult the relevant guide. If a saved bookmark opens an error or unexpected view, preserve the page name and ask support to identify the current entry point.\n\n## Get an accurate answer\nInclude the page, document type, and action when asking AI Help. The helper uses the published help articles and should describe these limits rather than invent a missing workflow. Contact support when you need help locating an existing record or verifying the status of a specific action.\n\n## Older timesheet bookmarks\nThe separate older **Timesheet** page is not the current Employee Portal time workflow and may fail to load or submit. Open **Employee Portal** and choose **Clock In** or **My Time Sheets** instead. Do not enter the same hours in both places. If hours are missing, ask your manager to check the current HR timesheets and keep the date/time details for support.","route":"/HelpArticles","search_terms":["coming soon","available","warranty","signature","signing","QuickBooks","integration","video","export","legacy"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-troubleshooting","guide-approvals-review"],"source_key":"help_articles_portal"},{"slug":"guide-help-articles-ai","feature_area":"Help & Support","audience":"all","question":"Finding the right article and using AI Help","answer_short":"Search the published help library, read detailed guides or quick answers, and ask the helper a specific question.","answer_long":"## Open the Help Articles portal\nChoose **Help → Help Articles** in the top navigation. You can also reach the portal from the AI helper. The help library contains detailed guides and short FAQ answers. The articles available to you depend on your company role, so field users do not see the whole office or administration library.\n\n## Find a relevant answer\n1. Type a feature, task, or question in **Search help articles**. Use useful words such as quote discount, expense approval, assigned tasks, or missing notification.\n2. Choose a topic collection or use **Filter by topic** to narrow the library.\n3. Choose **Guides** for detailed instructions, **Quick answers** for short explanations, or **All** to search both.\n4. Read the summary on a result card, then open the article.\n5. Use **Show more articles** if more matches remain. Clear search or reset filters to broaden your results.\n\nHelp search finds words inside the article as well as its title and summary. It is separate from the top-navigation search for your company's business records.\n\n## Read and follow a guide\nThe reader shows an estimated reading time and a review date. On desktop, **On this page** links to its sections; on a phone, use **Jump to a section**. **Open related page** takes you to the relevant app page when your role can use that route. Check the exact client/project/record before performing the steps.\n\nUse **Keep exploring** for related articles. **Back to all help articles** returns to your previous browse filters. If an article is unavailable, return to the available library; the link may be old or cover a role you do not have.\n\n## Ask AI Help a useful question\nTap **AI Help** and include the page, task, and what happened. For example: “In Staff & Tasks, how do I show only unassigned tasks?” The helper retrieves instructions from the same published library, formats the answer, and provides relevant article links. Follow those links when you need the full workflow or troubleshooting details.\n\nAI Help explains published instructions; it does not confirm that a specific customer payment, upload, invitation, or save completed in your records. Verify that result in the app. If an answer does not cover the detail you need, use the full guide or contact support rather than treating a guess as a confirmed feature.","route":"/HelpArticles","search_terms":["help articles","AI","assistant","guide","FAQ","search","topic","read","contents","troubleshooting"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-troubleshooting","guide-navigation-search"],"source_key":"help_articles_portal"},{"slug":"guide-all-tasks","feature_area":"Tasks","audience":"office","question":"Managing Action Items in the All Tasks screen","answer_short":"Find and manage general and project tasks while understanding the differences between their record types.","answer_long":"## Choose the right task list\nOpen **Resources → All Tasks** in the office workspace. The page heading is your company's **Action Items**. It combines general/CRM tasks and project tasks. For work inside one project, use **PM Projects → your project → Staff & Tasks**. Field users use **Employee Portal → My Tasks** for assigned work.\n\n## Find an action item\n1. Enter words in **Search tasks**.\n2. Choose **Every Status**, **All Unfinished Tasks**, or a specific status.\n3. Check the record's relation, priority, target date, and assignee.\n4. Move through the list pages if necessary; the screen shows tasks in groups rather than every matching task at once.\n5. Open the row/card to view the task description and details.\n\nThis combined list groups source statuses into **Pending**, **Active**, **Under Review**, and **Completed**. A project's **Blocked** task can appear under **Under Review** here; **To Do** can appear as **Pending**. Compare the source task before assuming its status changed unexpectedly.\n\n## Create an action item\nChoose **New Task**. Enter **Task Title**, description, and **Task Type**. Select the correct **Production Project**, **CRM Lead**, or **CRM Client** relation where applicable. The form limits mutually incompatible relations rather than attaching every relation at once. Add a vendor/subcontractor if needed, choose **Assign To**, priority, status, due date, and estimated hours, then submit the form.\n\nProject-related tasks and general tasks are stored as different task types. Reopen the saved task and verify its relation and assignment before treating it as ready for the crew.\n\n## Edit carefully\nOpen the details, then choose **Edit Task Details**. Review the available relation fields and choose **Save Changes**. Some relations are disabled depending on the original task type. Changing a status or seeing a success message should be followed by checking the reopened record.\n\nThe combined list and details may show the first assignee for a task assigned to multiple people. Use the project's **Staff & Tasks** view to inspect the full assignment before making an assignment change. The project assignee filter belongs to that project view, not to the combined list's status filter.\n\n## Troubleshooting\nClear search and status filters if a task disappears after an update. Compare the project and general lists, check assignment and company access, and inspect later pages. Preserve the task title, related project, and visible error when reporting a failed save. Avoid deleting and recreating a task merely to make it reappear.","route":"/Tasks","search_terms":["all tasks","action items","new task","general","CRM","status","pending","active","under review","completed","assignment"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-troubleshooting","guide-navigation-search"],"source_key":"help_articles_portal"},{"slug":"guide-project-views","feature_area":"Projects","audience":"office","question":"Choosing the right project workspace and detail view","answer_short":"Find the project from the current menu and recognize why different project links can show different layouts.","answer_long":"## Start from the current project menu\nOpen **Project Management → PM Projects** and select the intended project. Check its name and number before changing work. **PM Dashboard** summarizes project work, while **Project Timeline** is a scheduling view. They are different entry points, so a count or date shown in one view is not a guarantee that every other screen uses the same calculation.\n\nFor field assignments, use **Employee Portal → My Projects**, **My Schedule**, and **My Tasks**. Employees and subcontractors should not expect the office project detail pages to be available through their role.\n\n## Understand the detail layout\nSome existing links or records open an older project-detail layout. That view includes **Dashboard**, **Notes**, **Tasks**, **Gantt Chart**, **Resources**, **Schedule**, **Time**, **Materials**, **Files**, and **Permits**, with **Quote** shown when the project has a linked quote. These are sections within the selected project rather than separate company-wide records.\n\nThe current PM workspace uses its own sections and controls. Follow the guide for the screen you actually see. Do not assume that instructions for **Staff & Tasks** in the PM workspace refer to an identically named control in an older detail page.\n\n## Find a project safely\n1. Return to **PM Projects** if an old bookmark opens an empty or unexpected detail view.\n2. Search for the project name/number and clear list filters.\n3. Open the record from the list instead of manually changing its URL.\n4. Confirm the linked client, quote, and site before choosing a section.\n5. If the project is assigned to a field user, ask the manager to verify that assignment in the office project workspace.\n\n## Compare related information\nA quote describes the agreed scope; project tasks describe work; time entries record time; materials record quantities/costs; and files are attachments. Editing one section does not prove the other records were automatically updated. Reopen the affected source record after saving or approving a change.\n\n## If a view is inconsistent\nPreserve the project number and the exact page or section name. Check the current PM workspace and original quote before repeating a creation or import action. Keep unfinished notes before refreshing. If the mismatch remains, send support the two views you compared and the expected result. This gives support a useful reproduction without exposing private client details.","route":"/PMProjects","search_terms":["project detail","workspace","project views","bookmark","Gantt","project dashboard","missing project"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-troubleshooting","guide-navigation-search"],"source_key":"help_articles_portal"},{"slug":"guide-account-sign-in","feature_area":"Account","audience":"all","question":"Create an account, join an invited team, and sign in","answer_short":"Choose the correct signup or sign-in path, use the invited email, and troubleshoot confirmation and Google login.","answer_long":"## Choose the correct account path\nUse **Sign up** when creating a new company account. Use the signup link provided for your team's invited email when joining an existing company. These paths serve different purposes: creating another company does not add you to your employer's workspace.\n\nA new company signup asks for **Company Name**, **Your Full Name**, **Email address**, **Password**, and **Confirm Password**. An invited signup displays **Join your team**, pre-fills the invited email, and hides Company Name. The invited email cannot be changed in that form.\n\n## Sign up or join your team\n1. Open the appropriate signup page and check the heading.\n2. Enter your full name. For a new company, enter the company name as well.\n3. Enter matching passwords of at least six characters. The eye buttons reveal each password so you can check typing.\n4. Select **Sign up** or **Join Team** once and wait for the result.\n5. If prompted to confirm your account, check your inbox and spam folder, confirm the email, and return to **Sign in**.\n\n**Sign up with Google** is also available. Choose the Google account whose email matches the intended company membership. An email can belong to only one FuzedFlow company; an existing-account message is a reason to use Sign in or ask your company administrator, rather than repeatedly create accounts.\n\n## Return to your account\nOn the login page, use **Email address**, **Password**, and **Sign in**, or **Sign in with Google** if that was your original login method. Google users may not have a separate email password.\n\n## If login fails\nCheck the email spelling, confirmation status, and original login method. The current login screen does not provide a self-service **Forgot Password** button. For password recovery or an unexpected company association, contact support and provide your account email and the error wording. Do not send your password. If Google returns you to the login page, allow the authentication screen to finish before refreshing.","route":"/login","search_terms":["signup","login","Google","password","confirm email","join team","forgot password"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-team-invites","guide-support-and-ai"],"source_key":"help_articles_portal"},{"slug":"guide-team-invites","feature_area":"Team","audience":"admin","question":"Invite team members and choose their access role","answer_short":"Owners and administrators can invite colleagues through Team Management and track pending membership.","answer_long":"## Who can invite people\nUse an **Owner** or **Admin** account for team invitations. Open **Settings**, then **Team Management**. A project staff assignment and a company invitation are different: invite the person into the company first, then assign them to the relevant project when needed.\n\n## Create a company invitation\n1. Select the invitation action to open **Invite Team Member**.\n2. Enter **Full Name** and **Email Address**. Check the address with the colleague before saving; they must register with this same email.\n3. Choose **Access Role**.\n4. Enter **Hourly Pay Rate** if required for your company's estimates, or leave the appropriate initial value for your payroll process.\n5. Select **Send Invite** and wait until the member appears as pending in the team list.\n\nThe detailed invitation form offers **Employee (Field Only)**, **Project Manager (Ops Access)**, **Office Staff (Office Access)**, **Subcontractor (Field Only)**, and **Admin (Full Access)**. Existing owners may also appear in the list. Give the access needed for the person's work; an admin role includes settings and company-level administration.\n\n## Help the colleague join\nAsk the colleague to use the invited email on the company join/signup path. An invitation appearing in **Pending** means the registration has not yet been accepted. The screen's success message confirms that an invitation was saved; do not treat it as proof that an email was delivered. If the colleague has no invitation email, share the approved signup instructions with them and check the pending record.\n\n## Find and correct an invitation\nSearch by name, email, or role. Use the pending member's edit action to correct the name, role, or initial rate, or cancel an obsolete pending invitation. Pending invitations count toward the limit checked by this form.\n\n## Troubleshooting\nIf the user already belongs to another FuzedFlow company, resolve that membership with support. If a legacy **Team Settings** page offers **Standard User**, use the detailed **Settings → Team Management** form instead. Current invitations use the canonical roles above and require an owner or administrator.","route":"/AdminSettings","search_terms":["invite staff","join company","team member","role","pending invitation"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-team-access-and-seats","guide-account-sign-in"],"source_key":"help_articles_portal"},{"slug":"guide-team-access-and-seats","feature_area":"Team","audience":"admin","question":"Manage roles, account activity, and team seat limits","answer_short":"Review team access, edit a member, deactivate an account, and resolve company user-limit messages.","answer_long":"## Review company access\nOwners and administrators manage company membership in **Settings → Team Management**. The list combines existing profile records and pending invitations. Use its search field to find a member by name, email, or role before making an access change.\n\nCompany roles control the areas available after sign-in. Employees and subcontractors use the field portal; managers have operations access; office staff have office access. Some areas have extra restrictions: HR is for owners, administrators, and office staff, while the main Settings page is for owners, administrators, and managers. Managers cannot open every Settings section.\n\n## Edit a member\n1. Open the member's edit action.\n2. Check the email shown in **Edit Team Member** so you are changing the intended account.\n3. Update **Full Name**, **Access Role**, or **Hourly Pay Rate** as needed.\n4. For an existing account, set **Active Account** appropriately.\n5. Save and check the updated list.\n\nTurning Active Account off is the reversible access-management option provided by the form. The control is not shown for pending invitations. If a name change is needed, also check historical time records with HR: some employee screens match recorded entries by employee name.\n\n## Understand seat checks\nThe detailed invitation form compares the combined team and pending-invitation count with the company's maximum users. A limit warning may therefore occur even when not every colleague has completed signup. Review and cancel obsolete pending invitations before adding more people. Do not assume deactivating an account automatically removes it from the count used by that invitation form.\n\nUse the billing or user-management action when the company needs a different subscription arrangement. Subscription changes are completed in the billing portal, not by changing an employee role.\n\n## Removal and troubleshooting\nPermanent deletion is different from deactivation and is explicitly labelled as permanent in the team workflow. Verify the member carefully before using it. If an access or role update is rejected, confirm you are an active owner or administrator in the correct company and record the error. An employee cannot grant themselves a higher role from their own profile.","route":"/AdminSettings","search_terms":["roles","permissions","active account","deactivate","user limit","seats","delete team"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-team-invites","guide-stripe-and-subscription"],"source_key":"help_articles_portal"},{"slug":"guide-employee-portal","feature_area":"Employee Portal","audience":"all","question":"Find your personal work and HR tools in Employee Portal","answer_short":"Use the field portal on a phone or desktop and understand why a module may be missing.","answer_long":"## What the field portal contains\n**Employee Portal** brings your personal attendance, requests, and assigned work together. The available tabs depend on the company's plan and module settings. The portal requires a plan with HR access; the current upgrade screen identifies **Professional** as the required plan. A Business plan also includes HR access.\n\nEmployees and subcontractors are directed to this portal for field work. Your own records are different from the company's office lists. A blank personal list does not mean every company record is missing; it may mean you have no matching records or assignments.\n\n## Navigate on desktop\nThe left sidebar separates **My Information** from **Operations**. My Information can include **Clock In**, **My Time Sheets**, **My Pay**, **My Time Off**, and **My Expenses**. Operations includes **My Projects**, **My Schedule**, **Project Notes**, **My Tasks**, and **Inventory**. Select the relevant tab to load its content.\n\n## Navigate on a phone\nThe bottom bar shows the first available personal tabs with shorter labels such as **Clock**, **Time Sheets**, **Pay**, and **Time Off**. Select **More** to open the full menu and find Expenses or Operations tabs. Selecting an item closes the menu. Use the close button if you opened More only to look around.\n\n## Understand missing modules\nThe company owner or administrator controls portal modules in **Settings → Employee Portal**. **Time & Attendance** controls Clock In, timesheets, pay views, and time-off requests together. Expenses, daily logs, tasks, and inventory have separate switches. Turning a module off hides its navigation tab. Ask the office to check the plan and switches before assuming your account is broken.\n\n## Work without duplicate entries\nOpen the right tab and review existing history before submitting another timesheet, expense, or material checkout. Wait for the success or error message after saving. On a slow mobile connection, repeated taps can create extra records.\n\n## If a page will not load\nCheck that your login is active and belongs to the correct company. Use Retry where offered, or sign in again if your session expired. The self-service **Profile → Set Up Profile** form is currently incomplete. If it does not save, ask an owner or administrator to use **Settings → Team Management → Edit Team Member** for name, role, hourly rate, or active-account corrections. Ask HR about additional employee information and leave balances. Do not rely on this form as the sole record for emergency contact details.","route":"/EmployeePortal","search_terms":["employee portal","field portal","missing tabs","more menu","professional plan","staff portal"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-clock-in-out","guide-field-assigned-work"],"source_key":"help_articles_portal"},{"slug":"guide-clock-in-out","feature_area":"Timesheets","audience":"all","question":"Clock in, clock out, and review tracked hours","answer_short":"Track a live shift and submit the completed hours to HR without creating duplicate entries.","answer_long":"## Before starting a shift\nOpen **Employee Portal → Clock In**. On a phone the bottom-bar label is **Clock**. The page displays a live local clock, today's date, your current shift state, **Today's Hours**, and **This Week**. It uses your employee identity; if your name or company looks wrong, ask the office to correct the account before recording work.\n\nThe portal's **Time & Attendance** module must be enabled and the company's plan must include HR access. A missing Clock tab can be a company setting rather than a device problem.\n\n## Start and end work\n1. When the card says **OFF THE CLOCK**, optionally enter a note in **What are you working on today? (optional)**.\n2. Select **CLOCK IN** once.\n3. Wait for the success message and confirm the card changes to **CLOCKED IN**, showing the start time.\n4. At the end of the shift, return to this same tab and select **CLOCK OUT**.\n5. Wait for confirmation that your hours have been submitted, then review the shift in **My Time Sheets**.\n\nClocking out records the end time, calculates the elapsed hours, and changes the completed shift to **Pending** for HR review. This is a submitted time record, not payroll approval.\n\n## Understand the totals\nToday's total includes completed hours and elapsed time for a currently active shift. The weekly figure sums recorded total hours for the displayed week, beginning Monday; a live shift's unfinished hours may therefore differ from what you expect in the weekly total. Use the individual time-entry record when checking a discrepancy.\n\n## If you forgot to clock out\nDo not start another shift to compensate for the old one. The screen detects an existing **Clocked In** entry and offers clock-out for it. Tell HR the intended finish time and ask them to adjust the record through **Adjust Timesheet**. If an entire shift was never recorded, use **Submit Missing Hours** instead.\n\n## If an action fails\nRead the error and check the saved state before retrying. The time clock refreshes periodically, but a success toast and matching record are stronger confirmation than a button tap alone. Preserve the date, actual start/end times, and error wording for HR if a correction is needed.\n\n## Missing clock-out alerts\nAn open time-clock session can generate a missing-clock-out reminder after 12 hours. Review the actual start/end times and ask the responsible manager to correct an incorrect record. Do not add a second timesheet solely to silence the alert.","route":"/EmployeePortal?tab=time_clock","search_terms":["clock in","clock out","shift","forgot clock out","attendance","hours"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-missing-timesheets","guide-my-pay"],"source_key":"help_articles_portal"},{"slug":"guide-missing-timesheets","feature_area":"Timesheets","audience":"all","question":"Submit missing hours and understand timesheet statuses","answer_short":"Submit one manual missing shift with date, times, break, project, and notes for HR approval.","answer_long":"## Review existing shifts first\nOpen **Employee Portal → My Time Sheets**. The page shows the last 30 shifts in date order, including recorded start and finish times, total hours, project where available, notes, and the status. A **Manual Entry** badge identifies a manually submitted shift.\n\nCheck this history before adding missing hours. If the shift already exists but has the wrong times, ask HR for an adjustment. The employee form creates a new record; it does not edit or delete an existing shift.\n\n## Submit a genuinely missing shift\n1. Select **Submit Missing Hours**.\n2. In **Submit Missing Shift**, choose the **Date** worked.\n3. Enter **Clock In** and **Clock Out**.\n4. Enter **Unpaid Break (Minutes)** using minutes rather than decimal hours.\n5. Review the calculated **Total Shift**. It must be greater than zero.\n6. Choose **Project**, or **No Project** when appropriate.\n7. Add **Notes to HR** explaining why the shift is being submitted manually.\n8. Select **Submit to HR** and wait for the confirmation.\n\nThe record is saved with the type **Manual** and status **Pending**. Selecting a project associates the shift with that project; it does not create an assignment or a project by itself.\n\n## Understand status and corrections\n**Clocked In** means a shift is still active. **Pending** means the completed or manual shift is awaiting review. **Approved** and **Rejected** reflect HR decisions. An estimate on My Pay can include pending hours, but that does not mean those hours were approved or paid.\n\nIf an entry is rejected or you submitted the wrong date, explain the issue to HR instead of adding a second copy without agreement. HR can use its timesheet adjustment workflow to correct dates, hours, and timestamps.\n\n## Check unusual time ranges\nThe form calculates overnight duration when the finish time is earlier than the start time. It still asks for one shift date, so have HR verify the saved clock timestamps for overnight work. Confirm your device's timezone before entering local times.\n\n## If Submit is disabled or fails\nBoth time fields are required. Check the break amount and positive total. After an error, inspect the shift list before trying again and include the date and expected hours when asking HR for help.","route":"/EmployeePortal?tab=timesheets","search_terms":["missing hours","manual timesheet","break minutes","submit shift","pending","overnight"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-clock-in-out","guide-my-pay"],"source_key":"help_articles_portal"},{"slug":"guide-my-pay","feature_area":"Employee Portal","audience":"all","question":"Read My Pay estimates and explain missing hours or expenses","answer_short":"Understand approved versus pending hours, displayed pay periods, estimates, and approved expense totals.","answer_long":"## What My Pay shows\nOpen **Employee Portal → My Pay**. The content heading is **My Pay & Hours**. This page combines your recorded shifts, an hourly rate from your profile, and approved expense records to show a personal overview. It is an estimate display, not a bank transfer, payslip generator, or confirmation that payroll has been processed.\n\nThe screen displays a current biweekly period and a previous period. These periods are calculated by the application. Compare the dates shown on the screen with your employer's payroll calendar before comparing totals to an actual payslip.\n\n## Check the numbers in a useful order\n1. Read the **Current Period** date range.\n2. Review **Approved** hours separately from pending or active-shift hours.\n3. Open **My Time Sheets** and find any shift you expected to see in that date range.\n4. Check each shift's date, total hours, and status.\n5. Ask HR to confirm the hourly rate assigned to your account if the pay estimate appears wrong.\n6. For expenses, open **My Expenses** and check whether the claim has been approved and falls in the period being displayed.\n\nThe page's notice explains that HR must approve shifts before they are finalized for payroll. Pending hours can be counted in the estimate while awaiting approval. A currently clocked-in shift may not yet have a completed total-hours value.\n\n## Understand calculation limits\nEstimated pay is calculated from recorded hours and the profile hourly rate. The page also displays an overtime-style hours indicator using its own calculation. It does not establish your employer's overtime policy, deductions, tax withholding, holiday rules, or actual pay entitlement. Have HR reconcile those details through the company's payroll process.\n\nApproved expenses in the period can appear in the expense portion of the overview. Their appearance is not evidence that reimbursement has been deposited into your bank account.\n\n## Troubleshooting\nIf hours are missing, check the period dates, approval state, and whether a clock-out was saved. Use the missing-hours form only for an absent shift, not as a way to correct an existing one. If the pay estimate is zero while hours exist, ask an owner or administrator to check the profile's hourly rate. For final payroll or reimbursement questions, contact your own HR or office team with the relevant dates and records.","route":"/EmployeePortal?tab=payroll","search_terms":["pay","payroll","estimated pay","approved hours","hourly rate","reimbursement","pay period"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-missing-timesheets","guide-expense-claims","guide-time-off"],"source_key":"help_articles_portal"},{"slug":"guide-time-off","feature_area":"Employee Portal","audience":"all","question":"Request time off and track the HR decision","answer_short":"Submit a dated absence request, review balances and status, and cancel a pending request.","answer_long":"## Before requesting an absence\nOpen **Employee Portal → My Time Off**. The page shows **Vacation Left**, **Sick Days Left**, **Pending**, and **Request History**. The balance cards use the totals and used-day values stored in your profile. They are a display of configured records, so ask HR to confirm them if they do not match your company's records.\n\nThe Time Off tab is part of **Time & Attendance**. If it is missing, ask the owner or administrator to check the portal's module setting and the company's HR plan access.\n\n## Submit a request\n1. Select **Request Time Off**.\n2. Choose **Absence Type**. Available types include Vacation, Sick Day, Personal Day, and Unpaid Leave.\n3. Enter **First Day Off** and **Last Day Off**, ensuring the last date is on or after the first.\n4. Review the day count shown by the form.\n5. Add an optional reason with enough context for the office to understand the request.\n6. Select **Submit to HR** and wait for the success message.\n7. Find the new record in Request History and check its dates and **Pending** status.\n\nThe day display counts calendar dates inclusively. A Monday-through-Friday range is five calendar days; a range that includes a weekend includes those dates as well. Use your company's instructions for how to request a workday absence and have HR reconcile any different company counting rules.\n\n## Read the outcome\nThe record shows **Pending**, **Approved**, or **Rejected**. An **HR Note** may appear when provided. A submitted request is not permission to take the absence; wait for the company's approval and follow its attendance process.\n\n## Cancel or change a request\nA pending request offers **Cancel Request** with a confirmation. Approved or rejected records do not expose that same cancellation action. For changed dates or an approved absence you no longer need, ask HR to correct the records and explain whether a replacement request is required.\n\n## Troubleshooting\nCheck both dates carefully before saving; do not rely on the displayed day count to catch every date mistake. If a request does not appear after an error, verify the account name and ask HR to check the record before resubmitting. Avoid sending detailed sensitive medical information in an ordinary note.\n\n## Saved identity and decisions\nTime-off requests are saved against your user identity. Use **Cancel Request** for a pending request; its Cancelled record remains in Request History. HR decisions generate the relevant approval/decline alerts. Approved leave is considered when scheduled-work reminders check for a missing daily log or timesheet.","route":"/EmployeePortal?tab=vacation_tracker","search_terms":["vacation","sick day","time off","absence","leave","cancel request","calendar days"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-employee-portal","guide-my-pay"],"source_key":"help_articles_portal"},{"slug":"guide-expense-claims","feature_area":"Employee Portal","audience":"all","question":"Submit expenses, attach receipts, and correct a claim","answer_short":"Create an expense claim with a positive amount, category, payment method, and optional receipt or project.","answer_long":"## Prepare the claim\nOpen **Employee Portal → My Expenses**. Check **Claim History** before creating a new claim so the same receipt is not submitted twice. The **Pending Reimbursement** total combines certain claim statuses; it is not confirmation that money has been transferred.\n\nExpense Tracking must be enabled by the company administrator. Keep the original receipt and use the employer's policy to decide which costs and payment methods are claimable.\n\n## Create an expense\n1. Select **New Claim**.\n2. Enter the purchase **Date** and a positive **Amount ($)**. The form formats the amount to two decimal places.\n3. Choose **Category**: Materials, Fuel, Tools, Meals, Accommodation, Parking, or Other.\n4. Select **Payment Method** such as Personal Card, Cash, Company Card, or Other.\n5. Choose **Project (Optional)** if the purchase belongs to a particular job.\n6. Add a clear **Description** explaining the purchase.\n7. Under **Receipt Document**, select **Snap picture or upload file** and attach an image or PDF if needed.\n8. Wait until the upload finishes and shows **Receipt Attached**, then select **Submit Claim**.\n\nA successful submission is recorded as **Submitted** and sent into the company's review records. It does not automatically mean Approved or Reimbursed.\n\n## Review or correct the claim\nThe history shows category, status, date, amount, description, payment method, project where linked, and **View Receipt** when attached. Claims that are not Approved or Reimbursed expose edit and delete controls. Editing re-submits the claim as Submitted. If an approved or reimbursed claim is wrong, ask HR to handle the correction rather than creating a duplicate without instructions.\n\nOn a phone, some action buttons show icons instead of the full Edit or Delete word. Review the correct row and confirmation carefully.\n\n## Troubleshooting\nA disabled submit button can mean the amount is blank, an upload is running, or a save is already pending. If a receipt upload fails, check the connection and file, then retry the upload before saving. If HR cannot find a newly Submitted claim, ask them to select **All Statuses** in the HR Expenses view; **Pending Only** does not include every expense status. Record the error before retrying a failed save.","route":"/EmployeePortal?tab=expenses","search_terms":["expense claim","receipt","reimbursement","fuel","materials","Submitted","HR expenses"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-my-pay","guide-hr-approvals"],"source_key":"help_articles_portal"},{"slug":"guide-field-assigned-work","feature_area":"Employee Portal","audience":"all","question":"View assigned projects, milestones, and your schedule","answer_short":"Find project details and schedule events tied to your active project staff assignments.","answer_long":"## Where assigned work comes from\nOpen **Employee Portal → My Projects** for the projects assigned to your user account. Open **My Schedule** for schedule events belonging to those assigned projects. These views rely on active project staff assignments; an existing company project alone does not put it in every employee's list.\n\nOn a phone, use **More** to find My Projects and My Schedule in the Operations section. The desktop portal exposes them in the left navigation.\n\n## Read a project\n1. Open My Projects and find the project name.\n2. Review its status and site address.\n3. Check **Start** and **Target completion**. A missing date is displayed as **Not set**.\n4. Read the milestone lines showing the milestone title, current status, and target date where available.\n5. Use My Tasks and Project Notes for your actions and reports relating to that work.\n\nMy Projects is a focused overview. It does not provide the full office project editor or permissions to change a budget, staffing, or project dates.\n\n## Read the schedule\nOpen My Schedule to see event titles, the related project name, start and end times, address, and status. Missing event times display **Not scheduled**. Check the date and local time carefully, especially after travel or a device timezone change. Schedule events and task due dates are separate records; changing task completion does not update the schedule by itself.\n\n## Open an alert about assigned work\nProject or schedule notifications can open a focused portal view. That link may temporarily show only the project or event mentioned by the notification. If the message says **This item is no longer available in your assigned work**, the assignment or event may have changed. Open the normal My Projects or My Schedule tab to review the rest of your work.\n\n## Troubleshooting\n**No assigned work to show** usually calls for an assignment check. Ask the project manager to verify that you were added to project staff under the correct company account and that the assignment remains active. If the page says **Could not load your assigned work**, use **Retry**. If a project appears but an expected event does not, have the manager check the event's project and saved schedule dates. Do not create another login simply to try to find the missing assignment.\n\n## Phases and current plans\nEach assigned project shows **Project phases**, target dates and the prerequisite status when linked. A phase alert can focus the named phase; verify readiness with your manager. **Plans & Elevations** shows the current saved drawing versions. Open or download the file from its card, or use **Show earlier revisions** for history. A plan notification highlights its exact revision, even when superseded, with an earlier-revision warning. Check the latest revision before starting work. This field view does not expose upload or delete actions.","route":"/EmployeePortal?tab=projects","search_terms":["my projects","my schedule","assigned work","milestone","site address","missing project","schedule event"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-field-tasks","guide-field-project-notes","guide-notifications"],"source_key":"help_articles_portal"},{"slug":"guide-field-tasks","feature_area":"Tasks","audience":"all","question":"Read and complete tasks assigned to you","answer_short":"Review task details, priority, project, phase, and due date, then mark the work complete or reopen it.","answer_long":"## Find your task list\nOpen **Employee Portal → My Tasks**. On a phone, open **More** and choose My Tasks from Operations. The portal combines assigned tasks from the application's general and project task lists. Tasks must be assigned to your user identity or matching email to appear here.\n\nThe page separates active **To Do** tasks from **Completed** tasks. An active count appears near the heading. Completed or Done records are treated as finished; other statuses remain in the active group.\n\n## Review the work before changing its status\n1. Find the task title in the appropriate group.\n2. Review its project or phase badge, priority, and due date.\n3. Select **Details**. On smaller screens the action may appear as a document icon.\n4. Read **Task Description** and the other metadata in the dialog.\n5. Complete the actual work and confirm any acceptance steps with the project manager.\n6. Select **Mark Task as Completed**, or use the circle/check control on the task row.\n7. Wait for **Task updated!** and confirm the task moves to the completed group.\n\nMarking a task complete changes its status; it does not submit a timesheet, create an invoice, or approve a project's finances.\n\n## Reopen unfinished work\nIf a completed task needs more work, open its Details and select **Re-open Task as Incomplete**, or use the completed row's check control. This returns it to **To Do**. Tell the manager why it was reopened so the team understands the change.\n\n## Due dates and mobile tables\nAn overdue active task can have red highlighting. The portal displays the due-date value supplied with the task; check any expected deadline with the manager if the date is unclear. Tables can scroll horizontally on a phone to expose project, priority, due date, and actions.\n\n## Troubleshooting\nIf the list says you have no tasks, ask the manager to verify the assignee and company. Being project staff does not automatically assign every task. A notification link can open one particular task's details only if it is still in your available list. If an update fails, preserve the error and review the current status before retrying. Avoid repeated taps while **Updating Status...** is shown.","route":"/EmployeePortal?tab=tasks","search_terms":["my tasks","complete task","reopen task","assignee","overdue","priority","task details"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-field-assigned-work","guide-notifications"],"source_key":"help_articles_portal"},{"slug":"guide-field-project-notes","feature_area":"Daily Logs","audience":"all","question":"Submit project notes with progress photos from the field","answer_short":"Create a dated project note with work completed, issues, safety concerns, materials, and site photos.","answer_long":"## Choose the field workflow\nOpen **Employee Portal → Project Notes**. On a phone the full Operations menu is available under **More**. This personal view shows **My Log History** and the daily field logs submitted by your account. The company must have the Daily Logs & Project Notes module enabled.\n\nUse the separate office **Daily Logs** screen when you need company-wide filtering or notes linked directly to a client or lead. The field Project Notes form requires a project.\n\n## Submit a new note\n1. Select **Submit New Log**.\n2. Confirm the **Date** and choose **Weather**.\n3. Select **Project Location***. A valid project is required.\n4. Enter **Work Completed Today*** with a clear description of the actual progress.\n5. Add **Issues / Delays**, **Safety Concerns**, and **Materials Used** where relevant.\n6. Attach **Site Photos** using the photo upload control. Wait for uploads to finish and inspect the previews.\n7. Submit the note and wait for the confirmation.\n8. Open the saved record's **Details** to verify the text, project, date, and attachments.\n\nUse the note to describe location and work specifically, for example the room or phase affected, the blocker, and the decision needed. Written Materials Used text is a report; it does not perform an inventory checkout. Use the Inventory material-usage workflow when stock needs to be deducted.\n\n## Review and correct a note\nThe history lists date, project, summary, media count, and actions. Details displays the full work summary and any issue, safety, materials, and photo sections. Photos open in a separate view. The personal list has a delete action with confirmation, but it does not offer the office's full edit form. Ask the manager how to correct an important submitted report before deleting and recreating it.\n\n## Troubleshooting\nIf no projects are available, ask the office to confirm the project and your access. A blank project or summary prevents a valid submission. After an upload error, preserve your written text and retry only the missing photos. After a save error, record its exact wording and check history before resubmitting. Urgent safety issues need your company's immediate reporting process as well as a written note; do not depend on a log alone for an urgent response.\n\n## Categorize site events\n**Submit New Log** includes **Log category**: General, Work Completed, Site Issue or Safety. Use **Weather delayed or stopped work** when it applies. These saved fields support routed progress, issue, safety and weather alerts. Managers can acknowledge and resolve a reported issue or safety review in the PM daily-log workflow.","route":"/EmployeePortal?tab=daily_logs","search_terms":["project notes","daily field log","site photos","blockers","safety concerns","materials used"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-field-material-usage","guide-office-daily-logs","guide-field-assigned-work"],"source_key":"help_articles_portal"},{"slug":"guide-office-daily-logs","feature_area":"Daily Logs","audience":"office","question":"Manage office daily logs for projects, clients, and leads","answer_short":"Create, find, inspect, edit, and delete field notes from the company Daily Logs screen.","answer_long":"## Choose the correct log screen\nThe office **Daily Logs** screen is available to users with office or operations access. Employees and subcontractors use **Employee Portal → Project Notes** for their own reports. These two screens have different navigation and form options.\n\nThe office list can display notes related to a **Project**, **Client**, or **Lead**, together with date, author, weather, summary, issue indicators, and media count. Desktop uses a table; mobile uses stacked cards with the same basic actions.\n\n## Create a linked log\n1. Open Daily Logs and select its new-log action.\n2. In **New Field Log / Note**, choose **Date** and **Weather**.\n3. Choose the appropriate **Project**, **Client**, or **Lead** relationship. The form requires at least one relationship before saving and prevents conflicting client/lead choices while another relationship is selected.\n4. Enter **Work Completed / Note***.\n5. Add **Issues / Delays**, **Safety Concerns**, and **Materials Used** when needed.\n6. Upload photos, inspect their previews, and wait for uploading to finish.\n7. Save the log and verify it appears in the list.\n\nProject-linked notes belong to the project record. A sales-site note may instead belong to a client or lead before a project exists. Select the right relationship rather than placing every note under an unrelated project.\n\n## Find and inspect records\nUse **Search descriptions or issues...** to search summaries and blockers. Use **All Projects** to narrow the project view. Pagination controls move through the matching results. Selecting the document/details icon opens the full log, including text and attached photos.\n\n## Correct or remove a note\nUse the pencil action to open **Edit Log**, make the intended changes, save, and reopen Details to check the result. The delete action asks for confirmation and removes the selected log. Review author, date, and relationship carefully before deleting.\n\n## Troubleshooting\nIf **No logs found** appears, clear the search and reset the project filter before concluding the data is absent. If Save is disabled, ensure the note and a project/client/lead relationship are present and no upload is running. Text in Materials Used does not deduct warehouse stock; an inventory transaction is a separate action. Preserve errors and check the list before retrying a failed save.","route":"/DailyLogs","search_terms":["daily logs","field note","edit log","lead note","client note","photos","filter logs"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-field-project-notes","guide-field-material-usage"],"source_key":"help_articles_portal"},{"slug":"guide-field-material-usage","feature_area":"Inventory","audience":"all","question":"Log materials taken from the warehouse and correct a checkout","answer_short":"Record inventory consumption, associate it with a project, and inspect or refund a recorded checkout.","answer_long":"## What this inventory screen does\nOpen **Employee Portal → Inventory**. The content heading is **Material Usage**, with **Checkout History** underneath. This workflow records stock taken from company inventory and deducts the quantity from the warehouse item. Reusable tools use **My equipment** on the same page. Material consumption is separate from daily-log descriptions and purchase orders.\n\nThe company must enable Inventory Checks for the portal. Check the material name, unit, and current stock before entering a quantity; a unit such as feet, sheets, or each changes what the number means.\n\n## Log materials taken\n1. Select **Log Material Taken**.\n2. In **Log Materials Taken**, choose **Warehouse Material*** from company stock.\n3. Enter a positive **Quantity Taken*** using the item's unit.\n4. Review the displayed **Remaining** stock.\n5. Select **Project (Optional)**, or **Shop / Unassigned** where appropriate.\n6. Add **Notes / Where used?** with the location or purpose.\n7. Select **Log Checkout** once and wait for confirmation.\n8. Review the new Checkout History row and the warehouse balance.\n\nThe application saves the stock deduction and your named usage record together. The server rejects insufficient warehouse stock, invalid quantities and projects you cannot access. A negative displayed Remaining value is a reason to correct the quantity; it does not authorize taking more stock than is available.\n\n## Inspect and correct a checkout\nOpen the row's **Details** to check the timestamp, material, quantity, project and notes. After returning the recorded materials or confirming a correction with the office, select **Return materials to stock**. It restores that usage quantity once and keeps the original record marked **Returned to stock**. Repeating the return cannot add stock again. You can return only your own saved usage record. Older name-based records remain read-only; ask the office to verify their balance.\n\n## Troubleshooting\nA missing-company message calls for checking your account and signing in again. A missing warehouse item should be corrected by the office before you submit usage. If a save fails, check Checkout History and the stock balance before retrying. Wait for the outcome before another submission; a separate new checkout records another consumption. If Details says an item is unknown or deleted, use the transaction date, project, and notes to help the office identify the original material.","route":"/EmployeePortal?tab=inventory","search_terms":["material usage","warehouse","checkout","consume stock","quantity taken","refund stock","remaining inventory"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-field-project-notes","guide-employee-portal"],"source_key":"help_articles_portal"},{"slug":"guide-hr-approvals","feature_area":"HR","audience":"office","question":"Review and approve timesheets, time off, and expense claims","answer_short":"Use HR filters and bulk actions, adjust a time entry, and find claims hidden by status filters.","answer_long":"## Who uses Human Resources\n**Human Resources** is available to owners, administrators, and office staff when the company plan includes HR. The current upgrade screen identifies Professional as the required plan. Managers and field users use their own permitted areas; a manager role does not automatically include this HR route.\n\nDesktop offers **Employee List**, **Timesheets**, **Time Off**, and **Expenses** across the top. On mobile, choose the same view through the dropdown. Time-related and expense views can be hidden by the company's portal feature settings.\n\n## Review a queue\n1. Choose the correct HR view.\n2. Set the status selector to **Pending Only**, **Approved Only**, or **All Statuses**.\n3. Select **All Employees** or the individual employee.\n4. Choose **Daily**, **Weekly**, or **All Time**. Use date controls when reviewing a day or week.\n5. Inspect dates, hours or amounts, type, status, and receipt where provided.\n6. Tick the records you intend to decide, or use **Select All** for the current displayed list.\n7. Select **Approve (count)** or **Reject**, then confirm the records now show the intended status.\n\nSelecting all applies to the filtered displayed list. Review the employee, date, and selected count before a bulk action so another person's records are not unintentionally included.\n\n## Find newly submitted expenses\nEmployee expense claims are saved as **Submitted**. The HR **Pending Only** filter checks Pending or blank statuses, so a Submitted claim can be absent from that view. Choose **All Statuses** and the correct employee/date range to locate it. A lack of Pending results does not prove no claims were submitted.\n\n## Adjust a timesheet\nIn Timesheets, select **Adjust** on the relevant row. **Adjust Timesheet** exposes Date, Total Hours, Clock In Time, Clock Out Time, Type, Status, and **Admin Notes / Overrides**. Check the actual hours and timestamps together, explain the correction, and select **Save Adjustment**.\n\n## Troubleshooting\n**All caught up!** means no records match the current filters. Reset employee, status, and date filters before escalating. Approval updates records; it does not issue wages or reimbursements. If a write is rejected, check role permissions and preserve the error. Avoid adding a second employee submission as a workaround for an existing record that needs adjustment.\n\n## Older time-off records\nIf an older request cannot be matched to one employee, use **Link employee before approval** and verify the correct employee before deciding it. Known employee identities cannot be reassigned. Review management-hour entries through the normal timesheet approval process.","route":"/HumanResources","search_terms":["HR","approve timesheets","approve expenses","time off","adjust timesheet","Pending Only","Submitted"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-hr-directory-and-exports","guide-expense-claims","guide-missing-timesheets"],"source_key":"help_articles_portal"},{"slug":"guide-hr-directory-and-exports","feature_area":"HR","audience":"office","question":"Use the HR employee directory, hourly rates, and CSV exports","answer_short":"Find an employee, review their recorded work, and export the filtered HR view for reconciliation.","answer_long":"## Open the employee directory\nOwners, administrators, and office staff can open **Human Resources** on a plan with HR access. Select **Employee List** to browse the company's employee directory. The list combines account and profile records and displays the available name, email, and role information.\n\nUse the search field to find an employee by name or email, then select the employee to open their detail panel. Check that you selected the correct person before reviewing their hours or updating a rate.\n\n## Understand hourly-rate access\nThe employee detail panel shows an hourly rate and an Edit control. Changes to account profile fields such as hourly_rate are restricted by company security rules; owners and administrators should perform rate updates. Office staff may review HR but should ask an owner or administrator to save an account-rate change when a write is blocked.\n\n1. Select the employee.\n2. Open the hourly-rate Edit control.\n3. Enter the intended numeric rate.\n4. Save and wait for the success message.\n5. Reopen the record and check the saved value.\n\nThis rate feeds the employee's My Pay estimate. It does not independently run payroll, apply deductions, or change the cost of every labour item in a pricebook. Pricebook labour cost and a person's hourly pay rate are different records.\n\n## Export the view you actually need\nSwitch to **Timesheets**, **Time Off**, or **Expenses**. Apply employee, status, and date filters before selecting **Export CSV**. The export uses the displayed filtered data for that HR view, with fields relevant to its records. For example, timesheets include the employee and shift details, while expenses include expense values.\n\nThe Export CSV button is hidden on the smallest phone layout. Use a wider device or desktop when you need the download action. Keep the exported date range and status filters with the file so a later reviewer knows what it contains.\n\n## Troubleshooting and reconciliation\nIf the directory has an unexpected name or duplicate-looking records, compare emails and ask the administrator to reconcile membership before editing. If an export looks incomplete, reset filters to All Statuses, All Employees, and All Time, then narrow them again deliberately. A downloaded HR file is a snapshot of records; payroll and reimbursement decisions remain part of the employer's separate process.","route":"/HumanResources","search_terms":["employee directory","hourly rate","HR export","CSV","pay rate","employee list"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-hr-approvals","guide-my-pay","guide-team-access-and-seats"],"source_key":"help_articles_portal"},{"slug":"guide-company-branding","feature_area":"Settings","audience":"admin","question":"Set your company identity, logo, and PDF brand styling","answer_short":"Save company contact details separately from PDF colour and price-visibility settings.","answer_long":"## Open Branding & PDFs\nOwners and administrators can open **Settings → Branding & PDFs**. Managers do not see this section. The page contains **Company Identity** and **PDF Document Styling**, with separate save buttons. Saving one section does not replace the need to save the other.\n\nUse company-approved contact details and a clear logo suited to document headers. These settings represent your business identity within generated documents; the application itself retains FuzedFlow's general theme.\n\n## Save company identity\n1. Under Company Identity, choose **Upload Logo** and select an image if needed.\n2. Wait for the upload to finish and check the logo preview.\n3. Enter **Company Name***.\n4. Check **Phone Number**, **Email Address**, and **Website**.\n5. Set **Physical / Billing Address** using the address field.\n6. Select **Save Identity** and wait for **Settings saved successfully**.\n\nThe logo upload saves the company's logo separately when the upload succeeds. If the preview does not change, do not assume the file was stored; read the upload error and retry only after checking the file and connection.\n\n## Save PDF styling\n1. Under PDF Document Styling, choose **Primary Brand Color** using the colour picker or the colour value field.\n2. Set **Show Item Quantities & Prices** to suit how much detail clients should see.\n3. Set **Show Phase/Category Totals**.\n4. Select **Save PDF Settings**.\n5. Generate or preview a representative document and confirm the result before sending it to a client.\n\nHiding quantities or phase totals affects presentation; it does not remove the underlying estimate values. Quote-specific PDF customization may also provide document-level options, so compare the exact document preview rather than relying on a settings value alone.\n\n## Troubleshooting\nChanges still sitting in a field are not saved until the correct button succeeds. If company details look unchanged after navigation, return to the section and inspect saved values. If an upload or save is blocked, verify that you are an owner or administrator in the intended company and record the error. Use a valid colour value and a supported image file. Keep a sample PDF from before and after a styling change when investigating inconsistent document appearance.","route":"/AdminSettings","search_terms":["branding","company logo","PDF colour","brand color","company identity","hide prices"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quote-default-text","guide-message-templates"],"source_key":"help_articles_portal"},{"slug":"guide-quote-default-text","feature_area":"Settings","audience":"office","question":"Set default quote introduction, client message, and terms","answer_short":"Configure the default text used when creating new quotes and verify each quote before sending.","answer_long":"## Choose company quote defaults\nOwners, administrators, and managers can open **Settings → Quote Customization**. This section sets text that pre-fills when building a new quote. It does not create a quote, approve a quote, or automatically rewrite every existing document.\n\nThe three text areas serve different places in the document. **Default Executive Summary / Intro** is the project introduction. **Default Client Message** is a personal note before the pricing breakdown. **Default Terms and Conditions** is the terms text shown toward the bottom of the quote.\n\n## Update the defaults\n1. Open Quote Customization.\n2. Enter **1. Default Executive Summary / Intro** with a company-approved introduction that can be adapted to each job.\n3. Enter **2. Default Client Message** with a clear instruction about reviewing the proposal.\n4. Enter **3. Default Terms and Conditions** using the company's approved payment, scope, and other terms.\n5. Select **Save Defaults** and wait for the success message.\n6. Create a new quote and inspect the pre-filled text before adding client-specific details.\n7. Preview the final quote or PDF before sending it.\n\nAvoid placing project-specific dates, client names, or unusual guarantees in a company default unless every new quote should contain them. The defaults provide a starting point; each quote still needs a review against its actual scope and commercial agreement.\n\n## Keep text settings separate\nQuote Customization controls document text. **Message Templates** controls the bodies of outbound communications. **Branding & PDFs** controls company identity and some PDF presentation options. Changing document text does not automatically update communication templates. The quote terms and invoice payment-term default currently share a saved company value; after changing either section, check both a new quote’s terms and a new invoice’s due-date/default-term selection before sending.\n\nWarranty wording in terms is descriptive contract text. It does not activate a separate warranty-claims workflow. Similarly, referring to approval or signing in your terms does not create a general document-signature feature for all uploaded files.\n\n## Troubleshooting\nIf a new quote appears to use old wording, return to Settings and verify that Save Defaults succeeded, then inspect the quote's own text fields. Existing quotes can preserve their own saved values. If the Settings page is unavailable, check the role with an owner or administrator; office staff do not have access to the main Settings route. If a save fails, preserve your edited wording elsewhere temporarily and record the error before leaving the page.","route":"/AdminSettings","search_terms":["quote defaults","executive summary","client message","terms conditions","default intro"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-message-templates","guide-company-branding"],"source_key":"help_articles_portal"},{"slug":"guide-message-templates","feature_area":"Settings","audience":"office","question":"Customize email and SMS templates with safe tokens","answer_short":"Edit document communications and use Insert buttons for client names, numbers, and sender details.","answer_long":"## What Message Templates controls\nOwners, administrators, and managers can open **Settings → Message Templates**. The page provides communication text for quotes, invoices, change orders, and purchase orders, plus a company email signature. These are shared defaults used by the relevant dispatch workflow; saving a template does not send a message.\n\nQuotes, invoices, and change orders have **Email Body** and **Text Message (SMS)** fields. Purchase orders use an email body. The **Email Signature** is appended to outbound dispatch email where that workflow supports it.\n\n## Edit safely\n1. Choose the document's template section.\n2. Place the cursor where a dynamic value should appear.\n3. Use the small **+ Insert** token buttons instead of typing placeholder punctuation manually.\n4. Add clear surrounding text, leaving document links to the appropriate dispatch workflow rather than inventing a link.\n5. Repeat for SMS if your company uses text delivery.\n6. Review the company signature.\n7. Select **Save All Templates** and wait for confirmation.\n8. Check the next actual draft or dispatch preview before sending it to a client or vendor.\n\nQuote tokens include Client Name, Quote #, and Quote Title. Invoice tokens include Client Name, Invoice #, and Balance Due. Change orders include Client Name and CO #. Purchase orders include Vendor Name and PO #. Signature tokens include My Name (Sender) and Company Name.\n\n## Understand the token syntax\nA placeholder such as `{{client_name}}` is replaced with the relevant record value by the workflow. Changing or deleting its braces can leave literal placeholder text in a message. The Insert buttons add the supported token at your cursor position and reduce these errors.\n\nKeep SMS wording short enough to be useful on a phone, and make the document and next action clear. Your wording should match the workflow that is actually available; an email template cannot enable a missing general signature or payment capability.\n\n## Troubleshooting\nIf a client receives a raw placeholder, compare it with the supported token and the source record, then correct the template. If the wrong number or recipient appears, review the document and contact details as well as the template. An email/SMS switch, saved template, or success saving settings does not prove delivery. Use the relevant document send result and preserve any dispatch error. Office staff should ask a permitted manager or administrator for template changes.","route":"/AdminSettings","search_terms":["email template","SMS","tokens","client_name","email signature","dispatch wording"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quote-default-text","guide-alert-and-automation-settings","guide-support-and-ai"],"source_key":"help_articles_portal"},{"slug":"guide-regional-financial-settings","feature_area":"Settings","audience":"office","question":"Configure timezone, currency, margins, and tax labels","answer_short":"Save regional display and financial defaults, then check the exact quote or invoice calculation.","answer_long":"## Open Regional & Financial\nOwners, administrators, and managers can use **Settings → Regional & Financial**. This section stores company defaults for timezone, date formatting, currency, target margin, and tax details. It is a configuration screen; it does not decide which tax laws apply to a particular business or transaction.\n\nUse your company's approved values and confirm them against the documents you generate. Some screens have their own display or calculation behaviour, so a saved setting alone is not proof that every historic record changed.\n\n## Set regional values\n1. Choose **System Timezone** from the available options.\n2. Select **Date Format**, such as a readable month-name format, month/day/year, day/month/year, or year-month-day.\n3. Select **Base Currency**. The menu offers CAD, USD, GBP, EUR, and AUD.\n4. Review **Target Profit Margin**.\n5. Continue to the tax sections before saving the page.\n\nCurrency is a company default and display choice; changing it is not a currency conversion service for existing prices. Keep an eye on explicit currency labels in reports and HR screens when comparing amounts.\n\n## Configure taxes\nUnder **Primary Tax**, set **Tax/Business Number**, **Display Label**, and **Rate**. If the company needs a second tax, enable **Secondary Tax**, then set its optional number, label, and rate. Labels such as GST, HST, VAT, PST, or QST are examples of names; use the correct approved label and rate for your company's documents.\n\nSelect **Save Regional Settings** and wait for the success message. Open a representative quote or invoice to inspect the displayed currency, tax label, rate, and total. Confirm the document's taxable items and its own tax settings where available.\n\n## Understand margin separately from pay rates\nThe target margin is a financial default for pricing. An employee's hourly pay rate is managed in their account profile through the permitted team/HR workflow. Product labour and material costs are managed in the pricebook. These values are related in business use but are not the same setting.\n\n## Troubleshooting\nIf a tax looks wrong, check the saved company setting and the specific document before changing it again. Existing documents can retain saved values. If time appears wrong, compare device timezone with the document's stored dates and times. After a failed save, preserve your intended values and the error rather than assuming the changes took effect.","route":"/AdminSettings","search_terms":["timezone","currency","tax","GST","PST","margin","date format","financial settings"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quote-default-text","guide-hr-directory-and-exports"],"source_key":"help_articles_portal"},{"slug":"guide-portal-module-settings","feature_area":"Settings","audience":"admin","question":"Control which Employee Portal modules staff can see","answer_short":"Owners and administrators can enable attendance, expenses, daily logs, tasks, and inventory modules.","answer_long":"## Who can change field modules\nOwners and administrators manage this in **Settings → Employee Portal**. Managers do not see the Employee Portal settings section. The company must have a plan with HR access; otherwise this section shows an upgrade wall rather than module controls.\n\nThese switches control which portal navigation tabs are visible to field workers on desktop and mobile. They are company settings, not personal preferences. Consider the work your staff need to complete before hiding an active workflow.\n\n## Review the switches\n**Time & Attendance** enables Clock In/Out, timesheets, pay views, and vacation requests together. **Expense Tracking** exposes receipt uploads and expense claims. **Daily Logs & Project Notes** exposes field reports and progress photos. **Task Assignments** exposes assigned tasks and completion controls. **Inventory Checks** exposes warehouse/material-usage access.\n\nMy Projects and My Schedule are separate assigned-work views and remain available in the portal navigation. Company assignments and saved records determine what those views contain.\n\n## Save a module change\n1. Open Settings and choose Employee Portal.\n2. Review **Active Modules**.\n3. Turn the intended module on or off.\n4. Select **Save Module Settings**.\n5. Wait for confirmation before leaving the page.\n6. Ask a staff member with the appropriate role to refresh their portal and verify the intended tab is visible or hidden.\n\nDisabling a module hides the tab; it does not mean existing time entries, expenses, tasks, or inventory transactions were deleted. Re-enabling the navigation does not create records or assignments for staff who have none.\n\n## Explain missing tabs to staff\nA phone shows only the first personal tabs in its bottom bar, so ask staff to check **More** before concluding a module is disabled. Then check the saved switch, plan access, active account, and company membership. For assigned tasks and projects, also check the relevant assignee or project-staff record.\n\n## Troubleshooting\nIf a change does not persist, return to the section and check whether the save succeeded. Use the correct company account and record any permission or network error. Module visibility is not a substitute for database permissions: a hidden tab should not be treated as the only access control. Avoid turning off attendance while staff have active shifts without arranging how they will complete those records.","route":"/AdminSettings","search_terms":["employee modules","enable time clock","missing portal tab","feature toggles","attendance","portal settings"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-employee-portal","guide-team-access-and-seats"],"source_key":"help_articles_portal"},{"slug":"guide-client-portal-settings","feature_area":"Settings","audience":"office","question":"Configure the client portal welcome message and visible modules","answer_short":"Manage portal visibility settings and check a real client view before relying on the change.","answer_long":"## Open the portal configuration\nOwners, administrators, and managers can use **Settings → Client Portal**. The section stores company preferences for portal activity, a welcome message, and visible client modules. These settings are separate from the employee portal and from your staff's company roles.\n\nUse the client portal to expose the documents and content appropriate for that client. A company setting does not create a client record, send an invitation, or grant a client access to every company document.\n\n## Set the intended visibility\n1. Open Client Portal settings.\n2. Review **Enable Client Portal**.\n3. Enter the **Custom Welcome Message**.\n4. Under **Visible Modules**, review **Quotes Tab**, **Change Orders Tab**, **Invoices Tab**, **Documents Tab**, and **Portfolio Tab**.\n5. Enable the modules your company intends to offer.\n6. Select **Save Portal Settings** and wait for confirmation.\n7. Open the relevant client portal using its approved access path and check the actual tabs and records shown.\n\nThe settings labels describe quotes, change orders, invoices, attached quote documents, and portfolio photos. The complete client experience also depends on the page version and the saved records available to that client. If a tab still appears after changing the configuration, inspect the actual portal rather than assuming the switch was enforced everywhere.\n\n## Keep client actions distinct\nShowing a quote or invoice tab is different from approving a quote or collecting an invoice payment. Those actions require the appropriate document and workflow. A **Documents** tab means viewing or downloading available attachments; it does not create a universal electronic-signature workflow for uploaded documents.\n\nHiding a module is a visibility preference. It does not delete the underlying company documents. A welcome message is ordinary text, so avoid including confidential company details or promises that the application cannot fulfill.\n\n## Troubleshooting\nIf a client sees no records, check the client association and the document's availability as well as module settings. If the welcome message does not change, verify Save Portal Settings succeeded and reload the actual client view. Office staff cannot open the main Settings route and should request changes from a permitted manager or administrator. For access errors, preserve the page name and error and ask the office to verify the specific client's access rather than sharing another client's link.","route":"/AdminSettings","search_terms":["client portal settings","welcome message","visible modules","documents tab","portfolio tab"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-message-templates","guide-quote-default-text"],"source_key":"help_articles_portal"},{"slug":"guide-stripe-and-subscription","feature_area":"Settings","audience":"admin","question":"Connect client payments and manage your FuzedFlow subscription","answer_short":"Distinguish Stripe client-payment onboarding from subscription billing and save invoice-term defaults.","answer_long":"## Two different payment relationships\nCompany owners and administrators use **Settings → Payments** to configure client-payment collection. **Manage Subscription** in the Settings navigation opens the company's FuzedFlow subscription billing portal. These actions serve different purposes: client payments flow to your business, while the subscription pays for your FuzedFlow account.\n\nManagers do not see the Payments settings section or the administrator billing panel. Keep your company and bank details ready before starting external onboarding.\n\n## Link the company payment account\n1. Open Settings → Payments.\n2. In **FuzedFlow Payments**, select **Link Bank Account** when the account is not linked.\n3. Wait for the secure Stripe onboarding redirect.\n4. Complete the required details in the Stripe flow.\n5. Return to FuzedFlow and review the connection state.\n\nThe settings screen displays **Account Active** when the company has a linked Stripe account identifier and offers **View Stripe Dashboard**. Review any remaining onboarding or payout requirements in Stripe; a stored connection indicator alone does not guarantee that every payment or payout is ready.\n\n## Set invoice defaults\nUnder **Invoicing Defaults**, choose **Default Payment Terms**: Due on Receipt, Net 15 Days, Net 30 Days, or Net 60 Days. Select **Save Payment Settings**. Check the next invoice's actual due date before sending it; the default is a starting value for new work, not a mass update of every existing invoice. Quote terms and this invoice-term default currently use a shared company value, so check a new quote’s Terms and Conditions after saving payment terms as well.\n\n## Manage the application subscription\nSelect **Manage Subscription** from the owner/admin Settings panel. The application requests a billing-portal session and redirects to the returned portal. Complete any subscription change there and confirm the company state after returning. Team seat limits are company subscription settings, not employee-role values.\n\n## Current QuickBooks availability\nThe Settings panel can show **Connect QuickBooks**, but its current action says **Coming soon!**. Do not expect a live QuickBooks connection or accounting sync from that button, even if old company metadata makes the button's wording look connected.\n\n## Troubleshooting\nIf onboarding or billing fails, check that your session is active and record the exact error. Do not create repeated payment accounts as a workaround. Confirm the intended company and distinguish a client's unpaid invoice from a failed FuzedFlow subscription charge before seeking help.","route":"/AdminSettings","search_terms":["Stripe","link bank account","manage subscription","billing","payment terms","QuickBooks coming soon"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-team-access-and-seats","guide-regional-financial-settings"],"source_key":"help_articles_portal"},{"slug":"guide-notifications","feature_area":"Notifications","audience":"all","question":"Use the notification bell, filters, and action-only preference","answer_short":"Find role-specific alerts, open related work, mark the current view read, and troubleshoot a missing alert.","answer_long":"## Open your notification feed\nSelect the **notification bell** in the top navigation. The badge shows your unread count, with 99+ used for larger counts. Notifications are scoped to your company, user account, role, and assigned work. Another colleague can receive a different alert for the same event.\n\nThe feed opens in **Unread**. Filters include **All**, **Mentions**, **Projects**, **Financial**, and **Action Required**. Use horizontal scrolling on a small phone if a filter is outside the visible row.\n\n## Review and open alerts\n1. Select the relevant filter.\n2. Read the title, body, severity badge, category, and event time.\n3. Select an alert to mark it read and open the related work where an **Open →** destination is available.\n4. Use **All** to find previously read alerts.\n5. Use **Previous** and **Next** when additional pages are available; each page contains up to 30 records.\n\nA read alert disappears from Unread but remains eligible for All. **Mark this view read** applies to unread records matching the current view; it is not a delete action and is not an approval of the underlying work.\n\n## Check action-only mode\nOpen the gear button labelled **Notification settings**. **Notify me only when action is required** hides Important and FYI updates across the feed and unread count. Turn it off to see those updates again. Even **All** is narrowed while this preference is on.\n\n## Understand new lead alerts\nA newly created lead produces an **Action Required** office/operations alert for eligible owners, administrators, managers, and office staff with Leads access. The creator is included when eligible. Employees and subcontractors do not receive general company lead alerts. Action-only mode should not hide this creation alert. Check the saved lead, role, Leads access, and All filter before concluding that creation failed.\n\n## Troubleshooting\nUse **Retry** when the feed reports a loading error. The feed supports realtime updates and also refreshes periodically, so reopen it or refresh if needed. The notification bell is an in-app feature; an alert there does not prove a phone lock-screen push, SMS, or email was delivered. Field alerts can open a focused Employee Portal record; if that work was removed or reassigned, ask the manager to verify current availability.\n\n## Personal delivery and wording\nOpen the bell's settings for **My notifications**. In-app begins on; instant email, SMS, device push and email digests begin off and need explicit opt-in and working provider/device setup. Choose categories, quiet hours and daily/weekly summaries, then save. Alerts now describe the saved actor, action, record and date; scheduled reminders use a system identity. Read the personal-notification-delivery guide for device installation, contact-format and delivery troubleshooting.","route":"/EmployeePortal","search_terms":["notifications","bell","unread","all","action required only","missing lead alert","phone push"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-alert-and-automation-settings","guide-field-assigned-work","guide-field-tasks"],"source_key":"help_articles_portal"},{"slug":"guide-alert-and-automation-settings","feature_area":"Settings","audience":"office","question":"Set document alert preferences and follow-up schedules","answer_short":"Save supported communication preferences and automation schedules without assuming delivery is guaranteed.","answer_long":"## Keep three kinds of setting separate\nThe personal notification bell has its own action-only preference. **Settings → Notifications** stores company document-alert email/SMS choices. **Settings → Automations** stores follow-up timing. A saved switch or schedule is configuration; it is not proof that a particular email or text was delivered.\n\nOwners, administrators, and managers can open these Settings sections. Office staff should request changes through a permitted manager or administrator.\n\n## Configure document alerts\n1. Open Settings → Notifications.\n2. In **Alert Preferences**, review quote, invoice, change-order, and purchase-order event rows.\n3. Set the available **Email** and **SMS** switches for the intended events.\n4. Select **Save Preferences** and wait for confirmation.\n5. Verify the actual next relevant document event and its send result.\n\nQuote events include **Quote Viewed**, **Quote Approved**, and **Changes Requested**. Invoice events include viewed and paid actions. Change-order preferences are gated by the plan; a Professional plan or higher provides the relevant access. These switches are distinct from the notification bell's role-based in-app feed.\n\n## Configure follow-up timing\nOpen Settings → Automations. Quote follow-ups have **First Check-in** and **Final Push** timing. Invoice reminders expose **Pre-Due Reminder**, **Late Notice #1**, and **Late Notice #2**. Change-order automation exposes an **Urgent Check-in** and is plan-gated. Set the available enable switches and day values, then select **Save Automations**.\n\nMatch timing to your business process and check the document's saved status and dates before expecting a reminder. The settings page describes pausing follow-ups after relevant completion actions, but a stored schedule still depends on the running delivery workflow. Do not repeatedly send a manual reminder without checking whether one was already delivered.\n\n## Troubleshooting\nIf a reminder is absent, check the saved switch, timing, document state, recipient contact information, and any dispatch error. If the bell is empty, check its All filter and action-only preference; email/SMS switches are a different layer. A change-order upgrade warning indicates plan access, not a missing document. Capture the document number, expected event, date, and error when asking support to investigate delivery. Never treat a phone icon or SMS preference as confirmation of browser or lock-screen push notifications.","route":"/AdminSettings","search_terms":["alert preferences","SMS","email alerts","automation","follow up","reminder","save preferences"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-notifications","guide-message-templates","guide-stripe-and-subscription"],"source_key":"help_articles_portal"},{"slug":"guide-support-and-ai","feature_area":"Help & Support","audience":"all","question":"Use help articles, AI Help, and contact support effectively","answer_short":"Find written instructions, ask a specific AI question, follow article sources, or prepare a support email.","answer_long":"## Start with the written help\nOpen the **Help** menu in the top navigation and choose **Help Articles** for detailed instructions and troubleshooting. The **Knowledge Base & FAQ** provides shorter answers where available. Search using the page name, action, or exact error instead of only a broad word such as “problem.” Articles you can access are filtered for your role.\n\nUse the guide's steps and troubleshooting section to check prerequisites, saved status, and permissions. A feature described as coming soon or incomplete has no completed workflow to unlock by repeated clicking.\n\n## Ask AI Help a useful question\n1. Select the yellow AI Help button.\n2. Name the page and the action you are trying to complete.\n3. Include the relevant status or error, without passwords or full payment details.\n4. Send the question and read the formatted answer.\n5. Open its **Related help** article links to review the source instructions and limitations.\n\nAI Help uses the shared help content and the page context. It explains the documented workflow; an answer is not confirmation that the app performed an action, changed a record, sent a message, or approved a document. Review the actual application's saved result when completing the steps.\n\n## Prepare a support request\nOpen **Contact support** from Help or AI Help. Enter **Subject** and **Message**, then select **Open email app**. This creates a draft addressed to **support@fuzedflow.com**. Review it and select **Send** in your email application. The website does not submit a support ticket or send the email itself.\n\nIf no email application opens, use **Copy email address** and compose the message manually. The page also lists **1-855-400-3000** and support hours of Monday–Friday, 8 AM–5 PM Mountain Time.\n\n## Include enough information\nDescribe the company, page, attempted action, relevant document or record identifier, approximate time, and exact error. State what you already checked. A screenshot can help if it excludes sensitive information. Never send login passwords or card numbers.\n\n## Availability and troubleshooting\nVideo Tutorials currently displays **Coming Soon** rather than playable lessons. Use written articles and AI Help for current guidance. If AI reports an expired session, sign in again. If it cannot connect, the help portal and Contact support remain available. Verify you actually sent the prepared email before waiting for a reply.\n\n## Track a support request\nThe **Contact** page supports a saved ticket and its message history. Submit the issue from the actual page with a concise title, description and relevant record reference. Keep private customer access tokens, passwords and payment details out of the message. A support reply can create an alert and appears in the ticket history. Ticket status and a queued request email are separate from confirmation that a person has resolved the issue.","route":"/Contact","search_terms":["help articles","AI help","support email","contact","email draft","tutorials","related help"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-account-sign-in","guide-notifications"],"source_key":"help_articles_portal"},{"slug":"guide-personal-notification-delivery","feature_area":"Notifications","audience":"all","question":"Choose personal notification channels, quiet hours and summaries","answer_short":"Use My notifications to choose your own in-app, email, SMS, device push and digest preferences. Your role and assigned work still determine which events you receive.","answer_long":"## Open your own preferences\nOpen the notification bell and choose its settings or gear button. Owners and administrators can also open **Admin Settings → Notifications → My notifications**. These settings belong to your account. They do not enable external alerts for every person in your company.\n\n## Choose channels and categories\n1. Keep **In-app** enabled to see routed updates in the bell. It starts enabled.\n2. Enable **Instant email** if you want individual eligible updates at your saved account email.\n3. Enable **SMS text messages** only if you want texts. Enter **My mobile number** with its country code, such as the international +1 format for Canada or the United States.\n4. Use **Device push notifications** and **Connect this device** to request browser permission for the phone or computer you are using.\n5. Choose the categories you want, then select **Save my preferences**.\n\nExternal channels and digests start off. Delivery needs the platform's configured provider, scheduled dispatcher, supported device and your permission; a saved switch alone does not prove that a message was delivered. Contact support if an opted-in channel remains unavailable.\n\n## Device push on phones\nOpen Fuzed Flow over HTTPS in a supported browser. On iPhone or iPad running iOS/iPadOS 16.4 or later, add the app to your Home Screen and open the installed app before connecting push. Follow the device's permission prompt. On other supported devices, follow the browser's installation and permission controls where offered. The browser can deny or revoke permission. **Disable on this device** removes this device's subscription; signing out also removes it. Connect each device separately.\n\n## Quiet hours and summaries\nEnable **Quiet hours for email, SMS and push**, choose start/end times and your timezone, then save. This delays external personal alerts during that period while retaining the in-app history.\n\nChoose **Email digest → Daily summary** or **Weekly summary**. Set **Send after**, and choose **Day** for weekly summaries. Digest email is separate from the Instant email setting and includes future eligible updates after opting in. Category choices apply to summaries too. Returning the digest setting to Off stops future summaries.\n\n## Troubleshooting\nCheck the correct company/account, your role, assignment, category choices, Action Required-only filter, device permission and quiet hours. Company document alerts and the email dialog's **Send me a copy** are separate company-address workflows. Do not change company contact settings to troubleshoot your personal device.","route":"/EmployeePortal","search_terms":["phone notifications","push","sms","email alerts","quiet hours","daily digest","weekly digest","my notifications"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-warranty-claims","feature_area":"Warranty","audience":"all","question":"Create, assign and resolve warranty claims","answer_short":"Track warranty intake, assigned responsibility, response deadlines, repair visits and customer confirmation. Share a private expiring link when the customer needs to submit or update a claim.","answer_long":"## Open warranty work\nOpen **Warranty** from company navigation. Owners, administrators, permitted office staff and project managers can manage accessible claims. Assigned field staff can read their assigned claim and add an update; that access does not grant control of other company claims.\n\n## Record and assign a claim\n1. Select **New claim** and choose the project.\n2. Enter **Claim title** and **Issue details**. Customer identity defaults from the project's saved client; review any entered contact corrections.\n3. Choose **Priority**, **Assigned team member** and **Response deadline**.\n4. Set **Repair visit** when a visit has been arranged, then select **Save claim**.\n5. Select the claim to read its details and **Claim history**. The saved actor and date are retained for lifecycle changes.\n\nThe assigned person receives an assignment alert. Leadership and the responsible person receive relevant customer updates, response deadlines, repair changes and resolution/reopening alerts. Completed claims stop overdue-response reminders.\n\n## Give the customer access\nUnder **Customer warranty access**, choose a project and select **Email warranty access**. The project must have a saved client with a valid email. This explicitly queues an email to that client containing a private project link. The customer can submit a new claim, add information, confirm a repair and reopen a resolved claim. The link expires after 30 days when created through this control. Renewing access revokes the earlier link.\n\nFor a single existing claim, use **Email claim access to customer** in its detail. That link covers the selected claim. Keep the displayed private link secure and share it only with the intended customer. An expired link requires the company to issue new access.\n\n## Update, confirm or reopen\nUse **Manage claim** to assign work, change its status, adjust the response deadline or arrange/reschedule a visit. Add **Repair / resolution details** before choosing Awaiting Customer, Resolved or Closed. **Awaiting Customer** means the completed repair needs customer confirmation; the customer uses **Confirm repair complete** to resolve it.\n\nWrite updates under **Add a claim update**. Check **Show this update in the customer's warranty link** only for text you intend the customer to read. Internal notes stay out of the customer link. Resolved or Closed claims can be reopened, and customers must enter the reason for another look.\n\n## Mobile and troubleshooting\nForms scroll within the dialog and actions have large touch targets. Wait for the save result before leaving. If client access cannot be emailed, confirm the project-client relationship and client email. A queued email still depends on delivery service. A document upload or quote warranty term does not itself submit a claim.","route":"/Warranty","search_terms":["warranty","claim","repair visit","response deadline","customer warranty","reopen","confirm repair"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-document-requests","feature_area":"Documents","audience":"office","question":"Request and track a general document review or electronic signature","answer_short":"Upload a project document, create a named review or signature request, email its private link and track an immutable response/activity record.","answer_long":"## Choose a saved project document\nOpen the project's **Quotes & Docs** tab. Upload the file with **Upload Document**, fill its metadata and choose **Save Document**. Confirm the file opens before requesting a response. The review/signature workflow covers saved project documents; quote and change-order customer approvals remain their own workflows.\n\n## Create the request\n1. In **Reviews & signatures**, select **Request review / signature**.\n2. Choose **Saved document** and **Response needed**: Electronic signature or Review acknowledgement.\n3. Choose a saved team member or leave **Recipient** on Customer or external recipient.\n4. Enter the recipient's full name and email. Check them carefully before proceeding.\n5. Choose **Link expires** and enter any **Instructions**.\n6. Select **Create and email request** and wait for the result.\n\nThe request records the selected document's filename, link and available file checksum. New project uploads calculate a SHA-256 checksum. It also records the named recipient, request type, expiry, requesting user and date. The email is explicitly queued for the intended recipient and its private token grants access only to that document response, not the company workspace.\n\n## Follow the response\nRead each card's Pending, Reviewed, Signed, Declined, Expired or Cancelled status. **Open request** opens its secure recipient page when you are authorized. **Activity record** shows creation, link/email actions, response name, consent record and timestamps. **Download activity record** saves the response and activity as a JSON record for your files. A completed response cannot be replaced by pressing the response action again.\n\n## Remind, revoke or request again\nFor a pending request, **Renew link & remind** issues a new link and queues a reminder; earlier links stop working. Reminder retries with the same captured link are deduplicated. **Cancel request** revokes the pending request's links. For an expired request, select **Request again** and review the recipient, document and new expiry before emailing a fresh request.\n\nIf creation succeeds but queuing the email fails, leave the dialog open and choose **Retry request email**. This uses the already-created request rather than creating another one. Do not share private links with someone other than the intended recipient.\n\n## Mobile and limits\nOn phones, scroll the request dialog to its footer. New actions use large touch targets and stack where space is limited. An uploaded contract alone is not a signature: the recipient must open the request and explicitly complete its consent action. Company sales approval status is separate from this general document response.","route":"/PMProjects","search_terms":["signature","document review","electronic signature","request signature","secure link","activity record","consent"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-document-recipient","feature_area":"Documents","audience":"all","question":"Review, sign or decline a document shared with you","answer_short":"Open Document requests for your assigned review/signature requests, or use the private link emailed to you. Inspect the saved version and explicitly record your name and consent.","answer_long":"## Your assigned document inbox\nSigned-in subscribers can open **Document requests** to find the review and signature requests they are allowed to access. A notification opens and highlights its exact request, including requests older than the recent list. Choose **View document version** to inspect the saved file. For a Pending request, **Open request** obtains limited access to its response page. Completed cards retain the recorded status, name, date and comments; **Activity record** shows the audit history.\n\n## Start from the message sent to you\nYour contractor or company sends a secure document request link addressed to the named recipient. Open that original link in a regular browser. You do not need access to the private company workspace to respond. Keep the link private because it is the capability that opens this particular document request.\n\nThe page identifies the company, document title, intended recipient, instructions and expiry. Check these details before taking action. If the name or document is unexpected, contact the sender instead of forwarding the private link to someone else.\n\n## Inspect and respond\n1. Select **Open** beside the document filename to inspect the file in a new tab.\n2. Return to the response page and enter **Your full name**.\n3. Add **Comments** if there is a qualification, question or information the sender needs to retain.\n4. For a signature request, read and check the consent statement agreeing to sign electronically using the name entered above. For a review request, check the acknowledgement that you reviewed the document.\n5. Choose **Sign document** or **Complete review** and wait for **Response recorded**.\n\nThe app records the full name, response time, comments, consent version and saved document reference/checksum where available. Do not leave while the button is saving. Once a response is recorded, repeating the action does not overwrite it with another decision.\n\n## Decline or request a correction\nSelect **Decline request** if you cannot complete the requested response. Enter your full name and use Comments to explain a correction or question. Declining does not require the positive signing-consent checkbox. The sender receives the recorded status and can issue a corrected new request when appropriate.\n\n## Expired or renewed links\nLinks have an expiry and can be cancelled or renewed by the sender. A renewed request link replaces earlier links. If the page reports that the link is invalid or expired, ask the sender for current access rather than guessing a different URL or opening a private builder page.\n\n## On a phone\nThe file opens separately from the response form. Return to the original browser tab after reviewing it, then scroll to the consent and response actions. Confirm that the recorded success message appears. If saving fails, retain the visible error and ask the sender for help; a ticked consent box alone does not mean a response was saved.","route":"/DocumentRequests","search_terms":["sign document","recipient","consent","decline document","complete review","expired signature link"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-document-requests"],"source_key":"help_articles_portal"},{"slug":"guide-equipment-reservations","feature_area":"Inventory","audience":"all","question":"Reserve equipment, record checkout and return reusable tools","answer_short":"Mark reusable items as equipment, reserve quantities for a project, record checkout and return, and monitor conflicts, condition and maintenance dates.","answer_long":"## Identify reusable equipment\nPermitted office/project staff open **Inventory** and choose **New item** or edit an existing item. Set **Item type** to Equipment / reusable tool. Review the available quantity and choose **Equipment condition**: Available, Maintenance, Damaged or Missing. Enter **Next maintenance date** when the tool or equipment has a service requirement.\n\nInventory stock and equipment reservations are related records. A condition or maintenance date is not proof that a physical inspection has been completed. Use your company's maintenance process and record the next date accurately.\n\n## Reserve and check out\n1. Open the item's quick view and find **Reservations and returns**.\n2. Select **Reserve**.\n3. Enter **Quantity**, **Project**, **Assigned to**, **Start date**, **Return due** and useful **Notes**.\n4. Select **Save reservation**.\n5. Review any conflict warning. The workflow can retain the reservation and alert management when overlapping demand exceeds availability; resolve the conflict before relying on the item being available.\n6. When the item physically leaves storage, select **Check out** for the reservation.\n\nA reservation records intended use. Checkout records the actual handover. Do not use a reservation status alone as evidence that the assigned person collected the equipment.\n\n## Return, cancel or report condition\nUse **Record return** when the equipment is physically returned. Confirm the correct reservation and record any requested return details. Cancel a reservation when planned use is no longer needed; retain the history rather than creating a replacement reservation to undo a return.\n\nEdit the item's **Equipment condition** to report Maintenance, Damaged or Missing. This alerts the appropriate company staff. Keep the issue description and any inspection evidence in the company's normal equipment records and do not promise that a tool is usable solely because a notification was marked read.\n\n## Alerts and mobile use\nRelevant alerts cover reservation conflicts, maintenance dates, overdue returns and damaged/missing equipment. They remain limited by company access and personal notification preferences. The forms use responsive layouts and scrollable dialogs on phones. Scroll through the return deadline and notes before saving. If a save fails, check the list before retrying so an accepted reservation is not duplicated.\n\n## Field staff: request and return your equipment\nOpen **Employee Portal → Inventory → My equipment** and check the item, quantity, project and return due date on your assigned reservation. Select **Request checkout** when the reservation is Reserved and the equipment is available. The request remains Reserved, showing that office approval is required, until the office uses the item's **Reservations and returns → Check out** action for the actual handover.\n\nAfter physically handing back checked-out equipment, select **Confirm equipment returned**. You can request checkout and confirm return only for your own assigned reservation. If the item is unavailable or a reservation is missing, contact the office rather than recording material consumption for a reusable tool. Notification links highlight the relevant item/reservation, including older records. On phones, scroll through the card and confirm the saved status after each action.","route":"/Inventory","search_terms":["equipment","reserve","reservation conflict","return due","maintenance","damaged","missing","my equipment","request checkout","confirm equipment returned","office approval"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-task-discussion-dependencies","feature_area":"Tasks","audience":"all","question":"Discuss a task and set prerequisites before work starts","answer_short":"Post task-specific comments and connect production-task prerequisites. Completing all prerequisites generates a readiness alert without automatically doing the work.","answer_long":"## Open the right task\nOpen **Tasks** and select the task, or open a project's **Staff & Tasks** tab and choose **Edit Task**. Check the task title, project and assigned person before adding information. Field users open their assigned task from **Employee Portal → Tasks**; the field view does not grant permission to edit another person's assignment or prerequisite plan.\n\n## Discuss the task\n1. Find **Task discussion** in the detail view.\n2. Enter a useful comment about the work, decision or question.\n3. Select **Post comment** and wait for the saved comment to appear.\n4. Check the author and date in the discussion before relying on a new instruction.\n\nTask comments are separate from general project daily logs and help/support questions. Comments can notify the people involved in the task; they do not automatically email the customer. Avoid placing customer-facing promises or private staff information in the wrong discussion.\n\n## Add a prerequisite\nFor a production task, use **Prerequisites → Choose a prerequisite → Add prerequisite**. Choose another task from the same project that must be completed first. The app rejects circular dependencies and links to tasks outside the project.\n\nA prerequisite is a planning dependency. When all linked prerequisite tasks are complete, the app can notify that the task is ready to start. It does not complete the dependent task automatically, change the physical schedule by itself or prove that required materials and inspections are available. Check the site and the saved task instructions before beginning.\n\nField staff can read the prerequisite list for their assigned task. A permitted project manager or office user controls changes to the dependency plan. If the task is still blocked after a readiness alert, check whether another dependency was added or a completed prerequisite was reopened.\n\n## Dates, assignments and mobile use\nAssignment/reassignment, priority changes, due/overdue dates and completion can generate their own routed alerts. Choose personal channels in **My notifications** if you want eligible updates outside the app. On a phone, open the task detail and scroll to its discussion or prerequisites; controls use large touch targets. If posting fails, preserve the comment and check whether it was saved before repeating it.","route":"/Tasks","search_terms":["task comment","discussion","prerequisite","dependency","ready to start","priority change","assigned task"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-notification-events","feature_area":"Notifications","audience":"all","question":"Understand notification wording, recipients and event coverage","answer_short":"Notifications identify the actor, action, record and date when available. Only eligible people receive an event, and marking it read does not complete the work.","answer_long":"## Read the actor and action\nA notification describes who performed the action, what changed, the named record and when it happened. A lead example is **Gary Byrne created Lead Tim Rich on Oct 2nd, 2026**. Customer actions identify the customer where the workflow records that identity; scheduled reminders identify the system rather than inventing a staff action.\n\nDates use the company's or saved notification timezone where the interface supports it. The timestamp belongs to the event being reported. Opening an old alert today does not mean the action happened today.\n\n## Know who receives an event\nRecipients depend on company membership, active role, module permission, project membership and the person explicitly assigned to the work. Owners and office staff receive the business events their role covers; project managers receive accessible project events; field staff receive their own assigned work and eligible project updates. An alert never grants access to a record your role cannot open.\n\nThe notification bell can filter by category, read state and severity. **Action Required only** hides Important and FYI updates; turn it off when checking whether a lower-priority event arrived. Marking an alert read changes its read state, not the lead, task, payment, signature or warranty status.\n\n## Events to expect\nEligible alerts cover lead creation/assignment/replies/follow-ups/meetings; quote and change-order internal reviews, customer decisions, follow-ups and deadlines; invoices, recorded payments and delivery problems; project dates, phases, tasks, dependencies and discussion; daily logs, site issues and safety; staff hours, leave and timesheet reminders; purchases, deliveries, cost limits and equipment; plans, document responses and warranty activity; account/subscription/security changes; platform support and announcements.\n\nA document's manually selected Sent status is different from a provider-confirmed dispatch. A budget alert is a threshold signal, not an accounting reconciliation. A customer acceptance or general document signature is also different from an internal approval to send.\n\n## Personal delivery and summaries\nUse **My notifications** to choose categories, instant email, SMS, device push, quiet hours and daily/weekly digests. External channels require configured service and valid opted-in contact/device information. Newly enabled summaries contain future eligible activity; they do not replay all historical messages.\n\n## Missing or unexpected alerts\nCheck the company/account, assignment, permissions, selected filters and personal preferences. If a notification points to an unavailable record, ask the company administrator to check access or whether the record was removed. For support, include the event category, approximate date and record name without sharing a private customer token.","route":"/EmployeePortal","search_terms":["notification actor","created lead","who receives","date","missing notification","categories","action required"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":[],"source_key":"help_articles_portal"},{"slug":"guide-project-workspace","feature_area":"Projects","audience":"office","question":"Find your project and navigate the project workspace","answer_short":"Locate a project, open its workspace, and choose the right area for scheduling, staff, materials, documents, and client updates.","answer_long":"## Before you begin\nSign in to your company's workspace with a role that can manage projects. Project management pages show the company's projects; field team members use their assigned work in Employee Portal. Have the project name, client, or site address ready so you can distinguish similarly named jobs.\n\n## Open and navigate a project\n1. Open **PM Projects**. Each project card shows its name, status, and any saved client, address, dates, or budget.\n2. Select **Open** on the correct project card. Check the project heading and site address before making changes.\n3. Use the dropdown underneath the project heading to select a workspace area. The selected area is shown on the button, which also works on phones.\n4. Choose **Overview** for project health, milestones, linked documents, status, and quick additions. Choose **Phases** to maintain phase details and **Phase Timeline** to review the phase schedule.\n5. Choose **Staff & Tasks** for assignments, task editing, and the assignee filter. Use **Materials**, **Subcontractors**, or **Permits** for the related project records.\n6. Choose **Client View** for client-visible timeline updates, **Client Notes** for the notes feed, and **Project Notes** for the project diary. These areas serve different purposes.\n7. Choose **Quotes & Docs**, **Plans & Elevations**, or **Contractor Portal** when working with project files. Use the back arrow to return to PM Projects.\n\n## Create a project from an existing quote\nOpen the saved quote and select **Convert Quote**, then **Project Only** or **Project & Invoice** as appropriate. Review the resulting project rather than converting the same quote repeatedly. A conversion may first open the Project Detail page; you can return to PM Projects and open the project workspace for the PM tools.\n\n## Troubleshooting\n**Project not found** usually means the URL is missing its project identifier, the project was deleted, or your account cannot read it. Return to PM Projects and open the record from its card. Do not replace an inaccessible record by creating duplicates. On mobile, use the workspace dropdown rather than looking for a wide row of tabs.","route":"/PMProjects","search_terms":["project workspace","PM projects","open project","project tabs","convert quote"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-overview","guide-project-import-quote"],"source_key":"help_articles_portal"},{"slug":"guide-project-overview","feature_area":"Projects","audience":"office","question":"Understand project health, progress, and linked documents","answer_short":"Read project overview metrics correctly and use project status, Quick Add, milestones, and linked document cards.","answer_long":"## What the Overview shows\nOpen a project from **PM Projects** and select **Overview** in the workspace dropdown. This area brings together phases, tasks, issues, materials, milestones, client information, and linked commercial documents. Check the project heading first; updates apply to the open project.\n\n## Review the project\n1. Read the project status beside its name. Select the status dropdown to choose **Planning**, **Active**, **On Hold**, **Completed**, or **Cancelled** when your team has agreed to that change.\n2. Review progress. The overview percentage is the average of the phases' saved completion percentages. It is not calculated from paid invoices or the number of tasks alone.\n3. Compare completed tasks with the total task count. Tasks contribute to the completed count when their status is **Done**.\n4. Review open issues. Issues that are neither **Resolved** nor **Closed** remain in this count.\n5. Check days remaining when a target end date is available. An old or missing target date can make this figure unhelpful even when the job is progressing normally.\n6. Review the material-cost figure alongside the project's budget. This overview uses actual material cost when present, otherwise estimated cost; it is a project indicator rather than a complete accounting ledger.\n7. Open the linked quote, change order, invoice, or purchase order cards to inspect the underlying document. Linking a document is different from creating one or recording payment.\n\n## Add work without leaving Overview\nSelect **Quick Add** and choose **New Task**, **New Phase**, **New Material**, **New Milestone**, or **Project Note**. Complete the required fields and wait for the save confirmation. For detailed task assignment, due dates, and edits, use **Staff & Tasks** afterward. For material purchasing details, use **Materials**.\n\n## Review the company dashboard\nOpen **PM Dashboard** for **Active Projects**, **At Risk**, and **Upcoming — Next 14 Days**. Active Projects includes projects in Active, In Progress, or Planning states. Its progress bar also uses saved phase percentages. At Risk lists overdue incomplete tasks/milestones and open critical issues. Upcoming combines dated milestones, tasks, and materials within the next two weeks. These lists are capped, so they are summaries rather than complete work lists. Open the related project to review its records, and use **All Projects** to see the project cards.\n\n## Troubleshooting and mobile use\nAn unchanged overview percentage can reflect stored phase completion values. The Phases area's task bar is calculated separately from Done tasks, so the two displays can differ. Use the phase status and actual dates to review the job rather than assuming the overview automatically follows task completions. A missing document card can mean the document is not linked to this project or you cannot read it. On a phone, scroll through the overview sections and use the same Quick Add menu; review the selected project before saving. Refresh once after a successful update if another area still shows old values.","route":"/PMProjects","search_terms":["project overview","progress percentage","project status","project budget","quick add","PM dashboard","at risk","upcoming next 14 days"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-milestones","guide-project-phases","guide-project-materials"],"source_key":"help_articles_portal"},{"slug":"guide-project-import-quote","feature_area":"Projects","audience":"office","question":"Import quote phases and tracked materials into a project","answer_short":"Use the linked quote to populate project phases and material planning without repeatedly importing existing names.","answer_long":"## Before you begin\nThe project must have a linked quote. The quote needs saved phases for phase import and line items flagged as materials for tracked-material import. Open **PM Projects**, select **Open** on the project, and choose **Overview**. Review existing phases and materials first so you understand what is already planned.\n\n## Run the import\n1. Select **Import Data** in Overview. If the app says **No Quote Attached**, stop and confirm the project's quote link with the person who created or converted the project.\n2. In **Import Linked Data**, select **Import Project Phases**, **Import Tracked Materials**, or both. The options control which records are added.\n3. Select **Run Import** and wait for the result. The success message reports inserted phases and materials, and any names skipped as duplicates.\n4. Open **Phases** and verify the phase names and order. Imported phases start as **Not Started** and are marked client-visible, so review visibility before sharing updates with a client.\n5. Open **Materials** and verify quantities, units, suppliers, product information, notes, and phase assignments. Tracked materials start as **To Order**.\n6. Set or review planning dates and assignments separately. Importing the quote does not complete the project schedule or purchase the listed materials.\n\n## Import from the Materials area\nThe **Import Quote** button in Materials imports only quote line items flagged as materials. It carries descriptions, available supplier/product references, and images, and attempts to match the quote phase name to an existing project phase. Import the phases first when you want that mapping to succeed.\n\n## Understand duplicate handling\nThe import skips phases whose names already exist and materials whose names already exist in the project. It does not merge later quantity, price, or description changes into an existing imported record. Edit the project record intentionally when the quote has changed; repeated import is not a synchronization service.\n\n## Troubleshooting\n**No phases or tracked materials found** means the linked quote lacks the eligible source records. **No items flagged as materials** means the quote lines need the material flag set before import. An unassigned material usually needs its phase selected manually or the matching phase created. If an import fails, inspect what was already added before retrying; some records may have been saved before the error.","route":"/PMProjects","search_terms":["import quote","import phases","tracked materials","duplicate import","no quote attached"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-phases","guide-project-materials"],"source_key":"help_articles_portal"},{"slug":"guide-project-phases","feature_area":"Project Phases","audience":"office","question":"Create and maintain project phases","answer_short":"Set phase order, dates, progress, leadership, subcontractors, budget, visibility, and internal notes.","answer_long":"## Before you begin\nOpen the project workspace and choose **Phases**. A phase is a distinct section of work, such as demolition or rough-in. Use clear names and an agreed order so the overview and schedule remain understandable. Quote phases can also be added through Overview's **Import Data** action.\n\n## Add a phase\n1. Select **Add Phase**, or **Add First Phase** when the list is empty.\n2. Enter the required **Phase Name** and **Order / Sequence**. The list sorts by the sequence number.\n3. Enter **Phase Budget**, **Target Start Date**, and **Target End Date** when known.\n4. Choose a subcontractor if this phase belongs to a trade. Select **+ Create New Subcontractor** only when the existing directory does not already contain the company.\n5. Save the phase. New phases begin as **Not Started**.\n\n## Maintain progress and details\nExpand a phase with its chevron to see its detailed controls. Select **Not Started**, **In Progress**, **Blocked**, or **Completed** to describe its state. The task bar on this screen is calculated from the phase's linked tasks: Done tasks divided by total linked tasks. The overview separately reads saved phase completion percentages, so these two indicators may differ.\n\nUse **Target Start** and **Target End** for planned dates, and **Actual Start** and **Actual End** for what happened. Choose **Assigned Lead / Foreman** for the internal person responsible. Select the subcontractor when relevant and review **Phase Budget** as the scope changes. Enter **Internal Phase Notes** for operational context, then leave the field so the current value is saved.\n\nReview **Visible in Client Portal** before sharing a phase. This visibility setting controls whether the phase contributes to the client-visible feed; it does not publish every internal note or make your whole project public.\n\n## Troubleshooting and safe removal\nIf a phase is absent from the schedule, confirm it has usable planning dates and that the schedule window includes those dates. If a name appears twice after import, check the spelling because duplicate handling is based on existing names. Deleting a phase requires confirmation and can unlink its tasks; review affected work first. On mobile, expand one phase at a time and allow each update to finish before switching fields or leaving the page.\n\n## Readiness and phase dependencies\nChoose **Ready** when a phase can begin. **Prerequisite phase** links a phase from the same project and rejects cycles. Finishing the prerequisite can notify the next phase's readiness; it does not perform or automatically complete that next phase. Review the saved dates, responsibility, resources and site readiness before work begins.","route":"/PMProjects","search_terms":["phase","phase progress","phase dates","foreman","client visible","phase order"],"priority":83,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-phase-timeline","guide-project-client-updates"],"source_key":"help_articles_portal"},{"slug":"guide-project-milestones","feature_area":"Projects","audience":"office","question":"Track project milestones and target dates","answer_short":"Create milestone checkpoints, maintain their status, and understand how they appear in the dashboard and client feed.","answer_long":"## What a milestone is\nA milestone is a checkpoint such as an inspection, delivery deadline, or project handover. It has a title, target date, and status. It is separate from a phase, which describes a body of work, and from a task, which describes an actionable assignment.\n\nOpen the project from **PM Projects** and select **Overview**. Check the project heading and confirm which checkpoints the team expects to track before adding records.\n\n## Add and maintain milestones\n1. Select **Quick Add**, then **New Milestone**. You can also use the add button in the overview's milestone section.\n2. Enter the required **Milestone Title**. Use a name that explains the outcome, such as “Rough-in inspection,” rather than a vague reminder.\n3. Set **Target Date** if known. A missing target date prevents the milestone from contributing a dated upcoming deadline.\n4. Select **Pending**, **In Progress**, or **Completed** according to its actual state, then save.\n5. Review the saved milestone in Overview. Use its edit control to adjust the target date or status when the plan changes.\n6. Mark the milestone **Completed** after the checkpoint is reached. Changing the milestone status does not automatically complete the project's tasks or phases.\n\n## How the date is used\nThe PM Dashboard considers incomplete milestones with target dates when building its upcoming and overdue lists. The next milestone on a project's dashboard card is the earliest dated milestone that has not been completed. A past date therefore remains relevant until the checkpoint is completed or the target is intentionally revised.\n\nThe client timeline can include milestones unless they are explicitly marked not client-visible. Review the client feed before assuming a milestone is internal, especially when the title includes private project context.\n\n## Troubleshooting and mobile use\nIf a checkpoint is missing from upcoming work, inspect its target date and status. The upcoming list covers approximately the next two weeks and is capped, so it is not the full project plan. Duplicate milestones are separate records; creating another will not replace the old one. If you must remove a milestone, use its delete control and review the confirmation carefully. On a phone, scroll to the milestone section or use Quick Add, then verify the saved record.","route":"/PMProjects","search_terms":["milestone","checkpoint","inspection","target date","upcoming deadline"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-overview","guide-project-client-updates","guide-project-phase-timeline"],"source_key":"help_articles_portal"},{"slug":"guide-project-phase-timeline","feature_area":"Project Phases","audience":"office","question":"Read the project phase timeline and Gantt schedule","answer_short":"Use the phase schedule to compare phase dates, subcontractor assignments, and material deadlines across a 60-day view.","answer_long":"## Before you begin\nOpen the project workspace and choose **Phase Timeline**. The page is titled **Project Gantt Schedule**. It displays saved project planning data; moving around the chart does not reschedule records.\n\nCreate phases in **Phases**, assign subcontractors in **Subcontractors**, and maintain materials in **Materials**. A row needs suitable dates to show a bar or date marker. The schedule is a visual review of those source records.\n\n## Navigate the schedule\n1. Review the date range at the top and locate today's position in the grid.\n2. Use the left and right arrow buttons to move the schedule window backward or forward in fourteen-day increments. Each window contains sixty days.\n3. Select **Today** when that button is visible to return the range to the current date.\n4. Expand a phase using its chevron to see related subcontractor assignments and materials. The phase rows follow their saved phase order.\n5. Compare phase bars with subcontractor scheduled start/end dates and the material needed-by dates. A material associated with another phase will appear under that phase.\n6. On desktop, drag the divider at the edge of the label column to make long names easier to read. On a phone, scroll the date grid horizontally while the names remain in the label area.\n7. Select **Print** to open the browser's print workflow when you need a schedule copy.\n\n## Change the underlying plan\nTo alter a phase's target dates, return to **Phases**. For a subcontractor's saved scheduling information, review its assignment in **Subcontractors**. Review the material record when a material deadline or phase association is wrong. Chart navigation and tapping a bar do not save new dates.\n\n## Troubleshooting\n**No phases scheduled yet** can mean the project has no phases, even when tasks exist elsewhere. A phase without dates may have a name row but no visible bar. A valid bar outside the current sixty-day window will be hidden until you navigate to its dates. Check whether end dates precede start dates before interpreting an empty or unexpected bar. Material status labels can differ between planning views, so use the underlying material record to verify the current purchasing state.","route":"/PMProjects","search_terms":["gantt","phase timeline","project schedule","timeline dates","print schedule"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-phases","guide-project-subcontractors","guide-project-materials"],"source_key":"help_articles_portal"},{"slug":"guide-projects-timeline","feature_area":"Projects","audience":"office","question":"Compare projects in Timeline and Calendar views","answer_short":"Review planned project date ranges in the company-wide timeline or monthly calendar and open the related workspace.","answer_long":"## Choose the right schedule\n**Projects Timeline** compares whole projects across the company. **Phase Timeline** inside a project compares the phases, subcontractors, and materials of that one project. Use Projects Timeline for a portfolio view and the project workspace for detailed work planning.\n\nThe project range comes from its saved start date and target end date. This view reads those dates; it does not provide drag-and-drop project rescheduling or automatically resolve staffing conflicts.\n\n## Review the Timeline view\n1. Open **Projects Timeline** and select **Timeline**.\n2. Find the project in the name column. Projects are ordered using their saved start dates.\n3. Compare the project bar with the date header. A bar is drawn when at least one of the project dates is available; one date alone may appear as a single-day range.\n4. Use the arrow buttons to move backward or forward fourteen days. The timeline displays a sixty-day window.\n5. Select **Today** when visible to return to the current window.\n6. Open the project from its displayed link when you need the workspace, phases, tasks, or material records.\n\n## Review the Calendar view\nSelect **Calendar** to see project ranges across a month. Use the arrows to choose the preceding or following month. The same project may appear on several dates because it spans multiple days; those appearances are not duplicate project records. Use **Today**, when visible, to return to the current month.\n\n## Troubleshooting and phone use\nA project without either planning boundary cannot appear as a dated bar or calendar range. If you cannot find an old project, change the visible window or month before concluding it is missing. Completely cancelled projects without a start date are excluded from this view. A project whose target end precedes its start can display unexpectedly; confirm the saved dates in the project record.\n\nOn mobile, swipe the timeline horizontally to inspect later dates and use Calendar when a monthly overview is easier to scan. Opening **All Projects** or returning to PM Projects gives you the project cards even when their scheduling dates are missing.","route":"/PMTimeline","search_terms":["projects timeline","calendar","portfolio schedule","project dates"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-workspace","guide-project-phase-timeline","guide-project-overview"],"source_key":"help_articles_portal"},{"slug":"guide-project-staff","feature_area":"Team","audience":"office","question":"Assign company staff and manage project tasks","answer_short":"Add company members to a project, create tasks, and maintain assignees, priority, dates, hours, and completion.","answer_long":"## Before you begin\nOpen the project workspace and choose **Staff & Tasks**. The page contains **Task Board** and **Assigned Team** views. Assigning someone to the team and assigning a specific task are separate actions: a team member is not automatically responsible for every project task.\n\n## Add staff to the project\n1. Select **Assigned Team**.\n2. Select **Assign Staff** and choose the **Company User**. Only available company members can be selected; a person must exist in your company directory first.\n3. Confirm the assignment and check that the member appears in the team's cards.\n4. Use a card's remove control only when the person should be removed from the project. Read the confirmation; removing a staff membership does not explain how every task should be reassigned.\n\n## Create and edit tasks\n1. Return to **Task Board** and select **Add Task**.\n2. Enter a clear task title and description. Review the client and project choices so the task is attached to the intended job.\n3. Set priority, assignee, due date, and estimated hours where applicable, then save.\n4. Open an existing task's menu and choose **Edit** to review **Project Phase**, **Priority**, **Status**, **Due Date**, **Est. Hours**, and **Assign Staff (Select Multiple)**.\n5. Choose **To Do**, **Doing**, **Blocked**, or **Done** to describe the task's current state. Record enough description to make a blocked task actionable for another person.\n6. Save changes and check the task card. The completion control can switch a task between **Done** and **To Do**.\n\n## Troubleshooting and mobile use\nIf someone is missing from Assign Staff, they may already be assigned or absent from the company user list. If a task seems missing, clear the **Assigned to** filter and verify its linked project. A task moved to another project will no longer appear in this project's list. Due dates and estimated hours are planning fields; entering them does not record worked time. On phones, use the two view buttons and scroll through the dialog to reach its save action. Avoid deleting a task merely to fix an assignee; edit the existing record instead.\n\n## Task discussion and management-hour limits\nOpen **Edit Task** for **Task discussion** and production-task **Prerequisites**. Post a comment or add a same-project prerequisite; circular dependencies are rejected. The **Project management hours** panel lets permitted staff set an assigned manager's hour cap with **Save cap**, then **Submit management hours** with date, hours and work performed. Pending and approved management hours count toward 90%/over-cap alerts; retain the work description when reviewing totals.\n\nManagement time entries require normal HR approval. For scheduled workers, open **Project Details → Resource Allocation** and set **Hours for this allocation period**. Scheduled-hour alerts use a positive saved allowance; no allowance means no speculative overrun alert.","route":"/PMProjects","search_terms":["assign staff","project team","task board","edit task","multiple assignees"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-task-filter","guide-project-phases","guide-project-workspace"],"source_key":"help_articles_portal"},{"slug":"guide-project-task-filter","feature_area":"Tasks","audience":"office","question":"Filter a project task list by assigned user","answer_short":"Find tasks for a specific person or show unassigned work, then clear the filter without changing any task assignments.","answer_long":"## Where the filter is located\nOpen **PM Projects**, choose **Open** on the project, select **Staff & Tasks** from the workspace dropdown, and choose **Task Board**. The **Assigned to** selector is above the project tasks.\n\nThis filter changes what you see in the current project's task list. It does not assign work, remove tasks, or filter the entire company's project portfolio. Use **Edit** on an individual task when you need to change the assignees.\n\n## Filter the tasks\n1. Select **Assigned to**. The default is **All users**, which shows every task available in the project.\n2. Choose a company member by name or email to show tasks assigned to that person.\n3. Choose **Unassigned** when you want tasks without an assignee, such as newly created work that still needs an owner.\n4. Read the heading count. While filtering, it shows the number of matching tasks against the total project task count, helping you distinguish a narrow result from a project with no tasks.\n5. Open or edit a matching task as usual. If you change its assignees, it may leave the currently filtered results after saving.\n6. Select **Clear filter** or choose **All users** to restore the full list. Opening a different project resets this filter to All users.\n\n## Understand shared assignments\nA task can have multiple assignees. It appears when any of its saved assignees matches the selected person. The filter also recognizes older assignments stored as the person's email, so a task is not excluded merely because it uses an older assignment format.\n\n## Troubleshooting and mobile use\n**No tasks match this filter** means there are project tasks but none match the selection. Clear the filter before creating new tasks or reporting lost work. **No tasks created** means the project has no task records in this list. If a person is missing, confirm they belong to the current company and are represented in its directory.\n\nOn a phone, the selector and Clear filter button remain available above the cards; they may stack vertically. Selecting a user is a viewing choice, so you can safely switch between users while reviewing workload.","route":"/PMProjects","search_terms":["filter tasks by user","assigned to","unassigned","clear filter","assignee filter"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-staff","guide-project-workspace"],"source_key":"help_articles_portal"},{"slug":"guide-project-client-updates","feature_area":"Client Timeline","audience":"office","question":"Post client-visible project updates and review the client feed","answer_short":"Create dated client updates and understand which phases, milestones, and issues appear in the Client View feed.","answer_long":"## Before you begin\nOpen the project workspace and choose **Client View**. This subscriber-side view is the **Client Timeline Feed**. It helps your team review information marked for clients; it is different from the Client Notes feed and does not itself send a support ticket or invite a new subscriber.\n\nCheck the linked client and ensure the wording is appropriate to share. Avoid placing private pricing discussions, employee matters, or internal troubleshooting in an update that will be client-visible.\n\n## Post an update\n1. Select **Post Update**, or **Post First Update** when the feed is empty.\n2. Enter the required **Event Title / Summary**. Use a concise description of the work or checkpoint.\n3. Set **Event Date** to the date the update relates to, rather than relying on the date when you happen to type it.\n4. Enter **Details & Notes** with the context the client needs, such as what was completed, what comes next, and any decisions required.\n5. Review **Visible to Client** before saving. Leave it on only when the update is intended for the client feed.\n6. Save the update and review its placement in the dated feed.\n\n## What else appears\nThe feed combines manual updates marked client-visible, milestones that have not been explicitly hidden, phases marked client-visible, and issues marked client-visible. It groups entries by date and presents the most recent dates first. Phase progress and milestone status are read from their underlying records.\n\nA client-invisible manual update will not appear in this visible feed, even though it may be saved. Phase dates use actual start when available, otherwise target start or the record's creation date. This explains why an old phase may appear on a different date than expected.\n\n## Troubleshooting and mobile use\nIf an entry is missing, check visibility and the relevant date in the source record. If the status or progress looks wrong, update the phase or milestone rather than posting a contradictory manual update. Saving an update does not prove an email or text was delivered. On phones, scroll the feed by date and review the visibility switch in the posting dialog before tapping Save.","route":"/PMProjects","search_terms":["client view","client timeline","post client update","visible to client"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-phases","guide-project-milestones","guide-project-notes"],"source_key":"help_articles_portal"},{"slug":"guide-project-notes","feature_area":"Daily Logs","audience":"office","question":"Use Client Notes and Project Notes for the right purpose","answer_short":"Record conversation context in the notes feed and keep structured daily site information in Project Notes.","answer_long":"## Choose the appropriate record\nThe project workspace has **Client Notes** and **Project Notes**. Client Notes opens the shared notes feed for the project, allowing your team to record an update, email summary, or call note. Project Notes opens the structured project diary for dates, weather, crew, work completed, delays, safety concerns, materials, and photos.\n\nNeither label alone means a note has been emailed to a client or automatically published in the client-visible timeline. Use **Client View** when you need an explicitly client-visible update.\n\n## Post a conversation note\n1. Open the project and select **Client Notes**.\n2. Enter the update in **Log an update, email summary, call notes...**. Include the decision, responsible person, and next step so someone else can understand it later.\n3. Choose a category appropriate to the note. Use a mention only for a relevant available team member.\n4. Select the pin option when you need the note easy to find on this browser.\n5. Select **Post Note**, or use Control+Enter / Command+Enter while editing. Wait for the save to finish.\n6. Use the note's edit action when correcting the existing summary rather than adding a contradictory duplicate.\n\n## Record a site diary entry\nChoose **Project Notes** and add a daily log, or use Overview's **Quick Add → Project Note**. Enter **Date**, **Weather**, **Crew on Site**, **Work Completed Today**, **Issues / Delays**, **Safety Concerns**, and **Materials Used** as applicable. Save the record, then review it in the diary. The detailed Project Notes area supports reviewing and editing saved entries.\n\n## Troubleshooting and access\nPinned-note choices are saved in local browser storage, so a pin may not appear on another device. A missing mention option can mean the person is not in the relevant company/project team. The project feed is associated with the current project; confirm the project heading if you cannot find a note.\n\nOn phones, the posting controls wrap below the text box. Scroll the daily-log dialog to check all fields and the save action. A safety concern should also be communicated through your company's immediate reporting process; entering a diary field alone does not guarantee someone has seen it.","route":"/PMProjects","search_terms":["client notes","project notes","site diary","pin note","project conversation"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-client-updates","guide-project-overview"],"source_key":"help_articles_portal"},{"slug":"guide-project-plans","feature_area":"Plans & Elevations","audience":"office","question":"Upload and organize project plans, elevations, and drawing revisions","answer_short":"Save drawing files with their type, title, revision, and notes, then preview or download the correct plan.","answer_long":"## Before you begin\nOpen the project workspace and select **Plans & Elevations**. Keep the latest approved drawing files ready on your device. A plan in this area is a project drawing record with an uploaded file; it is not automatically a published contractor bid package or a signed approval.\n\nUse descriptive titles and revision labels so site staff can distinguish a current sheet from an older version. The available drawing types include Floor Plan, Elevation, Site Plan, Electrical, Plumbing, Mechanical, Structural, Detail Drawing, As-Built, and Other.\n\n## Upload and save a drawing\n1. Select **Upload Plan / Elevation**, or **Upload First File** when the area is empty.\n2. Choose the drawing type and enter a meaningful title.\n3. Enter the revision and notes when applicable. A revision label is descriptive; uploading another revision does not automatically replace an older saved record.\n4. Select the file from your device and wait for the upload to finish. The file name can fill the title when no title was entered.\n5. Save the record after the upload completes. Selecting a file and saving the drawing record are separate parts of the workflow.\n6. Confirm that the drawing appears under the correct type heading and that the revision label is visible.\n\n## Preview and download\nSelect an image thumbnail to open the image viewer. Other file types open in a new browser tab. Use the open/download controls on the card to access the file. If a download cannot be handled directly, the app may open the file URL so the browser's own save controls can be used.\n\n## Troubleshooting and sharing\nIf a file uploaded but no card appears, confirm the record was saved. A storage error and a record-save error are separate failures; note which message appears before retrying. Re-select the original file if the upload failed.\n\nTo share a drawing in the Contractor Portal, choose it using that portal's **Share Existing Project Files** flow. Saving it here alone does not add it to the portal's document list. On mobile, verify the full drawing title and revision before downloading. Removing a drawing record requires confirmation; download anything your team still needs before removal.\n\n## Upload and review revisions\nUse **Upload revision** on the current plan card. Upload the replacement file and enter a **Revision / Version** label before saving. The prior file remains in revision history. Assigned project staff receive a revised-plan alert. Use **Show earlier revisions** to inspect older files; always confirm which revision is current before work.\n\n## Open a drawing notification\nA plan alert opens and highlights the exact drawing, including an earlier revision. Earlier-revision alerts show a warning; check the current sheet before starting work. Assigned field users view plans under **Employee Portal → My Projects** with open/download controls and revision history. Upload, replacement and removal stay with permitted office/project staff.","route":"/PMProjects","search_terms":["upload plan","elevation","drawing revision","floor plan","download drawing"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-documents","guide-project-contractor-portal"],"source_key":"help_articles_portal"},{"slug":"guide-project-documents","feature_area":"Projects","audience":"office","question":"Store supplier quotes and documents in a project","answer_short":"Upload supporting files, classify them, and keep vendor, amount, and internal notes alongside the document.","answer_long":"## Before you begin\nOpen the project workspace and select **Quotes & Docs**. This area stores supporting project files such as supplier quotes, contractor quotes, contracts, and specification sheets. These uploaded documents are different from the app's editable sales quotes, invoices, and purchase orders.\n\nHave the file ready and decide what information belongs in its record. If it contains confidential information, review whether it should remain internal before sharing it through any external portal.\n\n## Upload a document\n1. Select **Upload Document**, or **Upload First Document** when the area is empty.\n2. Choose **Document Type** and fill **Vendor / Company** if applicable.\n3. Enter **Amount ($)** when the document represents an amount you want to reference. This metadata does not create a payment or automatically update the project's accounting totals.\n4. Add **Internal Notes** that explain the document, its version, or a decision associated with it.\n5. Choose the required **File** and wait for upload confirmation.\n6. Select **Save** to create the document record. The upload confirmation explicitly asks you to finish the details and save; closing the dialog beforehand does not finish the record workflow.\n7. Confirm the saved file appears in its document-type group.\n\n## Read and share files\nUse **Open in new tab** to inspect a document and **Download file to device** to save a copy. Documents can be selected separately in **Contractor Portal → Share Existing Project Files**. A file saved in Quotes & Docs is not automatically included in every contractor's bid package.\n\n## Troubleshooting and mobile use\nIf the Save button is disabled, check that a file URL is available and the upload has finished. A file can upload successfully while saving its metadata fails, so inspect the exact message before retrying. A failed direct download may open the file in a browser tab; use the browser's download or share controls there.\n\nDo not interpret an uploaded contract as a completed digital signature. Use **Reviews & signatures → Request review / signature** to request a saved document response; follow the dedicated guide for recipient consent, expiring links, reminders and the activity record. On phones, scroll the upload dialog through the file and save controls. Use the delete action only for records your team intentionally wants removed; the confirmation describes permanent document deletion.","route":"/PMProjects","search_terms":["project documents","supplier quote","spec sheet","upload document","contracts"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-plans","guide-project-contractor-portal"],"source_key":"help_articles_portal"},{"slug":"guide-project-permits","feature_area":"Projects","audience":"office","question":"Record project permits and attached approval documents","answer_short":"Track permit type, number, issuing authority, dates, status, scope, and a digital copy in the project.","answer_long":"## Before you begin\nOpen the project workspace and select **Permits**. The section is titled **Building Permits**, but it supports building, electrical, plumbing, mechanical, gas, demolition, grading, sign, and other permit types. Have the actual permit information ready so the record reflects the authority's document.\n\nThis area is a tracking tool. Adding a permit record does not submit an application, obtain approval from an authority, book an inspection, or establish that your project meets regulatory requirements.\n\n## Add a permit\n1. Select **Add Permit**, or **Add First Permit** when the list is empty.\n2. Choose the required **Permit Type** and the appropriate **Status**. The options include **Pending**, **Approved**, **Active**, **Expired**, **Closed**, and **Rejected**.\n3. Enter **Permit Number** and **Issued By (City/County)** when available.\n4. Enter **Issue Date** and **Expiry Date** from the permit document. These dates support the expired indication shown in the project.\n5. Fill **Scope of Work / Description** so your team can understand what the permit covers.\n6. Under **Digital Copy (PDF/Image)**, select the permit's PDF, JPG, JPEG, or PNG file. Wait for the file-upload confirmation.\n7. Save the permit record, then open the saved document to check that the correct file is attached.\n\n## Update and review\nUse the permit's edit control when the authority supplies new information or the permit changes state. A permit with a past expiry date can be highlighted as expired unless it is **Closed**. This date check is a visual cue, not evidence that an authority has cancelled or extended the permit.\n\n## Troubleshooting and mobile use\nA successful file upload still needs the permit form saved. If saving fails, keep the actual document and inspect the error rather than creating several incomplete permit records. If the expiry cue seems wrong, check the saved date and whether the permit is closed.\n\nOn phones, scroll the dialog through the dates, scope, file, and save controls. The delete action requires confirmation; removing the tracking record does not revoke the actual permit and may remove information your team needs for the project's history.\n\n## Inspection and information requests\nUse **Information Required** when a permit needs more information, and record **Information requested / inspection notes**. **Inspection tracking** records the inspection date and result: Passed, Failed or Reinspection required. Scheduling an inspection does not establish that it passed; record the actual result and keep the supporting report.","route":"/PMProjects","search_terms":["permit","building permit","permit expiry","approval document","permit upload"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-documents","guide-project-milestones"],"source_key":"help_articles_portal"},{"slug":"guide-project-materials","feature_area":"Project Materials","audience":"office","question":"Plan and track project materials from quote to receipt","answer_short":"Create material records, group them by phase, search them, and update purchasing status without confusing them with warehouse stock.","answer_long":"## Before you begin\nOpen the project workspace and select **Materials**. This is the project's purchasing and material-planning list. Warehouse **Inventory** is a separate record of physical stock, and a **Purchase Order** is a separate supplier document. Adding a project material does not by itself place an order or change warehouse quantities.\n\n## Add and maintain a material\n1. Select **Material** at the top, or **Add** in a phase group.\n2. Enter the required **Material Name**, **Quantity**, and **Unit**. Use a name that will be easy to recognize when searching supplier information later.\n3. Choose **Assign to Phase**, or leave it **General / Unassigned** when it does not belong to one phase.\n4. Enter **Estimated Unit Cost**. The material's displayed estimated total is quantity multiplied by this unit cost.\n5. Choose **To Order**, **Ordered**, or **Received On-Site**. Received is the saved state for material received on site.\n6. Fill **Supplier** and **Notes / Details (Optional)** with relevant SKU, product specifications, or delivery context.\n7. Select **Save Material**, then verify the record under its phase. Use the material's actions to edit or remove an existing record rather than adding duplicates.\n\n## Search and review purchasing progress\nUse **Search materials...** to find material names or notes. Combine it with **All Statuses**, **To Order**, **Ordered**, or **Received** to focus on work still required. Purchasing Overview totals are calculated from the full material list; a search narrows visible rows but does not redefine all project totals. The received percentage is based on material record count, not quantity or spending.\n\nUse **Import Quote** when the linked quote contains line items flagged as materials. Existing material names are skipped rather than overwritten. Review imported unit costs, quantities, supplier details, and phase mappings before using the totals.\n\n## Troubleshooting and mobile use\nAn empty list may result from a search or status filter. Clear both before reporting missing materials. A material in General / Unassigned needs a phase selected if you expect it elsewhere. Inconsistent wording in another schedule view can reflect older planning statuses; inspect the material's saved record. On a phone, controls may wrap above the phase groups; review the unit cost and quantity separately before saving.\n\n## Dates and cost alerts\nMaterial records include **Needed by**, **Actual unit cost**, **Cost category** and **Included in purchase order**. In the project's Materials tab, open **Cost alert limits** to set a material/purchase-order budget, approved labour-cost budget and category limits. **Save cost limits** enables approaching (90%) and exceeded threshold checks. Link a material or expense to a recorded purchase where applicable to avoid counting the same cost twice. Threshold alerts do not replace reconciliation against invoices, purchase orders and approved expenses.","route":"/PMProjects","search_terms":["project material","estimated unit cost","received on site","material supplier","import material"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-import-quote","guide-inventory-manage","guide-purchase-order-create"],"source_key":"help_articles_portal"},{"slug":"guide-project-subcontractors","feature_area":"Vendors","audience":"office","question":"Assign subcontractors to a project and phase","answer_short":"Connect a subcontractor to project work with status, dates, agreed amount, and role notes.","answer_long":"## Before you begin\nOpen the project workspace and choose **Subcontractors**. The area has assigned-project records and a directory. A directory contact is separate from an assignment: adding a company to the directory does not automatically book it for this project.\n\nReview the existing directory before creating a new entry. The project picker combines the company's vendor contacts and PM subcontractor contacts, so similarly named records can exist in different sources.\n\n## Create an assignment\n1. Select the assigned view and choose **Assign Sub**, or **Assign Subcontractor** when the list is empty.\n2. Choose the required **Subcontractor**. Confirm the company and contact details before assigning it.\n3. Choose a **Phase**, or **General / Unassigned** for work that does not belong to one phase.\n4. Set **Status** to **Proposed**, **Approved**, **Scheduled**, **On Site**, **Completed**, or **Removed** as appropriate.\n5. Set **Scheduled Start** and **Scheduled End** when the trade's booking has been agreed.\n6. Enter **Agreed Amount ($)** and **Role Notes** describing the expected scope, then save.\n7. Review the assignment card and change its status as the work progresses.\n\n## Add a missing contact\nIn the directory view, choose **New Sub**. The form includes Company Name, Trade Focus, contact details, WCB policy, insurance expiry, and notes. Complete what your team has actually verified. Saving an insurance date records information; it does not validate coverage with an insurer.\n\nThe phase editor also has a **+ Create New Subcontractor** option that creates a vendor contact. Use the appropriate directory and check for an existing contact so the company is not duplicated.\n\n## Troubleshooting and invitations\nA subcontractor missing from a phase schedule may be assigned to another phase, General / Unassigned, or have no scheduled dates. Review the assignment record first. Removing an assignment is different from deleting the directory contact.\n\n**Invite to Quote** sends a secure contractor link. The recipient can **Accept invitation**, **Decline invitation** or **Submit quote**. In the assigned view, **Trade quote requests** cards support **Approve quote** and **Decline quote**. An invitation or queued email does not itself mean that the trade accepted or that delivery succeeded. On phones, scroll the assignment dialog to reach dates, amount, notes, and the save control.","route":"/PMProjects","search_terms":["assign subcontractor","trade assignment","agreed amount","subcontractor dates","WCB"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-contractor-portal","guide-vendors-directory","guide-project-phase-timeline"],"source_key":"help_articles_portal"},{"slug":"guide-project-contractor-portal","feature_area":"Contractor Portal","audience":"office","question":"Prepare and share a contractor bid package","answer_short":"Maintain project scope, select external-facing files, copy the portal link, and verify the package before sharing.","answer_long":"## Before you begin\nOpen the project workspace and choose **Contractor Portal**. This subscriber-side area prepares a project bid package. It is separate from a subcontractor's Employee Portal account and from the general Help Articles portal.\n\nReview exactly which documents and scope information should be shared outside your company. The portal's document list is controlled separately from your internal Quotes & Docs and Plans & Elevations catalogs.\n\n## Prepare the package\n1. Review **Scope of Work**. Choose its edit control, enter the intended scope, then save. The portal uses this scope field; a project's internal notes or quote scope are not necessarily the same text.\n2. To add a new file, enter **New File Description (Optional)** and choose **Click to upload a brand new file**. Multiple files can be selected; wait for the upload/save result.\n3. To reuse an existing file, choose **Share Existing Project Files**, select the appropriate documents or plans, and choose **Share to Portal**.\n4. Inspect **Files Visible to Contractors**. Open the files to verify the correct version and check that no internal-only file was included.\n5. Use **Copy** in the **Public Contractor Portal Link** card, then **Open** to inspect the package before sharing it with a recipient.\n6. Review the Fuzed Flow branded outside portal and the submission instructions before sharing. Its quote-email action uses the project company’s configured business contact email. If that contact is unavailable, contractors should reply to the contact who sent their invitation. Include any additional bid instructions in your own message.\n\n## Remove and update shared files\nUse a file's remove control to take its record out of the portal list. An internal drawing revision does not automatically replace a separately shared portal record. Review the external list again after document changes.\n\n## Troubleshooting and access\nIf a recipient sees **No project specified in the link**, copy the complete generated URL including its project identifier. **Project not found or link has expired** can also indicate access restrictions; contact your company administrator rather than bypassing permissions. File downloads may fall back to opening the document in a browser tab.\n\nCopying the link does not send an invitation or confirm a bid submission. On a phone, use the full-width Copy/Open controls and scroll the shared-file list; verify the external package's scope, file names, and recipient instructions before sending it through your chosen channel.","route":"/PMProjects","search_terms":["contractor portal","bid package","share existing files","contractor scope","copy portal link"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-project-documents","guide-project-plans","guide-project-subcontractors"],"source_key":"help_articles_portal"},{"slug":"guide-vendors-directory","feature_area":"Vendors","audience":"office","question":"Maintain the subcontractor and supplier directory","answer_short":"Keep searchable company contacts, trade categories, ratings, project history, notes, and supporting files.","answer_long":"## Before you begin\nOpen **Vendors**, which is titled **Subcontractors Directory**. The directory contains company subcontractors and suppliers. Access is restricted, and some accounts may see **Access Denied**; ask a company administrator to review access rather than creating another account.\n\nA directory record provides reusable contact information. It does not automatically create a project assignment, purchase order, user login, insurance verification, or payment record.\n\n## Add or update a contact\n1. Select **New Subcontractor**. On a phone, open **Actions** to find this option.\n2. Enter the required **Subcontractor / Company Name** and fill **Contact Name**, **Trade / Category**, **Email**, **Phone**, and **Physical Address** as applicable.\n3. Review the internal rating and preferred setting based on your company's assessment. These are internal tracking choices.\n4. Under **Projects Worked On**, tag saved projects relevant to the contact's history. A history tag is different from scheduling that company on a live project.\n5. Add relevant supporting files in **Invoices & Files from Subcontractor** and record useful **Internal Notes**.\n6. Save the contact, then review its row or card. Choose **Edit** from its actions menu to correct details later.\n\n## Find an existing contact\nUse **Search name, contact, or email...** and the category/preferred filters. Choose the list or card view that is easiest to scan. Sorting can be **Newest First**, **A-Z**, or **Z-A**. Check the contact's name and email before creating a duplicate or preparing a request.\n\n## Import and project use\nThe **Import Excel** control currently parses a CSV-style file; save spreadsheet data as CSV and review the dialog's header guidance rather than uploading an arbitrary spreadsheet format. Imports add records, so inspect existing contacts first. Directory export can help review saved details.\n\nTo assign someone to a project, open that project's **Subcontractors** area and create an assignment there. For supplier orders, create a purchase order with the vendor selected.\n\n## Troubleshooting and mobile use\nIf the directory appears empty, clear search and filters and confirm the correct company account. If access is denied despite your expected role, provide that message to the company administrator. On phones, key actions are under the top Actions menu. Deletion removes the directory record; edit inaccurate details instead of deleting a contact that other records may reference.\n\n## Expiring documents and trade decisions\nThe vendor editor includes **Insurance expires**, **Certification expires** and **WCB policy ref**. Keep the dates current so expiry alerts reflect the correct record. In project Subs, **Invite to Quote** shares a secure contractor link; the invited contractor can accept/decline or submit a quote. Assigned-view **Trade quote requests** cards let permitted staff **Approve quote** or **Decline quote**. A saved directory row or invitation does not by itself mean the trade accepted the project.","route":"/Vendors","search_terms":["vendor","supplier","subcontractor directory","preferred vendor","vendor CSV"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-project-subcontractors","guide-purchase-order-create"],"source_key":"help_articles_portal"},{"slug":"guide-inventory-manage","feature_area":"Inventory","audience":"office","question":"Manage warehouse stock and review material usage","answer_short":"Create physical inventory records, set low-stock alerts, adjust quantities, and inspect the usage ledger.","answer_long":"## Distinguish stock from project planning\nOpen **Inventory**, titled **Warehouse Inventory**, to track physical shop stock. Project **Materials** is a separate purchasing plan, and the product catalog is used for quote/PO line items. Adding stock does not automatically fulfill a purchase order or update every project material status.\n\n## Add and maintain a stock item\n1. Select **Add Material**.\n2. Enter the required **Material / Item Name** and a useful **Physical Location**, such as a warehouse or truck.\n3. Choose **Unit**, enter **Unit Cost**, and record **Current Qty** in that unit.\n4. Set **Low Stock Alert At** to your reorder threshold. Items with quantity at or below the threshold qualify for the low-stock filter.\n5. Add categories, **SKU / Item #**, supplier details, optional supplier URL, description, and image where useful.\n6. Save, then verify the item's quantity, location, and unit in the list. Open its details to inspect or edit the full record later.\n\n## Find and adjust stock\nSearch item name or SKU and combine the category, location, and **Low Stock Alerts** filters. Clear filters before deciding an item is missing. The plus/minus controls make one-unit shop adjustments, with additions recorded as **Receive** and removals as **Consume**. For larger corrections, inspect the item carefully and use its edit form to change Current Qty.\n\nEditing a quantity field is not the same as recording a project-specific usage transaction. Manual shop adjustments use a shop-adjustment note and may have no project attached. Field users can use their Inventory tools in Employee Portal for the workflows available to their role.\n\n## Review the usage report\nSelect **Usage Report** to open the transaction ledger. Search by item or notes, then filter **Project**, **Employee**, and **Type**. The type options distinguish consumed/taken from received/added. **Export Ledger** exports the filtered transactions; it does not change stock.\n\n## Troubleshooting and mobile use\nAn **Unknown Item** in an old ledger entry can mean its inventory record was removed. A changed quantity with no expected project history may have come from a direct edit or shop adjustment. On phones, keep the unit visible while checking quantities, and use Usage Report to inspect history before making another correction.","route":"/Inventory","search_terms":["warehouse inventory","physical stock","low stock","usage report","receive consume"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-inventory-csv","guide-project-materials"],"source_key":"help_articles_portal"},{"slug":"guide-inventory-csv","feature_area":"Inventory","audience":"office","question":"Import and export warehouse inventory with CSV","answer_short":"Prepare a compatible stock spreadsheet, avoid duplicate imports, and understand which fields the importer reads.","answer_long":"## Before you begin\nUse **Warehouse Inventory** for this workflow. The current **Import CSV** and **Export** buttons are shown on wider screens, so use a desktop or tablet with a suitable viewport for bulk file work. Field stock usage is available separately in Employee Portal.\n\nCSV import adds new inventory records. It does not match an existing item by SKU, update existing quantities, or offer an automatic undo. Check existing stock and prepare only the new records you intend to add.\n\n## Prepare the file\nCreate a CSV file with a header row and at least one data row. Use clear columns such as **Name**, **SKU**, **Category**, **Unit**, **Location**, **Quantity**, **Cost**, and **Supplier**. Name is required; the importer also recognizes common headers containing item/product, quantity/qty, vendor/supplier, and location/bin.\n\nKeep each row's values aligned with its headers. Use plain numeric quantities and costs, and a consistent unit such as ea, ft, sqft, bag, or box. If omitted, quantity and cost become zero, unit defaults to ea, and location defaults to Main Storage. The importer does not carry every field available in the full item editor, so review reorder thresholds and subcategories afterward.\n\n## Import and verify\n1. Open Inventory and select **Import CSV**.\n2. Choose the prepared CSV file and wait for the result.\n3. Review the imported-item count and inspect several saved items for names, SKU, quantities, units, costs, and locations.\n4. Use the item editor to complete fields not supplied by the importer.\n5. If an import fails, inspect the inventory before retrying. Large imports are saved in batches, so earlier batches can already exist.\n\n## Export a review copy\nSet the inventory search and filters, then select **Export**. The CSV contains the currently filtered inventory rows. The export includes additional fields such as Sub Category, Alert Point, and Vendor URL, but those fields are not all restored by this importer; an export-and-reimport is not a full backup restoration.\n\n## Troubleshooting\n**File is empty or missing headers** means a proper header and data row are needed. **Could not find a Name column** means the item-name header was not recognized. **No valid items found** means data rows lacked usable names or columns. Avoid importing the same file twice when checking an error; find the already saved records first.","route":"/Inventory","search_terms":["import inventory","CSV inventory","stock spreadsheet","export inventory","duplicate inventory"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-inventory-manage"],"source_key":"help_articles_portal"},{"slug":"guide-purchase-order-create","feature_area":"Purchase Orders","audience":"office","question":"Create and complete a purchase order","answer_short":"Select a vendor and project, enter delivery details, add catalog or custom line items, and review calculated totals.","answer_long":"## Before you begin\nOpen **Purchase Orders** with a company account that can manage supplier orders. Have the supplier, item quantities, costs, delivery address, and expected date ready. A purchase order documents an order; creating a draft does not send it to the vendor or add physical stock.\n\n## Create the draft\n1. Select **New Purchase Order**. On smaller screens the create action may be displayed as a plus icon.\n2. Choose **Select Vendor**. Use the create-new-vendor option only after checking the existing list. The new-vendor form checks similar company names to help avoid duplicates.\n3. Set **Link to Project (Optional)** or choose **General Order (No Project)**.\n4. Enter **Order Date**, **Expected Delivery**, **Shipping Address**, and **Delivery Instructions / Notes** as needed.\n5. Select **Create PO Draft** and wait for the draft to open. The company PO prefix/counter provides its document number.\n\n## Add items and finish details\n1. Select **Add Item** in the line-item section.\n2. Optionally choose **Select Product from Catalog** to fill item information, or enter a custom **Item Name** and **Description**.\n3. Enter **Quantity** and **Unit Cost**, then save the item. Repeat for each order line.\n4. Review the subtotal, configured tax amounts, and total. Totals are recalculated after line items are added or removed using the company's tax settings.\n5. Review **Shipping Address**, **Vendor Quote Attachment**, **Delivery Instructions / Notes**, and **Terms & Conditions**. Detail fields save when their editing interaction finishes; **Save Draft** confirms the automatic-save behavior rather than acting as a separate bulk submit.\n6. Use **Vendor Preview** from Actions to inspect the document before sending it.\n\n## Troubleshooting and mobile use\nA vendor is required to create the draft. A project is optional. If a newly created vendor is selected but the order is not created, finish the main PO form rather than creating the vendor again. If the total seems wrong, inspect quantity, unit cost, and company tax settings; a project budget does not set PO pricing.\n\nOn phones, scroll through the draft and line-item dialog carefully, then confirm the saved rows before opening Send via Email. Do not mark an incomplete draft as Sent merely to make it appear finished.","route":"/PurchaseOrders","search_terms":["create purchase order","PO vendor","PO line item","shipping address","unit cost"],"priority":83,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-purchase-order-send","guide-project-materials","guide-vendors-directory"],"source_key":"help_articles_portal"},{"slug":"guide-purchase-order-send","feature_area":"Purchase Orders","audience":"office","question":"Preview, send, and track purchase orders","answer_short":"Share a vendor-facing PO link or email with an optional PDF and understand manual status changes.","answer_long":"## Before you begin\nOpen the saved purchase order from **Purchase Orders**. Confirm the vendor, shipping details, item quantities, costs, and total. Resolve errors while it is a draft; a supplier-facing document should accurately describe the intended order.\n\nSending a purchase order is a real communication to the selected recipient. Review the email address and message before selecting the final send action.\n\n## Preview and send\n1. Open **Actions** on the purchase-order detail page.\n2. Select **Vendor Preview** to review the document in a new tab. Return to the detail page to correct any problem.\n3. Select **Download PDF** if you need a local copy. The vendor-facing view also offers a PDF download.\n4. Choose **Send via Email** to open the **Send PO** dialog.\n5. Confirm **Vendor Email**, subject, message, and signature. The address starts from the vendor record and can be corrected for this send.\n6. Review the optional PDF attachment setting. The email also includes a **View Purchase Order** link.\n7. Use **Copy Link** in the Vendor Portal Link section when you want to share the generated link through your own verified channel instead.\n8. Submit the email only after review and wait for the send result. A successful send flow marks the purchase order **Sent**.\n\n## Understand status actions\n**Mark as Sent** changes the saved status without sending a new email. **Request Approval** asks for an internal decision. **Mark as Approved** captures the approved amount and keeps delivery tracking separate; it does not mark materials physically received. Use it according to your team's process, and do not assume that it represents a vendor's separate acknowledgement or a physical stock receipt.\n\nThe public PO page displays the document and allows a PDF download. It is a vendor-facing view, not a full vendor account or an automated warehouse receiving workflow.\n\n## Troubleshooting and mobile use\nA send error may come from email dispatch, PDF generation, or saving the status. Inspect the error before retrying, and ask the vendor whether they received a message when duplicate sending would be confusing. A saved Sent status alone does not prove inbox delivery. If a link will not open, copy the complete generated URL and have the company administrator review document access. On phones, scroll through all email fields and the attachment option before sending.\n\n## Track supplier and physical delivery\nIn **Purchasing and delivery tracking**, use **Record supplier acknowledgement** when the supplier confirms the order. Set **Expected delivery date**, **Delivery status**, **Delivery notes** and **Cost category**. Delivery status separates Not received, Partial delivery, Delayed, Received and Cancelled. **Cancel order** preserves the cancellation event. Actual receipt and partial delivery are separate from internal approval and a sent email.","route":"/PurchaseOrders","search_terms":["send purchase order","vendor preview","PO PDF","mark as sent","PO approval"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-purchase-order-create","guide-inventory-manage"],"source_key":"help_articles_portal"},{"slug":"guide-change-order-draft","feature_area":"Change Orders","audience":"office","question":"Create and send a clear change order","answer_short":"Document a project scope change with phases, line items, cost/revenue impact, and a client-facing preview before sending; optionally send your company the same formatted email with **Send me a copy**.","answer_long":"## Before you begin\nOpen **Change Orders**. Access depends on your company's plan; an upgrade wall means the feature is unavailable on the current plan. Have an existing project and the proposed change ready. A change order should explain the difference from the original scope, its cost, and any decisions the client needs to make.\n\n## Prepare a draft\n1. Select **New Change Order**; the create action may show as a plus icon on a phone.\n2. Enter the required **Change Order Title** and select **Linked Project**. Review the resolved client and **Issue Date**.\n3. Fill **Reason for Change / Scope** with the reason and overall change description.\n4. Add a phase and its line items. Review names, descriptions, quantities, units, internal costs, client prices, tax choices, and any optional items before relying on the total.\n5. Use **Cost vs Revenue Impact** to distinguish your costs from the amount being proposed to the client.\n6. Review **Client Message** and **Terms & Conditions**, then save the draft. The app assigns its CO number; it is not entered manually.\n\n## Preview and share\nOpen **Actions → Client Preview** to inspect the client document. Check optional selections, photos, scope, and totals. Use **Actions → Send via Email** to review the client email, subject, message, signature, and optional PDF attachment. **Send via Text Message** uses the client phone and a message containing the public review link. Submit only after checking the recipient and wait for the result.\n\nThe list-level **Send to Client** action currently announces a coming-soon module. Use the saved builder's email/text actions instead. **Mark as Sent** changes document status without sending a message.\n\n## Send your company a copy\n\nThe **Send me a copy** checkbox is at the bottom left of the email dialog and starts unchecked. Leave it unchecked to send only the customer email. Tick it to send a separate copy to your company's business email address in **Settings → Branding & PDFs → Email Address**. An owner or administrator can correct a missing or invalid address before sending with this option.\n\nThe copy has the same formatted body, document link, and any included PDF attachments as the customer email. Its subject identifies the saved document and customer, for example: `[COPY] Change Order from LBProjects - Change Order #CO-1001 for Jane Smith`. This option applies to email, not text messages.\n\nIf the client email succeeds but the company copy fails, use **Retry copy** in the open dialog. It retries the captured message without sending another client email. Avoid starting a new send to retry a copy. On mobile, scroll to the dialog footer to reach the checkbox.\n\n## Troubleshooting and mobile use\nIf no project is available, confirm that you are in the correct company and have access to the project. If saving fails, retain the entered scope and inspect the error before creating another draft. A Sent status is not proof that a recipient received an email or text; check the actual send result.\n\nOn a phone, the bottom Actions button includes its text label while the top button may show only a menu icon. Scroll through phases and the totals before sending. Do not treat sending or approval as a general document-signature workflow.\n\n## Review and decision deadlines\nUse **Next Follow-up Date** for subscriber follow-up alerts and **Client Approval Due Date** for approval-deadline alerts. **Actions → Request Internal Review** saves the full change order before requesting a team review. Internal approval for sending is separate from the customer's decision. **Decline Change Order** on the customer page records a decline and optional reason.","route":"/ChangeOrders","search_terms":["create change order","scope change","CO email","change order draft","cost revenue impact","send me a copy","company email copy","copy failed","retry copy"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-change-order-approval","guide-project-overview"],"source_key":"help_articles_portal"},{"slug":"guide-change-order-approval","feature_area":"Change Orders","audience":"office","question":"Review change order approval, change requests, and invoice conversion","answer_short":"Understand the client decision flow and verify project-budget synchronization and invoicing as separate steps.","answer_long":"## Before you begin\nOpen the saved change order and choose **Client Preview**, or use the public review link sent to the client. Review the scope, selected optional phases/items, and calculated total before an approval decision. Approval records a document decision; it is not a general electronic-signature process.\n\n## Client review and change requests\n1. The client opens the full generated review link and checks the scope, prices, selections, and photos.\n2. Optional choices can alter the displayed total before approval. Verify that the intended choices are selected.\n3. The client can select **Download PDF** for a copy of the displayed change order.\n4. To ask for clarification, select **Request Changes**, enter a meaningful description, and submit. The request flow notifies the team; it does not automatically rewrite the change order's line items.\n5. When ready, use the approval action and wait for confirmation. The saved record contains Approved status, selected items, and the recalculated document total.\n6. Your team should open the saved record afterward to verify the decision and address any requested revisions.\n\n## Project-budget updates\nThe builder's **Actions → Mark as Approved** includes a project synchronization step that adds the change's budget impact and attempts to create related project work. Public approval uses a separate save path. Therefore, check the project budget and related work explicitly; an Approved badge alone does not prove every phase, task, or material was synchronized.\n\nDo not repeat Mark as Approved to troubleshoot a sync error. Repeated use can add the budget impact again. Ask the responsible project administrator to inspect the saved document, budget, and any records already created before attempting another operation.\n\n## Invoice conversion\nThe builder's **Convert to Invoice...** menu currently shows a coming-soon notice. The separate internal Change Order View has a **Convert to Invoice** action when the document is Sent or Approved. Use it only after the required approval and review its confirmation; it creates a new draft invoice that must be checked. Conversion is not a payment record and should not be repeated to refresh an existing invoice.\n\n## Troubleshooting and mobile use\nIf a public link says the change order was not found, check the complete URL and document access with the company administrator. A failed approval or change request should be retried only after checking its error and saved state. On phones, review the full scope and totals before using the bottom decision controls.\n\n## Decline or completed decisions\n**Decline Change Order** records a decline with an optional reason. Customer decision controls are hidden while the team is reviewing the document and after a final decision or billing status; an old link cannot reset that decision.","route":"/ChangeOrders","search_terms":["approve change order","request changes","budget sync","change order invoice","optional items"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-change-order-draft","guide-project-overview","guide-project-materials"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-create-save","feature_area":"Quotes","audience":"office","question":"Create and save a quote for a lead or client","answer_short":"Start a quote, select its contact, build the scope in phases, and confirm that your saved draft is available before sharing it.","answer_long":"## Before you start\n\nA quote can be linked to either an existing lead or a client. Have the contact name, site address, scope, quantities, and pricing ready. The quote builder also lets you create a client using the person-plus button beside **Client/Lead**. A quote is a sales document; saving it does not create a project or collect payment.\n\n## Create a draft\n\n1. Open **Quotes** and choose **New Quote**. To reuse an estimate, choose **From Template** instead.\n2. Enter **Title \\***, then choose the correct **Client/Lead**. Confirm **Site Address**, **Issue Date**, and **Expiry Date** rather than relying on the contact's stored address.\n3. Write the **Introduction**. Use **Show to client** to control whether that introduction appears in the customer document.\n4. Under **Phases / Rooms**, choose **Add Phase** and build the work breakdown. Review each phase's items, quantities, prices, taxes, and optional choices.\n5. Add your **Client Message**, **Terms & Conditions**, and any attachments the customer should receive.\n6. Choose **Save Draft**. The builder assigns a quote number when a new quote is first saved; existing quote numbers are displayed as read-only.\n\n## Confirm the save\n\nAfter a successful save, reopen the quote from **Quotes** and check the contact, scope, and total. Treat the success message and a persistent saved record as your confirmation. A title is required; a missing company session also prevents saving.\n\nIf saving fails, keep the builder open and preserve your entered scope. Capture the visible error, check the Quotes list in another tab to see whether a record was created, and avoid creating repeated copies. Retry only after checking your connection and session. If the error continues, contact support with the quote number, page, and error message, excluding sensitive customer information.\n\n## On a phone\n\nThe builder stacks its sections vertically. Scroll through the scope and totals before using the compact Save control. Save before navigating away; an unsaved-change warning is a prompt to review your work, not proof that it has already been saved.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Quotes","search_terms":["new quote","estimate","create quote","draft","save","client lead","title","quote number"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-phases-items","guide-quotes-review-send","guide-templates-quote-library"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-phases-items","feature_area":"Quotes","audience":"office","question":"Build quote phases, rooms, line items, and material scope","answer_short":"Organize the quote into phases, add Pricebook or custom items, and keep customer scope separate from internal notes.","answer_long":"## Organize the work\n\nUse **Phases / Rooms** to group an estimate into work areas such as demolition, kitchen, or finishing. Phases give the customer a readable scope and help the office review costs. They are part of the quote until you deliberately convert it to a project.\n\n## Add phases and items\n\n1. Choose **Add Phase**. Select an available phase template or create the phase, then enter its name.\n2. Expand the phase and open **Settings** when you need the scope, private notes, photos, or optional settings.\n3. Enter **Scope of Work (Client-Facing)** and check its customer visibility setting. Put reminders for your team in the internal notes field instead.\n4. Use the **Pricebook...** selector to bring in an existing product, or add a custom line item. Enter a meaningful item name, description, quantity, unit, unit cost, and unit selling price.\n5. Check the item's tax and optional settings. Where an item is marked as material, confirm its supplier and quantity so that later project conversion has useful material information.\n6. Review the phase cost, margin, tax, and total. Choose **Save Draft** to persist the complete quote.\n\n## Reuse and reorder\n\nThe phase controls offer **Duplicate Phase**, **Delete Phase**, and move-up or move-down actions. Line items can also be duplicated, moved, or removed. Duplicating creates another priced entry, so review quantities and totals after copying. Saving a phase as a template creates reusable scope for future quotes; it is separate from saving the current quote.\n\n## Troubleshooting\n\nAn empty or collapsed phase may hide the item controls. Expand it before assuming the items are missing. A phase or item that is optional and not selected contributes no value to the selected scope. Check both the phase-level and item-level selection if the subtotal seems too low.\n\nPricebook values are copied into quote items. Updating the Pricebook does not justify assuming that every existing quote has changed. Review the copied item prices and use **Refresh Pricing** only deliberately. On mobile, work through one expanded phase at a time and save after a substantial scope change.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Quotes","search_terms":["phases rooms","line items","scope","materials","labour labor","pricebook","quantity","duplicate phase"],"priority":81,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-create-save","guide-quotes-pricing-tax-discount","guide-templates-phase-library","guide-pricebook-create-maintain"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-pricing-tax-discount","feature_area":"Quotes","audience":"office","question":"Review quote costs, margin, tax, discounts, and final totals","answer_short":"Check line-item pricing, optional scope, margin adjustments, tax settings, and customer-facing totals before issuing a quote.","answer_long":"## Start with the item prices\n\nThe quote's base selling value comes from selected item quantities multiplied by unit prices. Its base cost comes from quantities multiplied by unit costs. **Total Cost vs Revenue** shows the relationship, and margin is profit as a percentage of selling revenue. Margin and markup are different measures: a 20% margin on a $100 cost implies a $125 selling price, not $120.\n\n## Review pricing in order\n\n1. Check every selected phase and line item for the correct quantity, unit, cost, and selling price. Optional items only belong in the selected total when selected.\n2. Review **Total Cost vs Revenue** and **Final Margin**.\n3. If needed, use **Adjust Margin (Optional)** and select dollars or percent. Review the effect on the estimate rather than assuming this edits every displayed line price.\n4. Check whether each item is taxable. Company settings provide the primary tax label and rate, with a secondary tax when enabled.\n5. Enter the **Discount** using the dollar or percentage mode. Check the resulting total and **Deposit Required**.\n6. Save, open **Client Preview**, and compare the customer-facing total and downloaded PDF with the amount you intend to offer.\n\n## Verify the customer document\n\nAlways review the customer view after margin overrides, percentage discounts, tax changes, or optional selections. The customer view recalculates selected scope, so its displayed amount is the amount the customer will see. If the builder, preview, and PDF disagree, stop before sending or collecting payment and ask support to review the discrepancy. Include the quote number and which totals differ; do not attempt to compensate by entering an unexplained negative charge.\n\n## Troubleshooting\n\nFor missing tax, check the item's tax checkbox and the company tax settings. For a lower subtotal, check optional phase and item selection. For an unexpected selling price after **Refresh Pricing**, compare the item name against the corresponding Pricebook entry and recheck any special negotiated price. Only authorized administrators should change company-wide tax defaults. A tax calculation in the app is operational information; confirm your company's billing requirements with your responsible finance person.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Quotes","search_terms":["margin","markup","discount","tax","gst","pst","selling price","profit","wrong total","cost revenue"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-phases-items","guide-quotes-review-send","guide-pricebook-create-maintain"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-review-send","feature_area":"Quotes","audience":"office","question":"Preview, email, text, and track a quote","answer_short":"Review the saved customer document, personalize the recipient and message, and distinguish sending a quote from manually changing its status; optionally send your company the same formatted email with **Send me a copy**.","answer_long":"## Review before sharing\n\nOpen the quote in its builder, save your latest changes, then choose **Actions → Client Preview**. Check the contact, address, dates, visible scope, optional choices, images, attached documents, terms, and final total. A preview of an existing quote should be reviewed after saving; opening another tab alone does not guarantee that your unsaved edits are included.\n\n## Send an email\n\n1. Choose **Actions → Send via Email**, or use **Send** from the Quotes list action menu.\n2. Review **To (Client Email)**. The dialog attempts to fill this from the linked client or lead, but you can correct it before sending.\n3. Review **Subject**, **Message**, and **Email Signature**. The outgoing message includes a link to the digital quote.\n4. Submit the send action and wait for its result. A successful send updates the quote to **Sent**; check the recipient with the customer if they still cannot find it.\n\n## Send your company a copy\n\nThe **Send me a copy** checkbox is at the bottom left of the email dialog and starts unchecked. Leave it unchecked to send only the customer email. Tick it to send a separate copy to your company's business email address in **Settings → Branding & PDFs → Email Address**. An owner or administrator can correct a missing or invalid address before sending with this option.\n\nThe copy has the same formatted body, document link, and any included PDF attachments as the customer email. Its subject identifies the saved document and customer, for example: `[COPY] Quote from LBProjects - Quote #Q-1001 for Jane Smith`. This option applies to email, not text messages.\n\nIf the client email succeeds but the company copy fails, use **Retry copy** in the open dialog. It retries the captured message without sending another client email. Avoid starting a new send to retry a copy. On mobile, scroll to the dialog footer to reach the checkbox.\n\n## Send a text\n\nChoose **Actions → Send via Text Message**. Confirm **Mobile Phone Number** and **Text Message**. The dialog includes the quote link with your message. Review the phone number carefully, including the appropriate country information, before choosing **Send Text**.\n\n## Understand status and viewing\n\n**Mark as Sent** changes the quote's workflow status; it does not send an email or text. Likewise, **Mark as Approved** records an office decision and does not create a separate document signature. Customer quote pages support viewing and online approval; delivery, viewing, and approval are separate events.\n\n## Troubleshooting\n\nIf email fails, verify the address and preserve the visible error. If SMS fails, verify the number and wait for a send result before repeating; a Sent status alone is insufficient proof of SMS delivery. Ask the customer to check spam or reopen the original link in a regular browser. If a link is inaccessible or shows incomplete scope, verify that the record was saved and ask support for help. Share only the intended customer document, not an internal builder URL or private notes.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.\n\n## Follow-ups and internal review\nThe builder's **Next Follow-up Date** supports subscriber follow-up alerts. **Actions → Request Internal Review** saves the full document before requesting a team decision. After internal approval, review the customer document and send it. The customer page offers **Decline Quote** with an optional reason; customer acceptance remains separate from internal review.","route":"/Quotes","search_terms":["send quote","email quote","text sms","client preview","pdf","sent","delivery","recipient","viewed","send me a copy","company email copy","copy failed","retry copy"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":4,"related_slugs":["guide-quotes-create-save","guide-quotes-client-options-approval","guide-quotes-find-duplicate-archive"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-client-options-approval","feature_area":"Quotes","audience":"office","question":"Help a customer select quote options, approve, or request changes","answer_short":"Explain optional phases and items, customer approval, change requests, PDF downloads, and when deposit checkout is available.","answer_long":"## What the customer receives\n\nAn emailed or texted quote opens a customer document with scope, pricing, optional selections, company information, and the available actions. This is a quote approval workflow. It is not a general document-signing service, and clicking acceptance is not a drawn-signature workflow.\n\n## Review and select scope\n\n1. Ask the customer to open the quote link from the message in a regular browser.\n2. Review the introduction, each phase, and item details before taking action.\n3. Select or deselect available optional phases and line items. A deselected optional phase excludes its items from the selected scope. Required items remain part of the quote.\n4. Check the recalculated subtotal, tax, discount, and total after changing options.\n5. Use **Download PDF** when a copy of the displayed estimate is needed.\n\n## Approve or request a change\n\nThe customer can choose **Accept Quote** when ready to proceed. The app records **Approved**, selected options, and the resulting totals, and attempts to notify the team. If the customer needs an adjustment, **Request Changes** opens a message dialog. They must describe the requested changes before submitting. That message goes to the team; it does not automatically rewrite the estimate.\n\nOffice staff should review the approved scope before project or invoice conversion. If a customer approves verbally, an authorized office user can record **Mark as Approved**, but should keep the actual agreement in the company's records.\n\n## Deposits and limitations\n\nWhen a deposit payment action is available, it uses the company's configured payment processing. A deposit amount on a quote is a request, not evidence that money was received. Checkout cannot be completed from an embedded preview; open the published customer page instead.\n\n## Troubleshooting\n\nIf the total changes unexpectedly, check the selected optional items and ask the office to clarify the scope before acceptance. If acceptance or a change request returns an error, keep the link and visible message and contact the company; do not assume the request was recorded. An approval does not guarantee that a project, invoice, or payment was created.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.\n\n## Decline or completed decisions\n**Decline Quote** records a decline with an optional reason. Customer decision controls are hidden while the team is reviewing the document and after a final decision or billing status; an old link cannot reset that decision. An Approved quote can still show **Pay Deposit Now** when a deposit amount is present and payment processing is configured.","route":"/Quotes","search_terms":["accept quote","approve quote","optional items","optional phase","request changes","client selection","deposit","signature"],"priority":83,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-review-send","guide-quotes-convert-project-invoice","guide-quotes-pricing-tax-discount"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-convert-project-invoice","feature_area":"Quotes","audience":"office","question":"Convert an agreed quote into a project, invoice, or both","answer_short":"Choose the correct conversion outcome, review the copied scope and materials, and avoid duplicate projects or invoices.","answer_long":"## Choose the outcome\n\nConversion creates new working records from a quote. Use **Project Only** to begin delivery planning, **Invoice Only** to begin billing, or the combined project and invoice option when you need both. Confirm the agreed customer, selected scope, and final total first. Creating another record is a separate action from changing the quote's status.\n\n## Convert from the builder\n\n1. Open the quote and verify the saved scope and customer-facing total.\n2. Ensure the contact is a client if the work requires client-linked project or billing records. Convert a lead through its Lead Detail page when appropriate, then confirm the quote's client link.\n3. Choose **Actions → Convert Quote...**.\n4. Select the desired conversion option and wait for completion.\n5. Open the resulting project or invoice and inspect its name, client, address, totals, phases, and payment schedule.\n\nThe builder's project conversion copies selected phases into project phases and selected line items into project tasks. Items marked as material are also used to create planned material entries, with their quantities, unit, estimated cost, supplier, and notes. Review these entries before assigning work or ordering stock. Conversion is a starting point, not confirmation that staff assignments or purchasing have been completed.\n\n## Check limits and duplicates\n\nProject creation can be subject to your subscription's active-project limit. If a limit message appears, review your plan or existing project statuses with the owner. Do not use repeated clicks or another conversion route to work around a limit.\n\nDifferent quote views offer conversion actions, and their copied details can differ. Prefer the builder when you need to review project phases, tasks, and materials from your estimate. Inspect the created record in every case.\n\n## Troubleshooting\n\nIf conversion fails or a follow-up page does not open, check the Projects and Invoices lists before retrying. Some steps may have completed before the error appeared. Record the quote number and any created project or invoice number for support. Conversion does not provide an automatic merge with an existing project, and repeating it can create a duplicate. Verify materials and payment milestones after any partial conversion.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Quotes","search_terms":["convert quote","project only","invoice only","project invoice","accepted quote","materials tracker","planning"],"priority":83,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-client-options-approval","guide-invoices-create-edit","guide-quotes-phases-items"],"source_key":"help_articles_portal"},{"slug":"guide-quotes-find-duplicate-archive","feature_area":"Quotes","audience":"office","question":"Find, duplicate, archive, decline, or expire quotes","answer_short":"Use quote search, active and archived views, status filters, and duplication to keep your quote list organized.","answer_long":"## Find the right quote\n\nThe **Quotes** page separates **Active** and **Archived** records. Declined and expired quotes are included in the archived view even when you did not manually archive them. Quote templates live in **Templates**, so they do not appear in the normal Quotes list.\n\n1. Choose **Active** or **Archived** first.\n2. Search using a title, quote number, client or lead name, or site address.\n3. Use the **Status** filter to narrow the list. Active choices include Draft, Sent, and Approved; the archived filter offers Declined and Expired.\n4. Use the sort selector for newest/default order, A–Z, or Z–A.\n5. Open a quote title or card to reach its builder. Desktop supports list and card views; phones display quote cards.\n\n## Duplicate deliberately\n\nChoose **Duplicate** from the quote's action menu. Select the destination client or lead using the search control, then confirm. Duplication copies the quote and its related scope into a new record. Review the title, recipient, dates, prices, attachments, terms, and payment schedule before issuing it. Copying an old quote does not verify that its pricing or terms are still current.\n\n## Update status or archive\n\nUse **Mark Declined** or **Mark Expired** to record that outcome; those actions also move the quote into the archived group. **Archive** hides a quote from the active group without deleting it. **Unarchive** removes the manual archive flag, but a quote still marked Declined or Expired continues to meet the archived-view rules. Review its status if you intend to resume active negotiation.\n\n## Troubleshooting and deletion\n\nFor a missing quote, clear the search and status filter, check both views, and check Templates if it was saved as a template. A quote can be present but excluded by the current filter. If it still cannot be found, ask the office to confirm your role, company, and whether it was deleted.\n\n**Delete** removes the record and is different from archiving. Use it only when your company has decided the quote is unnecessary; prefer archiving for ordinary record keeping. Confirm the specific quote number before deletion. Do not assume a deleted quote can be recovered from Archived.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Quotes","search_terms":["search quotes","archive quote","unarchive","declined","expired","duplicate estimate","copy quote","missing quote"],"priority":78,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-create-save","guide-templates-quote-library","guide-quotes-review-send"],"source_key":"help_articles_portal"},{"slug":"guide-templates-quote-library","feature_area":"Templates","audience":"office","question":"Create and reuse complete quote templates","answer_short":"Store reusable whole estimates and start new quotes from them while reviewing customer-specific details and current pricing.","answer_long":"## Choose a template type\n\nThe **Templates** page has **Quote Templates** and **Phase/Room Templates**. A quote template is a reusable whole estimate, including its phases and items. A phase template is a smaller work package that you can insert into another quote. Choose the size of template that matches the work you repeat.\n\n## Create a whole quote template\n\n1. Open **Templates → Quote Templates** and choose **New Template**.\n2. Enter **Template Name \\*** in the builder and add the standard introduction, phases, item descriptions, quantities, prices, photos, documents, customer message, and terms.\n3. Review default optional selections and any payment schedule.\n4. Save the template. You can also open a useful existing quote and choose **Actions → Save as Template** to create a library copy.\n5. Return to Quote Templates and search for the saved name. Open it to maintain its reusable scope.\n\n## Start a customer quote\n\nFrom Quotes or a client/lead page, choose **From Template** or **Quote from Template**. In **Create Quote from Template**, select the template. Select a client when the dialog offers that field, or use the contact already supplied by the client/lead page. Choose **Create Quote** to open the builder, then check the customer, title, dates, address, prices, and terms before saving the new quote.\n\nInside an existing quote, **Import Template** can append template scope. It can also bring in payment-schedule entries and supporting content. Review the result so you do not accidentally duplicate phases or payments that were already present. Verify the imported phase names and scope text, and restore any missing details before saving or sending.\n\n## Troubleshooting\n\nIf the selector says no templates are available, create and save a quote template in the same company. Saving a normal Draft quote does not make it a template. Updating a template is maintenance for future reuse; review already-created quotes separately rather than assuming they changed automatically. If imported scope appears twice, remove the unintended copy before saving.\n\nOn mobile, search by a distinctive template name and review the entire imported estimate before sending. A reusable template should contain standard scope, not confidential details copied from another customer's project.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Templates","search_terms":["quote template","new template","save as template","from template","import template","estimate library"],"priority":79,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-templates-phase-library","guide-quotes-create-save","guide-quotes-find-duplicate-archive"],"source_key":"help_articles_portal"},{"slug":"guide-templates-phase-library","feature_area":"Templates","audience":"office","question":"Create and maintain phase or room templates","answer_short":"Save repeatable phase scope with line items, then reuse it in quotes without rebuilding the same work package.","answer_long":"## When to use a phase template\n\nA **Phase/Room Template** stores a repeatable work package such as a bathroom demolition or painting scope. It includes a template name, phase name, scope, and reusable line items. Use it when the same package appears in several different quotes; use a complete Quote Template for an entire standard estimate.\n\n## Save an existing quote phase\n\n1. Open a quote with a phase you want to reuse.\n2. Review the phase's name, scope, quantities, pricing, tax settings, and optional items.\n3. Use the phase's save-as-template action beneath the phase.\n4. Enter **Template Name \\*** and an optional description, then save.\n5. Open **Templates → Phase/Room Templates** and confirm the package appears.\n\nWhen saving from the quote builder, using the exact name of an existing company phase template updates that template. Use a different name if you intend to keep both versions.\n\n## Maintain the library\n\nThe Phase/Room Templates tab lets you create or edit a phase template. Review **Phase Name**, **Scope of Work**, and its line items. Items can be reordered, duplicated, removed, or given photos. Save when the package is complete. Search matches the template name or phase name, so give both clear descriptive names.\n\nTo use the template in a quote, choose **Add Phase** and select the available package. Recheck the imported quantities, item descriptions, costs, selling prices, and materials for that job. Template defaults are a starting point, not a substitute for the customer's actual measurements or current supplier prices.\n\n## Troubleshooting\n\nIf a template contains no items, open it and verify that the line-item changes were saved. If the desired version has changed, check whether someone saved another phase with the same template name. Avoid keeping several indistinguishable names; use names that show the work type or package version.\n\nDeleting a library template is different from removing a phase in an individual quote. Check which record you are editing before choosing Delete. On a phone, review one item at a time and save after finishing the package so incomplete editing does not become the next customer's starting point.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Templates","search_terms":["phase template","room template","scope template","line item library","save phase as template"],"priority":77,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-templates-quote-library","guide-quotes-phases-items","guide-pricebook-create-maintain"],"source_key":"help_articles_portal"},{"slug":"guide-pricebook-create-maintain","feature_area":"Pricebook","audience":"office","question":"Create and maintain Pricebook products and pricing","answer_short":"Maintain reusable items with costs, selling price, margin, taxability, units, supplier details, and a clear category structure.","answer_long":"## What the Pricebook stores\n\n**Pricebook** contains reusable products and services for quotes. It is a pricing catalog, not a stock count. Use Inventory for on-hand quantities and stock movements. Pricebook item costs and selling prices are copied into quote scope when you select an item.\n\n## Add or edit an item\n\n1. Open Pricebook and choose the new-item button. On mobile, open the header menu for item and category actions.\n2. Enter **Item Name \\*** and choose **Main Category**, **Sub Category**, and **3rd Category** where useful.\n3. Set **Unit** to the unit you actually estimate, such as each or an area unit.\n4. Enter **Material Cost** and **Labor Cost**. Their sum feeds **Total Cost**; you can also edit total cost directly.\n5. Review **Margin** and **Client Pays**. The app uses gross margin: cost divided by one minus the margin rate. Changing Client Pays recalculates the displayed margin.\n6. Add **SKU / Item #**, **Supplier / Vendor**, **Supplier Link / URL**, **Description & Notes**, and an image when helpful.\n7. Check **Taxable** and save the item.\n\n## Keep the catalog usable\n\nSearch by product name or SKU and use category or supplier filters. Category actions let you add a category level or rename an existing category and its associated products. Use a consistent naming convention so staff can distinguish similar products and units.\n\nReview prices whenever supplier costs change. Existing quotes have copied prices; check them individually before sending. **Refresh Pricing** in the quote builder looks for matching product names, so renamed items or negotiated quote prices need particular care.\n\n## Troubleshooting\n\nIf a price looks wrong, confirm the cost components, margin mode, and unit before correcting it. A high margin is not a percentage added directly to cost. If the item cannot be saved, preserve the visible error and ask support to check your access or setup. Do not repeatedly create the same name to bypass a save problem. Removing a catalog item does not mean you should delete historical customer scope; review any existing quote separately.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Products","search_terms":["pricebook","products","new item","sku","material cost","labor cost","margin","client pays","supplier","category"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-pricebook-import-export","guide-quotes-phases-items","guide-quotes-pricing-tax-discount"],"source_key":"help_articles_portal"},{"slug":"guide-pricebook-import-export","feature_area":"Pricebook","audience":"office","question":"Import, export, and safely update Pricebook CSV files","answer_short":"Use the Pricebook export as a starting format and preserve item IDs when updating an existing catalog through CSV.","answer_long":"## Prepare a controlled update\n\nPricebook supports CSV import and export. Exporting first gives you a useful record of the items you can currently see and their IDs. Keep a copy of that file before editing so you can compare the intended changes. Export operates on the current sorted and filtered product results; clear filters when you need the whole visible catalog.\n\n## Export and edit\n\n1. Open Pricebook, clear unintended filters, and choose **Export CSV**.\n2. Open the file in your spreadsheet application while preserving text fields such as SKUs and IDs.\n3. Keep the header row. Exported columns include ID, Name, SKU, Category, Sub Category, 3rd Category, Unit, Material Cost, Labor Cost, Total Cost, Price, Supplier, Vendor URL, Taxable, and Image URL.\n4. Change only the fields you intend to update and save as CSV.\n\n## Import carefully\n\nChoose **Import CSV** and select the file. A recognizable **Name** column is required. The importer matches existing items by ID when provided; otherwise it tries an exact name match without considering letter case. Rows that match an existing item update that item, and unmatched rows can create new products. A change to the name without retaining the original ID can therefore create an unintended duplicate.\n\nStart with a small file and verify the results before importing a large catalog. Imported monetary values are parsed from their text; check decimal values, units, cost components, and supplier URLs after import. The current importer makes imported rows taxable by default, so review taxability in the item editor rather than assuming the exported Taxable column round-trips unchanged.\n\n## Troubleshooting\n\nFor “Could not find a Name column,” restore the original header structure. For no valid products, check that rows have a name and are not blank. If an import fails partway, inspect the catalog before trying again because earlier groups may already have saved. Reuse stable IDs when repeating an update.\n\nCSV import is a data update, not a preview-only action. Do not use another company's IDs or a customer list as a Pricebook file. After bulk price changes, review any quotes that need the new pricing; saved quotes are separate records.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Products","search_terms":["pricebook csv","import products","export products","bulk pricing","id column","spreadsheet","sku"],"priority":79,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-pricebook-create-maintain","guide-quotes-pricing-tax-discount"],"source_key":"help_articles_portal"},{"slug":"guide-resource-library-upload-attach","feature_area":"Resource Library","audience":"office","question":"Upload company resources and attach them to quotes","answer_short":"Maintain flyers, licenses, blank forms, and supporting documents in Resource Library, then choose which files belong on a customer quote.","answer_long":"## Choose the right document\n\n**Resource Library** stores company files such as flyers, certificates, and blank forms. It is a file library, not a warranty-claim workflow or general electronic-signature service. Uploading a warranty document does not create claim tracking, and uploading a form does not make it automatically fillable or signable.\n\n## Upload a resource\n\n1. Open Resource Library and choose **Upload File**.\n2. Enter **Document Name \\*** using a clear title, such as the document type and version or year.\n3. Choose **Link to Project (Optional)** if the file relates to a particular project, or leave **General Document (Available for all)**.\n4. Choose **Attachment \\*** and browse for the file. The dialog describes common formats such as PDF, DOCX, or images.\n5. Choose **Save Document**, wait for upload completion, and confirm the new record in the library.\n6. Use **View** to verify that the file opens correctly before attaching or sharing it.\n\n## Find and attach files\n\nSearch matches the resource title and original filename. The library shows ten records per page; use the page controls when the desired file is not on the current page. Changing the search returns you to the first page.\n\nIn a quote builder, open the resource picker under **Attached Documents**. Search **Company Resources**, choose **Attach** beside the intended file, then save the quote. Attaching is a deliberate customer-document choice. A project link in the library organizes the resource; it should not be treated as proof that the file has been distributed to the customer or as a substitute for access controls.\n\n## Troubleshooting\n\nIf upload fails, keep the exact visible message and check whether the document record appeared before uploading again. Verify your connection and permission, then contact support if the issue continues. If a file opens incorrectly, confirm that you selected the right original file and format.\n\nThe delete control removes the library record after confirmation. It is not a promise to recall files already attached, downloaded, or shared. Keep appropriate company records and avoid uploading sensitive information unless your company intends to store and share it in this workflow.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/ClientForms","search_terms":["resource library","client forms","upload file","document","wcb","license","warranty document","attach quote"],"priority":76,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-quotes-review-send","guide-quotes-create-save"],"source_key":"help_articles_portal"},{"slug":"guide-leads-create-follow-up","feature_area":"Leads","audience":"office","question":"Create a lead and organize the next follow-up","answer_short":"Capture lead contact details, source, stage, owner, photos, estimated value, and follow-up date without creating avoidable duplicates.","answer_long":"## Capture the opportunity\n\nUse **Lead Tracker** for prospective work that has not yet become a client job. A lead stores contact information, sales stage, source, estimated value, priority, a next-follow-up date, and an assigned team member. Keeping these fields current helps the team distinguish a new enquiry from an opportunity already being handled.\n\n## Create a lead\n\n1. Open Lead Tracker and choose the yellow **New Lead** button. On a narrow phone, this appears as the plus button labelled Create a new lead.\n2. Enter **First Name \\*** and **Surname \\***, then the email and phone number if available.\n3. Choose **Source**, **Priority**, and **Pipeline Stage**. A new enquiry normally starts as New; use the stage that represents the actual sales progress.\n4. Enter **Value Estimate**, **Next Follow Up Date**, and **Assign Team Member** where useful. The estimate is an opportunity value, not an invoice or received payment.\n5. Confirm **Site / Project Address**, add a description, notes, and any site photos.\n6. Save the lead and confirm that it appears in the tracker or opens correctly in Lead Detail.\n\n## Handle a duplicate warning\n\nFor an entered email, the form checks existing clients and leads in the same company. If it finds a match, review the existing profile before choosing **Create Duplicate Anyway**. The warning is intended to help you update an existing record instead of splitting its history across several profiles. It is not a complete identity check; records without email or bulk imports need manual review.\n\n## Follow up and troubleshoot\n\nOpen the lead card to review its detail page, update the follow-up date, and create a task or note for the next action. A saved date is not proof that a phone push notification or an email reminder has been sent. Use the task and notification workflows your company actually has configured.\n\nIf saving or uploading fails, preserve the visible error and check whether the lead was created before retrying. If the card is missing, clear search and stage filters. Verify failed photos individually rather than assuming that a saved lead contains every selected image.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.\n\n## Assignment, meetings and reminder dates\n**Assigned To** saves a company user's identity and displays their name. **Next Meeting Date** and **Next Meeting Time** schedule the lead meeting in company local time. **Next Follow-up** drives approaching, due and overdue reminders. A changed meeting and a lead follow-up are separate events; update each field when the plan changes.","route":"/LeadTracker","search_terms":["lead tracker","new lead","contact","source","priority","assigned team","follow up","duplicate lead"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-leads-pipeline-find-import","guide-leads-detail-convert","guide-quotes-create-save"],"source_key":"help_articles_portal"},{"slug":"guide-leads-pipeline-find-import","feature_area":"Leads","audience":"office","question":"Use the lead pipeline, search, and CSV import","answer_short":"Move opportunities through verified sales stages, find Won or Lost leads, and import CSV records without expecting an automatic merge.","answer_long":"## Understand the stages\n\nLead Tracker uses **New**, **Contacted**, **Booked Visit**, **Quoted**, **Negotiation**, **Won**, and **Lost**. The main Kanban board displays the five active sales stages. Won and Lost records are terminal outcomes rather than active negotiation columns, so switch view or filter when looking for those records.\n\n## Navigate the pipeline\n\n1. Use **Search leads...** for contact name, email, or description.\n2. Use **Filter Stage** to narrow the records, or choose **All Stages** to clear it.\n3. Choose the list or Kanban view that suits your work. Desktop cards support dragging between active columns; cards also offer a stage selector.\n4. On mobile, tap a stage heading to expand its group. Booked Visit starts expanded; other collapsed groups can contain leads even when you cannot initially see their cards.\n5. Open a card to inspect the contact and full history before changing its stage.\n\nMoving a lead to Won through the tracker's confirmation flow creates a client record. Lost records remain a recorded outcome. Review the confirmation rather than using Won merely as a color or label change. If you need to carry detailed notes, files, and quote links into a client, review the Lead Detail conversion guide first.\n\n## Import and export\n\nChoose **CSV Template** for the supported file layout, then **Import** to select a CSV. Columns include Contact Name, Contact Email, Contact Phone, Stage, Value Estimate, Source, and Description. Stage defaults to New when omitted. The importer inserts records; it does not promise to match or merge existing leads by email. Use a small sample and check for duplicates before a large import.\n\nThe download control exports the filtered results. Clear unintended filters when you want a fuller list. Although the file picker accepts spreadsheet extensions, the current import processing is CSV text; save your spreadsheet as CSV first.\n\n## Troubleshooting\n\nFor a missing card, clear the search and filter, expand mobile stage groups, and inspect the list view. For import errors, compare the header spelling with the template and check that rows contain names. Inspect the tracker after any failed import before repeating it, so the same enquiries are not created twice.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/LeadTracker","search_terms":["kanban","pipeline","new contacted booked visit quoted negotiation won lost","lead csv","import","search"],"priority":79,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-leads-create-follow-up","guide-leads-detail-convert","guide-clients-create-organize"],"source_key":"help_articles_portal"},{"slug":"guide-leads-detail-convert","feature_area":"Leads","audience":"office","question":"Manage lead history and convert a lead to a client","answer_short":"Keep notes, tasks, photos, files, and quotes together, then review what the selected conversion route transfers to the new client.","answer_long":"## Work from the detail page\n\nOpen a lead from Lead Tracker to view its contact details, stage, priority, estimated value, follow-up information, notes, tasks, quotes, photos, and documents. Use **Edit** to correct the contact or sales details. On mobile, some actions move into the header menu; open it before assuming an action is unavailable.\n\n## Record the next action\n\n1. Use **Create → Add Note** for a call, email, meeting, update, or general internal note. Pin a note when it needs to stay prominent.\n2. Use **Create → Add Task / Request** for work that needs an owner and completion tracking. Review the assignee, due date, priority, and status.\n3. Use **Create → Quote** or **Quote from Template** to prepare an estimate linked to the lead.\n4. Add site photos and documents, then confirm that each uploaded file opens and has a useful description.\n\nNotes are history; tasks are work to be followed through. Changing a task's status does not automatically update the lead's sales stage or send a customer message.\n\n## Convert deliberately\n\nFrom Lead Detail, choose **Convert to Client** only after confirming that the lead should become a client and that the correct client does not already exist. This route creates a client, marks the lead Won, copies lead notes and files, and attempts to relink lead quotes to the client. Open the resulting Client Detail page and verify contact information, billing/site addresses, notes, attachments, and quotes.\n\nThe Lead Tracker's Won confirmation also creates a client, but it is a different conversion route and should not be assumed to transfer the same detailed history. Use the detail workflow when you need to review that history, and check the result either way.\n\n## Troubleshooting\n\nConversion is not an automatic merge into an existing client. If an error appears or navigation stalls, check Clients for a new record and inspect the lead before retrying. Repeating conversion can create another client. If photos, notes, or quotes are missing afterward, keep both record names and the visible error for support. Do not delete the original lead while resolving incomplete transfers.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.\n\n## Incoming communication\nOpen **Communications** for **Send Email**, **Log Communication** and **Add Reminder**. **Needs reply** identifies an incoming message awaiting a response. **Reply by email** links the selected incoming message to that send and clears its reply requirement only after confirmed delivery. **Mark handled** records explicit manual resolution. History shows **Delivery failed** when appropriate, and failed sends retain the draft. Automatic email reply capture requires verified receiving configuration; when unavailable, replies use your configured company email address. Lead conversion saves its linked client identity; verify the new client before proceeding.","route":"/LeadTracker","search_terms":["lead detail","convert to client","won lead","lead notes","lead tasks","lead photos","documents","quote lead"],"priority":83,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-leads-create-follow-up","guide-clients-detail-workflows","guide-quotes-create-save"],"source_key":"help_articles_portal"},{"slug":"guide-clients-create-organize","feature_area":"Clients","audience":"office","question":"Create, edit, find, and organize clients","answer_short":"Maintain accurate contact and address details, search the client list, use segments, and handle CSV imports with care.","answer_long":"## Keep a single useful client record\n\nClients links a customer's contact information to their quotes, projects, invoices, tasks, and files. Search for an existing profile before adding another, especially after a lead has been converted. Duplicate clients can split the same customer's work and payment history across several records.\n\n## Add or correct a client\n\n1. Open **Clients** and choose **New Client**. On mobile, look for the plus button.\n2. Enter **First Name \\*** and **Surname \\*** in the new-client form, choose the type, and add **Primary Contact**, **Email**, and **Phone**.\n3. Complete **Site Address (Project Address)** and the billing address. Use the same-as-site option only when it is correct; the invoice recipient and job site may differ.\n4. Add useful notes and save. Review any duplicate-email warning before deliberately creating another profile.\n5. To correct an existing client, use **Quick Edit** for the compact contact fields or **Full Edit** for the complete form. Save rather than just closing the editor.\n\n## Search and segments\n\nSearch clients by name, email, or primary contact. Filters include type, location, and tags; sorting offers default/newest, A–Z, and Z–A. Desktop **Save Segment** stores your filter combination and **Load Segment** restores it. A segment is a saved view, not a new collection of client copies. Shared segments can be visible to the company. Clear the active segment or filters when a client appears missing.\n\n## CSV handling\n\nUse **CSV Template** and **Import** for a CSV with Name, Type, Primary Contact, Email, Phone, Billing Address, Site Address, and Notes. Import inserts client rows; it does not automatically merge by email. Export uses the currently filtered results, so clear filters for a broader list. Start with a small sample and inspect it before importing more.\n\n## Troubleshooting\n\nIf saving fails, preserve the details and check whether the client already appeared before retrying. If import fails, inspect the list for partially created or duplicate records. Delete is different from removing a filter; verify the client and its linked history before deleting anything.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Clients","search_terms":["new client","edit client","client search","billing address","site address","segments","client csv","quick edit"],"priority":81,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-clients-detail-workflows","guide-leads-detail-convert","guide-invoices-create-edit"],"source_key":"help_articles_portal"},{"slug":"guide-clients-detail-workflows","feature_area":"Clients","audience":"office","question":"Use Client Detail as the customer work hub","answer_short":"Find the client’s linked work, create customer-specific quotes or tasks, and distinguish private notes from shared documents.","answer_long":"## Open the customer's hub\n\nChoose a client from **Clients** to open Client Detail. It brings together the customer's contact and address information, tasks and requests, projects, quotes, invoices, change orders, photos, documents, and internal notes. Check the client name and email before creating work so you do not link it to a similarly named customer.\n\n## Create linked work\n\n1. Use **Edit** to correct the contact, billing address, site address, type, or internal notes.\n2. Open **Create** for **Add Note**, **Add Task**, **Create Quote**, **Quote from Template**, **Create Invoice**, or **Create Project**.\n3. Review the customer and site details in the resulting builder; starting from a client page helps preselect the client but does not remove the need to check the form.\n4. Save the new record and confirm it is listed under the relevant Client Detail section.\n\nEach workflow still has its own access rules. If invoice creation is unavailable for your role, ask an authorized billing user to perform it. A Create action shown in a customer hub is not a guarantee that your role can complete every downstream action.\n\n## Review history and files\n\nOpen project cards to reach the project workspace and quote cards to reach the quote builder. Invoice summaries show total, balance due, and status. Use the Invoices workspace for detailed payment management rather than treating the summary as a complete ledger.\n\nFor tasks, review the owner, priority, due date, and status and use the edit control when the assignment needs correction. Add notes with the appropriate note type and pin significant history. Notes labelled internal are for the team; they do not automatically become customer correspondence. Verify uploaded photos and documents before deliberately sharing them through a customer-facing workflow.\n\n## Troubleshooting\n\nA record only appears here when linked to this client. If a quote or project exists elsewhere but is missing from the hub, inspect its client link. A quote still linked to a lead may need the lead conversion or an office review of its association. Clear errors before repeatedly recreating work. For a missing attachment, check that its upload completed and that you opened the intended customer.\n\nOn mobile, scroll through the separate sections and expand the header action menu for additional commands.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.\n\n## Customer communication\nOpen **Communications** for **Send Email**, **Log Communication** and **Add Reminder**. Review **Needs reply**, choose **Reply by email** to respond to the selected incoming message, or **Mark handled** for manual resolution. Only confirmed delivery resolves a linked email reply. **Delivery failed** preserves the failure in history. Automatic receiving email capture requires verified configuration; when unavailable, replies use your company email address.","route":"/Clients","search_terms":["client detail","customer hub","client tasks","client notes","client photos","create invoice","create project","linked records"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-clients-create-organize","guide-quotes-create-save","guide-invoices-create-edit","guide-leads-detail-convert"],"source_key":"help_articles_portal"},{"slug":"guide-invoices-create-edit","feature_area":"Invoices","audience":"office","question":"Create or edit an invoice and review the saved billing scope","answer_short":"Select the client, choose invoice dates and payment terms, import quote scope when appropriate, and confirm that the saved invoice is complete.","answer_long":"## Who can manage invoices\n\nThe Invoices workspace is available to owners, administrators, and office users. Managers can have other project and sales access without access to this billing list. Ask an authorized billing user when your role cannot open it.\n\n## Build the invoice\n\n1. Open **Invoices & Payments** and choose **Create New Invoice**, or open an existing invoice number. On a phone, the new action can appear as a plus icon.\n2. Select **Client \\*** before importing quote scope.\n3. Review **Billing Address**, **Site Address**, and **Issue Date**.\n4. Choose **Payment Terms**: Due on Receipt, Net 15, Net 30, Net 60, or Custom Date. For a custom term, enter **Custom Due Date**.\n5. Use **Import from Quote** if this invoice should draw scope from an existing quote for the selected client. Review the imported phases and items rather than assuming every quote option belongs on the invoice.\n6. Add or edit phase scope and any additional item, then review discount, tax, contract total, amount paid, and balance due.\n7. Add **Note to Client** only if you intend it to appear, using **Show on Invoice**. Keep private reminders in **Internal PM Notes**.\n8. Save, then confirm the invoice appears in the Invoices list and reopens with the intended details.\n\n## Confirm persistence before sharing\n\nSelecting Draft, Sent, Paid, Overdue, or Cancelled is a status change; it is not proof that a send, payment, or cancellation with a processor happened. Payment records are the evidence for money received. Review the customer preview and PDF after saving.\n\n## If Save or preview fails\n\nKeep the builder open and preserve the information you entered. Check the invoice list in another tab to see whether the invoice or changes were saved before repeating an action. Capture the visible error and intended invoice number. Verify the connection and session, then ask support if the problem persists. Do not recreate the invoice several times or send an incomplete draft to bypass the error.\n\nImporting a quote is a billing-scope action; it does not replace the separate project-delivery workflow.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Invoices","search_terms":["create invoice","invoice builder","save invoice","import quote","payment terms","due date","billing address","draft"],"priority":85,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-invoices-milestones-ledger","guide-invoices-share-customer-pay","guide-quotes-convert-project-invoice"],"source_key":"help_articles_portal"},{"slug":"guide-invoices-milestones-ledger","feature_area":"Invoices","audience":"office","question":"Set invoice payment milestones and record progress payments","answer_short":"Break the contract into payment milestones and apply actual payments to either a milestone or the overall invoice balance.","answer_long":"## Separate the schedule from money received\n\nA payment milestone describes what should be collected and when. It does not itself record a payment or charge the customer. Actual payment records determine amount paid, balance due, and paid or partial statuses. Review both before deciding that a project payment is complete.\n\n## Add milestones\n\n1. Open the invoice builder and review the contract total.\n2. Under **Payment Schedule**, choose **Add Milestone**.\n3. Enter **Payment Name \\***, choose or type **Due Event / Milestone**, and select a fixed dollar amount or percentage.\n4. Choose **Save Item** and review the displayed schedule amounts.\n5. Edit or remove unintended entries and save the complete invoice.\n\nRecheck the schedule after changing the invoice total. Percentage entries depend on that total, and the builder may adjust an unpaid entry to balance the schedule. Do not assume a previously agreed milestone amount remained unchanged after scope or pricing edits. Preserve paid payment history when discussing schedule changes with the finance person.\n\n## Record an actual payment\n\nFrom the invoice action menu on **Invoices**, choose **Record Payment**. The dialog asks **Which Scheduled Payment is this for? (Optional)**. Select a milestone when the payment belongs there, or **Apply to Overall Balance** when it does not. Enter **Date Received \\***, **Amount Received \\***, **Payment Method**, and **Reference Notes**, then save.\n\nRecording or editing a payment recalculates the invoice and milestone balances from its payment records. A payment applied to the overall balance reduces the invoice total due but does not necessarily complete an individual milestone. Check the chosen allocation if the invoice and milestone statuses look different.\n\n## Troubleshooting\n\nCheck Payments History before recording money that may already have arrived online. Duplicate manual and online records can overstate the amount collected. Enter the amount actually received, not an estimate or future promise. If saving fails, inspect the ledger before retrying and keep the visible error for support. If a milestone remains Pending despite a payment, verify its allocation and compare its required amount with the total allocated to it.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Invoices","search_terms":["progress billing","payment schedule","milestone","record payment","ledger","partial","paid","balance due"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-invoices-create-edit","guide-payments-history-corrections-receipts","guide-invoices-share-customer-pay"],"source_key":"help_articles_portal"},{"slug":"guide-invoices-share-customer-pay","feature_area":"Invoices","audience":"office","question":"Share an invoice and help the customer use payment checkout","answer_short":"Review the saved invoice, email or text the intended customer, and explain balance or milestone checkout without assuming a send means payment; optionally send your company the same formatted email with **Send me a copy**.","answer_long":"## Review the saved document\n\nBefore sharing, confirm the invoice is saved and reopens with its correct client, number, addresses, scope, dates, payment schedule, total, and balance. Use **Client Preview** or **Download PDF** to inspect the customer document. Do not share an incomplete draft while a save error remains unresolved.\n\n## Email or text\n\n1. Open the invoice's sharing menu and choose **Send via Email** or **Send via Text Message**.\n2. For email, review **To (Client Email)**, **Subject**, **Message**, and **Email Signature**. Correct any auto-filled contact information before sending.\n3. For text, review **Mobile Phone Number**, **Text Message**, and the included invoice link before submitting.\n4. Wait for the send result. Ask the customer to check their spam folder or reopen the original message if needed.\n\nSending and payment are separate events. A Sent status is a workflow label; the payment ledger and processor confirmation establish whether money was received.\n\n## Send your company a copy\n\nThe **Send me a copy** checkbox is at the bottom left of the email dialog and starts unchecked. Leave it unchecked to send only the customer email. Tick it to send a separate copy to your company's business email address in **Settings → Branding & PDFs → Email Address**. An owner or administrator can correct a missing or invalid address before sending with this option.\n\nThe copy has the same formatted body, document link, and any included PDF attachments as the customer email. Its subject identifies the saved document and customer, for example: `[COPY] Invoice from LBProjects - Invoice #INV-1001 for Jane Smith`. This option applies to email, not text messages.\n\nIf the client email succeeds but the company copy fails, use **Retry copy** in the open dialog. It retries the captured message without sending another client email. Avoid starting a new send to retry a copy. On mobile, scroll to the dialog footer to reach the checkbox.\n\n## Customer payment flow\n\nWhen online payment is available, the customer document opens secure checkout through the company's payment processor. The amount depends on the document: the public progress-billing view can offer the next unpaid milestone less its allocated payments, while another invoice view can offer the remaining balance. The customer should check the amount shown on the page and again in checkout before proceeding.\n\nCustomers can also download the displayed PDF and review payment history. The office should confirm a completed transaction in the processor and the app ledger before marking the payment resolved. A success message or return to the invoice page alone should not replace that check.\n\n## Troubleshooting\n\nIf checkout is unavailable, ask the company's authorized administrator to confirm payment setup. If the customer reports an error after submitting card information, verify whether the processor recorded a charge before asking them to try again. For an incorrect amount, check milestone allocation and the invoice balance first.\n\nFor a link that will not load, confirm the intended invoice and original link and contact support with the invoice number and visible error. Do not request card details by email or place them in invoice notes.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Invoices","search_terms":["send invoice","email invoice","text invoice","public invoice","pay now","checkout","pdf invoice","payment failed","send me a copy","company email copy","copy failed","retry copy"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-invoices-create-edit","guide-invoices-milestones-ledger","guide-payments-connect-and-refunds"],"source_key":"help_articles_portal"},{"slug":"guide-payments-history-corrections-receipts","feature_area":"Payments","audience":"office","question":"Review payment history, correct records, and send receipts","answer_short":"Find payments by client or invoice, distinguish ledger corrections from refunds, and send receipts for selected recorded payments.","answer_long":"## Find a payment\n\nOpen **Invoices & Payments → Payments History**. Search by client name or invoice number, then use date range and payment-method filters. The table shows invoice, client, amount, method, notes, and date paid. These are recorded payments; their presence should be reconciled with actual bank or processor receipts.\n\n## Correct a record\n\n1. Confirm the invoice and payment reference before changing anything.\n2. Choose **Edit Payment** from the payment's action menu.\n3. Review the received date, amount, method, reference notes, and milestone allocation, then save.\n4. Check the invoice and milestone balances after the update.\n\nUse **Delete Record** only to remove an incorrect ledger entry. The confirmation states that this adjusts the invoice balance. It deletes a record and recalculates balances; it does not send money back to the customer. If the payment was real, discuss the correction with the person responsible for company finances before altering its history.\n\n## Send a receipt\n\nFrom Payments History, choose **Send Receipts**. Select the client, then select the specific payments to include. Review the combined selected amount, continue to the message step, and check **To (Client Email)**, **Subject**, and **Message** before choosing **Send Receipt**. The workflow produces an emailed receipt for selected recorded payments. It does not collect another payment or correct the underlying ledger.\n\nIf no payments are available, ensure you selected the client whose invoices contain the payments. A client with a similar name may be a different record. Confirm that the intended payment has been recorded and linked to the correct invoice.\n\n## Troubleshooting\n\nFor a payment that seems missing, clear search and date/method filters and inspect the relevant invoice. For a wrong balance, look for duplicate entries or an incorrect amount. For a milestone that remains unpaid, review its allocation rather than simply deleting and recreating the receipt.\n\nIf saving or sending fails, check whether the record changed or receipt action succeeded before retrying. Preserve the visible error and invoice reference for support. Never use Delete Record as a substitute for a processor refund.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Invoices","search_terms":["payments history","edit payment","delete payment","receipt","date received","reference","refund record","payment method"],"priority":84,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-invoices-milestones-ledger","guide-payments-connect-and-refunds","guide-reports-review-reconcile"],"source_key":"help_articles_portal"},{"slug":"guide-payments-connect-and-refunds","feature_area":"Payments","audience":"admin","question":"Set up payment processing and handle refund questions","answer_short":"Connect the company’s bank account through the authorized payment setup, verify processor readiness, and distinguish refunds from app ledger edits.","answer_long":"## Set up the company account\n\nPayment setup belongs to the company, not an individual invoice. An owner or administrator opens **Admin Settings → Payments** to review **FuzedFlow Payments**. The payment processor handles its onboarding and payment processing. Do not add bank or card details to customer notes or help messages.\n\n## Connect and review settings\n\n1. In Payments, choose **Link Bank Account** when the company is not connected.\n2. Follow the processor's onboarding instructions and provide the requested information there.\n3. Return to the app and review the connection state. **Account Active** indicates that the app has a linked account; check the processor dashboard for any outstanding verification or processing requirements.\n4. Use **View Stripe Dashboard** to inspect the linked processor account when available.\n5. Under **Invoicing Defaults**, choose **Default Payment Terms** and select **Save Payment Settings**.\n6. Check the payment terms and due date on each invoice before sending; a saved default does not establish the terms of every existing invoice.\n\nLinking the account is not a guarantee that every checkout or payout has completed. Confirm a customer's transaction in the payment processor and the app ledger. Payout timing and account requirements are controlled by the processor and should be checked there.\n\n## Refunds and record corrections\n\nThe invoice payment ledger provides edit and delete-record actions. There is no verified in-app financial Refund button in this workflow. **Delete Record** adjusts the app's accounting record and invoice balance; it does not reverse a card payment or bank transfer.\n\nFor an actual refund, an authorized finance person should inspect the transaction in the company's payment processor and use that processor's supported refund process. Then reconcile the result with company records and ask support how the relevant invoice should be reflected if necessary. Do not assume an external refund automatically synchronized into the app.\n\n## Troubleshooting\n\nIf onboarding fails, preserve the visible error and verify your signed-in company account before retrying. If checkout fails after a customer may have paid, check the processor first to avoid a repeated charge. Ask support about unresolved connection or ledger discrepancies with transaction references, without sharing card numbers or bank credentials.\n\n## Access and support\n\nCompany payment setup is available to owners and administrators through Admin Settings. Ask an authorized administrator to perform setup; sharing an article does not change account permissions.","route":"/AdminSettings","search_terms":["stripe","link bank account","payment settings","connect payments","refund","payout","account active","default payment terms"],"priority":83,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-invoices-share-customer-pay","guide-payments-history-corrections-receipts","guide-invoices-create-edit"],"source_key":"help_articles_portal"},{"slug":"guide-reports-review-reconcile","feature_area":"Reports","audience":"office","question":"Read reports and reconcile sales, expenses, taxes, and receivables","answer_short":"Use the available report sections and date filters while verifying important totals against invoice, payment, and expense records.","answer_long":"## Choose the right report\n\nThe Reports workspace offers **Sales & Revenue**, **Expense Report**, **Tax Summary**, and **Invoice Aging**. These views summarize operational records. Use them to identify work that needs review, and reconcile important financial decisions against the source invoices, actual payments, expenses, and your company's accounting records.\n\n## Navigate and filter\n\n1. Open Reports and choose the section you need. Desktop uses report tabs; mobile uses the report selector.\n2. For sales, expenses, or taxes, choose **YTD**, **QTD**, **This Month**, or **Last Month**.\n3. Read the labels carefully: billed value and revenue received are different amounts, and outstanding receivables represent unpaid billing.\n4. Compare the summary with the relevant invoices and Payments History before acting on a mismatch.\n\nThe monthly sales chart is a recent-month trend and should not be assumed to show exactly the same window as every selected summary. Invoice Aging groups unpaid invoices using their due dates; records without due dates cannot be placed reliably into an aging bucket. Review dates on the underlying invoices when an aging amount looks incorrect.\n\n## Reconcile discrepancies\n\nFirst confirm the selected date window and what the metric represents. Then inspect the related invoice, payment date and amount, ledger allocations, and expense entries. Some totals rely on the availability of their expected date and tax data, so a blank or zero summary does not prove that no transaction occurred. Tax summaries should be checked against invoice and expense tax records before being used for a filing or payment decision.\n\nIf client names show as unknown in a summary, confirm the client link in the original invoice rather than creating another client just to change the report label. Keep a list of the records whose values differ for the finance person or support.\n\n## Troubleshooting\n\nClear the chosen period and compare a broader period when records appear missing. If the summary still conflicts with source records, preserve the report name, period, expected amount, and relevant invoice numbers. Do not edit real payments solely to force a dashboard total to agree. Report visibility is also subject to your subscription's advanced-reporting access.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Reports","search_terms":["reports","sales revenue","expense report","tax summary","invoice aging","ytd","qtd","reconcile","wrong report total"],"priority":82,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":2,"related_slugs":["guide-reports-availability-export","guide-payments-history-corrections-receipts","guide-invoices-milestones-ledger"],"source_key":"help_articles_portal"},{"slug":"guide-reports-availability-export","feature_area":"Reports","audience":"office","question":"Understand advanced-report access and current export availability","answer_short":"Check report subscription access, navigate reports on mobile, and use verified source-record downloads when a report export is not available.","answer_long":"## Access depends on the plan\n\nReports checks the company's advanced-reporting feature. The verified plan configuration enables it for Professional and Business and excludes Starter. A blocked page displays an upgrade panel identifying **Custom & Advanced Reporting**; that panel can name Business even though Professional also has the feature configured. Ask the account owner to review the current subscription if access is unexpected. A different role or an article link does not bypass a subscription requirement.\n\n## Desktop and mobile navigation\n\nOn desktop, use the report tabs for Sales & Revenue, Expense Report, Tax Summary, and Invoice Aging. On a phone, use the **Select report...** control to change sections. For sections with period filtering, the available choices are YTD, QTD, This Month, and Last Month. Horizontal chart or table content may require scrolling; use the selected report name and period to orient yourself before interpreting the values.\n\n## Current export limitation\n\nThe Reports page shows **Export** or **Export Report**, but a downloadable report file is not implemented in the verified workflow. An export toast does not prove that a file has been created. Do not keep pressing the button or assume that the file must be in your device Downloads folder when no download starts.\n\nWhen you need a durable copy, use an available document or source-record workflow instead: customer invoice pages offer a PDF, Clients and Lead Tracker have download controls for their filtered records, and Pricebook provides CSV export. These are different record sets, not a substitute financial report with identical calculations. Check what each file contains and which filters were active when it was generated.\n\n## Troubleshooting and support\n\nIf a report page will not open, confirm the subscription and your company's role permissions. If an available source-file download fails, preserve the selected record and visible error and check your browser's download handling. If you need a report format that is not currently available, give support the report name, date window, required fields, and the purpose of the export.\n\nFor finance review, compare source invoices and actual payment records. Do not infer that a summary is a complete accounting export or an automatic sync with external bookkeeping software.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Reports","search_terms":["report export","export unavailable","advanced reporting","business plan","upgrade wall","mobile reports","download report"],"priority":80,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-reports-review-reconcile","guide-payments-history-corrections-receipts","guide-clients-create-organize","guide-leads-pipeline-find-import"],"source_key":"help_articles_portal"},{"slug":"guide-dashboard-sales-navigation","feature_area":"Reports","audience":"office","question":"Use the Dashboard to resume sales work and follow active leads","answer_short":"Resume unfinished quotes and invoices, inspect recent active leads, and open the complete workspace when the Dashboard shows only a summary.","answer_long":"## Use the Dashboard as a starting point\n\nThe Dashboard brings together recent work and shortcuts. It is useful for resuming a sales conversation or checking what needs attention, but it does not display every company record. Use the full Quotes, Lead Tracker, Clients, or Invoices workspace when you need a complete search or history.\n\n## Resume a document\n\n1. In the continue-working area, look for **Resume Quotes** and unfinished invoice work.\n2. Open the relevant entry to return to its builder.\n3. Verify the contact and current saved scope before editing, particularly when another office user may have worked on it.\n4. Save any changes, then review the customer document before sending.\n5. Use the section's link to the full workspace if the document you need is absent.\n\nThe resume area shows a small selection of unfinished records. Approved, declined, expired, archived, or older documents may not appear there even though they remain in their appropriate lists. A document missing from the Dashboard is not evidence that it was deleted.\n\n## Follow active leads\n\nThe **Leads Snapshot** shows recent active enquiries. Tap a lead to expand its summary and review estimated value, phone, and other available details. Choose **View All Leads** for the complete tracker and its stage/search tools. Active sales summaries exclude Won and Lost opportunities; use the tracker to review those outcomes.\n\nUse the Dashboard's sales shortcuts for new work when offered, then confirm the client or lead in the destination form. Starting from a general Dashboard shortcut does not always preselect a specific customer.\n\n## Troubleshooting\n\nFor a missing record, search in its full workspace, clear filters, and check the archived or terminal-stage views. For an unexpected customer name, inspect the linked client rather than assuming the summary renamed the record. For a financial amount, open the actual invoice and payment history; Dashboard summaries do not replace the ledger.\n\nOn mobile, Dashboard columns stack, so scroll beyond the first card to find the sales sections and shortcuts. Preserve unsaved builder work before navigating back to the Dashboard. If a record still cannot be found, ask the office or support to review the company, role, record number, and visible error.\n\n## Access and support\n\nThese instructions cover the company office workspace. Availability depends on your role and subscription. If a page redirects or is missing from navigation, ask your company owner or administrator to confirm access. Reading this guide does not grant access to the underlying records.","route":"/Dashboard","search_terms":["dashboard","resume quotes","continue working","leads snapshot","recent leads","sales crm","missing dashboard record"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"guide","read_minutes":3,"related_slugs":["guide-leads-pipeline-find-import","guide-quotes-find-duplicate-archive","guide-invoices-create-edit","guide-reports-review-reconcile"],"source_key":"help_articles_portal"},{"slug":"employee-portal-features","feature_area":"Employee Portal","audience":"all","question":"What can employees access in the Employee Portal?","answer_short":"The Employee Portal provides attendance, expenses, assigned projects, schedule, tasks, project notes, and inventory where the plan and company modules allow. Self-service Profile setup is incomplete.","answer_long":"Open **Employee Portal** for your personal field tools. Available sections depend on the company’s plan and enabled features.\n\n- **Clock In**, **My Time Sheets**, **My Pay**, **My Time Off**, and **My Expenses**.\n- **My Projects**, **My Schedule**, **Project Notes**, **My Tasks**, and **Inventory**.\n\nOn mobile, select **More** to find the full menu. If a section is missing, ask an owner or administrator to check **Settings → Employee Portal** and the company’s HR plan access.\n\nThe **Profile → Set Up Profile** self-service save is currently incomplete. Ask an owner or administrator to correct your name, role, hourly rate, or account activity through **Settings → Team Management**; use the employer’s HR process for other employee information. Do not rely on the incomplete form as the sole record for emergency contact details.","route":"/EmployeePortal","search_terms":["employee portal","clock in","timesheet","time off","expenses","profile setup","more menu"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"timesheet-approval","feature_area":"Timesheets","audience":"all","question":"Do timesheets require approval?","answer_short":"Completed shifts and manual missing-hour submissions are Pending until HR reviews them. Employees cannot edit or delete an existing shift from My Time Sheets.","answer_long":"Clocking out or selecting **Submit to HR** in **My Time Sheets → Submit Missing Hours** saves a completed entry as **Pending**.\n\nOwners, administrators, and office staff with HR plan access review entries in **Human Resources → Timesheets**, then approve, reject, or adjust them.\n\nIf an existing entry is rejected or incorrect, ask HR to review it using **Adjust Timesheet**. The employee My Time Sheets form creates a new missing shift; it does not edit or resubmit an existing shift. Do not add a duplicate to correct a record without HR’s instructions.\n\nCheck the shift date, hours, and status. A My Pay estimate can include Pending hours and does not prove payroll was approved or issued.","route":"/EmployeePortal?tab=timesheets","search_terms":["timesheet","approval","approve","reject","pending","adjust timesheet","missing shift"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"notification-overview","feature_area":"Notifications","audience":"all","question":"Where do I find my notifications?","answer_short":"Use the notification bell for alerts allowed by your company, event, role, permissions, and assigned work.","answer_long":"1. Tap the **notification bell** in the top navigation.\n2. Choose **Unread**, or **All** to include read history.\n3. Use **Mentions**, **Projects**, **Financial**, or **Action Required** to narrow the list.\n4. Select an alert to read it and open its related record when a destination is available.\n\nVisibility depends on the event’s permitted roles, module access, company, and project or personal assignment. Financial events do not all have one identical role rule; eligible managers can receive some quote or assigned-project financial updates, while other invoice/payment events are more restricted.\n\nIf **Notify me only when action is required** is on, Important and FYI updates remain hidden even in All. Turn it off to include them again. In-app alerts do not by themselves prove email, SMS, or native phone push delivery.","route":"/FAQ?article=notification-overview","search_terms":["notifications","bell","financial alerts","role","permissions","unread","action only"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"invite-team-member","feature_area":"Team","audience":"admin","question":"How do I invite a team member?","answer_short":"Owners and administrators save team invitations in Settings → Team Management. Verify the pending record and ask the colleague to join with the invited email.","answer_long":"1. Sign in as an **Owner** or **Admin**.\n2. Open **Settings → Team Management** and **Invite Team Member**.\n3. Enter the colleague’s **Full Name** and **Email Address**.\n4. Choose a supported **Access Role** and the appropriate **Hourly Pay Rate**.\n5. Select **Send Invite** and verify the pending member appears in the list.\n\nA saved pending invitation and the screen’s success message do not prove that an invitation email was delivered. Ask the colleague to use the invited email on the company join/signup path; if an invitation email exists, they can follow that link. Do not have them create an unrelated company account.\n\nCurrent invitations require an owner/admin and canonical roles. Use the detailed Team Management form if a legacy Team Settings screen offers Standard User.","route":"/AdminSettings","search_terms":["invite","team","employee","join company","pending invite","email delivery"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"pending-invites","feature_area":"Team","audience":"admin","question":"Can I see pending team invitations?","answer_short":"Yes. Owners and administrators can inspect and edit or cancel pending invitations in Settings → Team Management.","answer_long":"Open **Settings → Team Management** as an Owner or Admin. Search by the colleague’s name or email and review the pending record’s address and role.\n\nUse the pending member’s edit action to correct the available invitation details, or cancel an obsolete invitation. The current detailed form does not provide a dedicated Resend Email action. A pending record confirms the invitation was saved; it does not confirm an email was delivered.\n\nAsk the colleague to register with the exact invited email on the company join/signup path, and check any received invitation email and spam folder. If the email already belongs to another company, resolve that membership rather than repeating signup.\n\nPending invitations count toward the detailed invitation form’s user-limit check.","route":"/AdminSettings","search_terms":["pending","invitation","team","cancel invite","resend email","seat limit"],"priority":75,"requires_admin":true,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"hr-approvals","feature_area":"HR","audience":"office","question":"What can administrators approve in the HR area?","answer_short":"Owners, administrators, and office staff with HR plan access can review time entries, time-off requests, and expenses. Use All Statuses to find Submitted expenses.","answer_long":"Open **Human Resources** as an Owner, Admin, or Office user on a plan with HR access. Choose **Timesheets**, **Time Off**, or **Expenses**; on mobile use the view dropdown.\n\n1. Check the employee, status, and date filters.\n2. Review the hours or amount and supporting details.\n3. Select the intended records and choose **Approve** or **Reject**.\n4. Use **Adjust** on an existing timesheet to correct its date, hours, timestamps, type, status, and notes.\n\nEmployee expense claims begin as **Submitted**. HR’s default **Pending Only** filter matches Pending or blank status, so it can hide Submitted claims. Select **All Statuses** and an appropriate date range to find them.\n\nApproving a record changes its status; it does not pay wages or issue an expense reimbursement. My Pay shows estimates, and final processing follows the employer’s payroll process.","route":"/HumanResources","search_terms":["HR","timesheet","time off","expenses","approval","Submitted","All Statuses","adjust timesheet"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"daily-log-edit-delete","feature_area":"Daily Logs","audience":"all","question":"Can project Daily Logs be edited or deleted?","answer_short":"Authorized office/project staff can edit or delete daily logs. The Employee Portal personal log list offers Details and Delete, but no full edit form.","answer_long":"Authorized office/project staff can edit and delete entries in **PM Projects → your project → Project Notes**, or the office **Daily Logs** page. Review the log’s date, author, and linked work before changing it.\n\nIn **Employee Portal → Project Notes**, your personal log history provides **Details** and a delete action with confirmation. It does not provide the office’s full Edit Log form. Ask the manager how to correct an important submitted report instead of assuming you can edit it directly or deleting it prematurely.\n\nDeleting a log removes the record; it does not reverse inventory usage mentioned in its Materials Used text. Inventory transactions are managed separately.","route":"/DailyLogs","search_terms":["daily log","edit log","delete log","project note","field log"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"warranty-workflow-availability","feature_area":"Warranty","audience":"all","question":"Can I manage warranty claims in FuzedFlow?","answer_short":"Yes. Warranty supports saved claims, assignment, response deadlines, repair visits, customer updates, confirmation and reopening.","answer_long":"Open **Warranty** to create or manage accessible claims. Choose **New claim**, select the project, enter the issue, assign responsibility and set the response deadline. Use **Manage claim** to record a repair visit and resolution. **Email warranty access** shares an expiring customer link for new claims and updates; **Email claim access to customer** shares a single claim. Internal notes remain private unless **Show this update in the customer's warranty link** is checked. The customer can confirm a completed repair or reopen a resolved claim. Assigned field staff can read and add updates to their assigned claim.","route":"/Warranty","search_terms":["warranty workflow availability"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"document-signature-availability","feature_area":"Documents","audience":"all","question":"Does document approval capture an electronic signature?","answer_short":"Quote/change-order approval remains separate. General project documents have a dedicated electronic-signature request with consent and an activity record.","answer_long":"In the project's **Quotes & Docs → Reviews & signatures**, select **Request review / signature**, choose the saved document and **Electronic signature**, then review the named recipient, expiry and instructions before **Create and email request**. The recipient opens the secure link, reviews the file, enters their full name, confirms electronic consent and selects **Sign document**. The saved response records the name, date, consent version and document reference/checksum where available. Uploading a file or marking a sales document Approved does not itself capture this response.","route":"/HelpArticles","search_terms":["document signature availability"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"phone-push-notifications","feature_area":"Notifications","audience":"all","question":"Are in-app notifications the same as phone push notifications?","answer_short":"No. In-app alerts are the bell history; optional device push requires a supported browser, explicit device permission and configured delivery.","answer_long":"Open the notification bell's personal settings, enable **Device push notifications**, choose **Connect this device**, approve the browser permission and select **Save my preferences**. On iOS/iPadOS 16.4 or later, add Fuzed Flow to the Home Screen and open the installed app before connecting. Each device connects separately. **Disable on this device** and signing out remove that device. Device push, SMS, instant email and digests begin off; configured providers and scheduled delivery are also required. Company document SMS alerts are a separate setting.","route":"/EmployeePortal","search_terms":["phone push","mobile notification","browser permission","home screen","connect device"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"notification-quiet-hours","feature_area":"Notifications","audience":"all","question":"How do I stop external alerts overnight?","answer_short":"Enable Quiet hours for email, SMS and push in My notifications; in-app history remains available.","answer_long":"Open the bell's settings or **Admin Settings → Notifications → My notifications**, enable **Quiet hours for email, SMS and push**, choose start/end times and the correct timezone, then **Save my preferences**. Eligible external personal alerts wait until quiet hours end. This preference does not delete alerts or mark their work complete.","route":"/EmployeePortal","search_terms":["notification quiet hours"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"notification-digests","feature_area":"Notifications","audience":"all","question":"Can I get a daily or weekly summary instead of individual emails?","answer_short":"Yes. Choose Daily summary or Weekly summary under Email digest in My notifications.","answer_long":"Set **Email digest** to **Daily summary** or **Weekly summary**, choose **Send after** and the weekly **Day**, then save. Digests are separate from **Instant email** and contain future eligible updates after opting in, filtered by your category preferences and access. Turning the digest setting Off stops future summaries. Delivery requires the configured email provider and scheduled dispatcher.","route":"/EmployeePortal","search_terms":["notification digests"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"notification-actor-date","feature_area":"Notifications","audience":"all","question":"Why do notifications show a person, record name and date?","answer_short":"The wording identifies the actor and the actual event, for example Gary Byrne created Lead Tim Rich on Oct 2nd, 2026.","answer_long":"The notification describes the saved person or customer action, named record and event date where the source workflow records them. Scheduled reminders use a system identity instead of attributing them to an employee. Reading or dismissing an alert does not change the underlying task, lead, document or claim. Check the record itself when a status or payment needs verification.","route":"/EmployeePortal","search_terms":["notification actor date"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"document-request-link-expired","feature_area":"Documents","audience":"all","question":"What if a document review or signature link has expired?","answer_short":"Ask the sender for current access; the sender can create another request or renew a pending request link.","answer_long":"For a pending request, the sender can use **Renew link & remind** in **Reviews & signatures**. Earlier links stop working. For an expired request, use **Request again** and review the new document/recipient/expiry before sending. The recipient should use the original current secure link rather than an internal builder URL. A completed response remains recorded and cannot be overwritten by replaying its link.","route":"/HelpArticles","search_terms":["document request link expired"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"equipment-reservations","feature_area":"Inventory","audience":"all","question":"Can I reserve equipment and receive overdue-return alerts?","answer_short":"Office staff reserve and check out equipment. Assigned field staff use My equipment to request checkout and confirm a physical return; overdue/conflict alerts follow the saved reservation.","answer_long":"Permitted office/project staff open **Inventory → Reservations and returns**, choose **Reserve**, enter quantity/project/person/start/return due and save. Use **Check out** for the physical handover and **Record return** after handback. Conflicts can warn and alert management while retaining the reservation. Equipment condition and Next maintenance date support maintenance/damaged/missing alerts.\n\nAssigned field staff open **Employee Portal → Inventory → My equipment**. **Request checkout** keeps the reservation Reserved until the office approves the handover with **Check out**. After returning checked-out equipment, choose **Confirm equipment returned**. These actions apply only to your own assigned reservation. A notification opens and highlights its target, including older records.","route":"/Inventory","search_terms":["equipment reservations","my equipment","request checkout","reserved office approval","confirm equipment returned"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"task-prerequisites","feature_area":"Tasks","audience":"all","question":"Does completing a prerequisite automatically complete the next task?","answer_short":"No. Completing all prerequisites creates a readiness alert; the dependent task still needs to be performed and completed.","answer_long":"For production tasks, a permitted manager adds **Prerequisites → Choose a prerequisite → Add prerequisite** from the same project. Circular dependencies are rejected. Staff can read the prerequisite list on their assigned task. Use **Task discussion → Post comment** for task-specific information. A ready alert does not verify site conditions, material availability or inspection readiness.","route":"/Tasks","search_terms":["task prerequisites"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"field-material-return","feature_area":"Inventory","audience":"all","question":"How do I return materials to warehouse stock without deleting the usage history?","answer_short":"Open your Checkout History record’s Details and choose Return materials to stock. It restores the recorded quantity once and retains the original usage history.","answer_long":"In **Employee Portal → Inventory → Checkout History**, open **Details** for your own recorded material usage. Verify the material, quantity and project. After physically returning those materials or agreeing a correction with the office, choose **Return materials to stock** and wait for success. The original usage remains in history, marked **Returned to stock**. Repeating the return cannot refund that quantity again.\n\nStock deduction and new usage history are saved together; insufficient warehouse stock is rejected. Only your own saved usage record can authorize a return. Older records saved by employee name remain read-only and require office verification. Reusable equipment uses **My equipment → Confirm equipment returned** after handback, rather than material-stock restoration.","route":"/EmployeePortal?tab=inventory","search_terms":["return materials to stock","warehouse stock refund once","retained usage history","checkout history"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"send-change-order","feature_area":"Change Orders","audience":"contractor","question":"Can I send a change order to a client for approval?","answer_short":"Open the saved change order builder and use Actions → Send via Email. The list-level Send to Client action is a coming-soon placeholder.","answer_long":"1. Open **Change Orders** and select the saved change order's number to open its builder.\n2. Review the linked project, client, scope, line items, and totals, then save.\n3. Use **Actions → Client Preview** to check the client document.\n4. Choose **Actions → Send via Email**, review the client address, subject, message, signature, and optional PDF attachment, then select **Send Email**.\n5. Wait for the send result before assuming the message was dispatched.\n\nThe builder also has **Send via Text Message** and a client review link. The list-level **Send to Client** action currently displays a coming-soon notice. **Mark as Sent** changes status without sending a message; Sent alone does not prove delivery to the recipient's inbox.\n\nApproval and request changes are separate client actions. After approval, check project-budget synchronization separately.","route":"/ChangeOrders","search_terms":["change order","send","approval","change order send email","send to client placeholder","mark as sent"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"change-order-statuses","feature_area":"Change Orders","audience":"contractor","question":"What statuses are available for change orders?","answer_short":"The change-order list can filter Draft, Sent, Approved, Declined, and Invoiced records.","answer_long":"The **Change Orders** list offers status filters for **Draft**, **Sent**, **Approved**, **Declined**, and **Invoiced**, plus **All Statuses**.\n\nReview status separately from financial totals and document delivery. The builder's **Mark as Sent** action changes the record's status without sending an email. Use the builder's send action when you need to contact the client.\n\nPublic client approval saves Approved status and the selected items/totals. It uses a different path from the builder's project synchronization action, so verify the project's budget and work records separately after a decision.","route":"/ChangeOrders","search_terms":["change order","status","draft","sent","approved","invoiced change order","change order status filters"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"post-client-update","feature_area":"Client Timeline","audience":"contractor","question":"Can I post a manual project update for the client?","answer_short":"Yes. Use Post Update in the project Client View to save a dated title, details, and client-visibility choice.","answer_long":"1. Open **PM Projects**, select **Open** on the project, and choose **Client View**.\n2. Select **Post Update**, or **Post First Update** when the feed is empty.\n3. Enter **Event Title / Summary**, **Event Date**, and **Details & Notes**.\n4. Review **Visible to Client** and select **Post Update** to save.\n\nThe dialog does not include a category selector; manual posts use the Update category. Updates with client visibility switched off are not shown in the client-visible feed. Saving an update does not itself confirm delivery of an email or text.","route":"/PMProjects","search_terms":["post update","client update","timeline","client update fields","visible to client"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"phase-client-visible","feature_area":"Project Phases","audience":"contractor","question":"Can I hide a project phase from the client?","answer_short":"Yes. Expand the phase and switch Visible in Client Portal off; the visibility change saves directly.","answer_long":"1. Open **PM Projects**, select **Open** on the project, and choose **Phases**.\n2. Expand the required phase with its chevron.\n3. Change **Visible in Client Portal**. The switch saves the visibility change directly; there is no separate Save Phase button for this update.\n4. Check **Client View** to review the visible phase feed.\n\nOnly make phases visible when their information is appropriate for the client. The feed displays phase name, progress, and status; Internal Phase Notes and Micro-Costing are separate operational sections.","route":"/PMProjects","search_terms":["client visible","hide phase","client portal","phase visibility switch","save phase visibility"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"inventory-tracking","feature_area":"Inventory","audience":"contractor","question":"What can FuzedFlow track in Inventory?","answer_short":"Warehouse Inventory tracks physical items, quantity, unit, cost, location, reorder threshold, and supplier details; Usage Report shows saved movements.","answer_long":"**Inventory → Warehouse Inventory** tracks physical stock records including item name, SKU, category, unit, unit cost, current quantity, physical location, reorder threshold, supplier, description, and image.\n\nThe **Low Stock Alerts** filter is calculated from quantity at or below the reorder threshold. It is not a separate editable purchasing-status field.\n\nUse **Usage Report** to inspect saved **Consume** and **Receive** transactions and filter by project, employee, or type. A direct Current Qty edit is different from recording a project-specific usage transaction.\n\nProject **Materials** has separate purchasing states such as To Order, Ordered, and Received. Saving project materials or a purchase order does not automatically change warehouse stock.","route":"/Inventory","search_terms":["inventory","quantity","location","status","movement","warehouse stock fields","low stock calculated","inventory usage report"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"vendors-location","feature_area":"Vendors","audience":"all","question":"Where do I manage vendors and subcontractors?","answer_short":"Vendors is the company subcontractor/supplier directory; the project Subcontractors area manages project assignments. Directory access is restricted.","answer_long":"Open **Vendors** for the **Subcontractors Directory**, including contact information, categories, preferred status, project history, supporting files, and internal notes.\n\nFor a specific job, open **PM Projects → Open → Subcontractors** to create or review a project assignment. A directory record or project-history tag does not itself schedule a subcontractor for a job. Phase-level assignment is available under the project's **Phases** area.\n\nThe global directory has an access check. If your account shows **Access Denied**, ask a company administrator to review that access rather than assuming the directory is empty. On mobile, directory creation and import actions are in the top **Actions** menu.","route":"/Vendors","search_terms":["vendor","subcontractor","supplier","directory","vendors access denied","subcontractor directory actions"],"priority":90,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"delete-paid-milestone","feature_area":"Invoices","audience":"contractor","question":"Can I delete a payment milestone after it has been paid?","answer_short":"The current invoice builder does not protect paid milestones from removal. Do not remove paid milestones without reviewing the payment ledger and allocation.","answer_long":"The current **Invoice Builder → Payment Schedule** shows a remove action for milestones, including paid ones. Do not rely on a paid milestone being protected from deletion.\n\nBefore changing the schedule, review **Payments History** and which payments are allocated to each milestone. Removing a milestone is not a refund and can make the schedule inconsistent with its payment history. Ask the authorized billing user or support to review the invoice if a paid milestone needs correction.","route":"/Invoices","search_terms":["paid milestone","delete","payment schedule","paid payment","allocation","refund"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"payment-schedule-balance","feature_area":"Invoices","audience":"contractor","question":"Why can't I confirm an invoice payment schedule?","answer_short":"In the current invoice builder, add or edit milestones with Save Item and then save the invoice; there is no separate Confirm Schedule action in that screen.","answer_long":"In the current **Invoice Builder**, use **Payment Schedule → Add Milestone**, enter the name, event and amount, and select **Save Item**. Then save the invoice and verify the stored schedule.\n\nReview the sum of the milestone amounts against the invoice contract total. The builder rejects a new or edited milestone that would exceed the available total and can adjust an unpaid milestone after the contract total changes. Recheck every amount after scope or price edits.\n\nDo not assume paid milestones are protected from removal in the current builder. Preserve their allocation and ledger history. If invoice saving fails, keep your entered details and inspect the invoice list before retrying; contact support if it remains unresolved.","route":"/Invoices","search_terms":["payment schedule","balanced","invoice total","save item","remaining","milestone","save failure"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"convert-lead-client","feature_area":"Leads","audience":"contractor","question":"What happens when I convert a lead to a client?","answer_short":"Conversion creates a client and marks the lead Won. Lead Detail and the tracker’s Won confirmation transfer different information, so review the resulting client.","answer_long":"From **Lead Detail**, choose **Convert to Client** when the prospect should become a client. That workflow creates a client, marks the lead **Won**, copies lead notes and files, and attempts to link the lead’s quotes to the new client. Review the resulting client’s contact details, addresses, attachments and quotes.\n\nThe **Lead Tracker → Won** confirmation also creates a client, but its transfer is more limited: it copies contact/address information and a description-or-notes field rather than the full detail history. Do not assume the two routes transfer identical data.\n\nConversion does not merge into an existing client. Search Clients first, and inspect the result before repeating a failed conversion so you do not create duplicates.","route":"/LeadTracker","search_terms":["lead","convert","client","won","lead detail","notes transfer","duplicate client"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"lead-notes-transfer","feature_area":"Leads","audience":"contractor","question":"Do lead notes transfer when I convert a lead to a client?","answer_short":"Lead Detail conversion copies dedicated lead-note records. The tracker’s Won confirmation transfers only limited description/notes information.","answer_long":"It depends on the conversion route.\n\n- **Lead Detail → Convert to Client** copies the lead’s dedicated note records to the new client, along with its description/internal notes and other transferred information.\n- The **Lead Tracker → Won** confirmation copies a description-or-notes value into the new client; it does not perform the same dedicated-note history transfer.\n\nAfter conversion, open **Client Detail** and verify the notes and attachments you need. Keep the original lead while resolving an incomplete transfer, and do not repeat conversion solely to recover a missing note because it can create another client.","route":"/LeadTracker","search_terms":["lead","notes","convert","client","won","transfer history","lead detail"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"quote-followups","feature_area":"Quotes","audience":"contractor","question":"Can FuzedFlow automatically follow up on sent quotes?","answer_short":"Quote reminders are configured for the company under Admin Settings → Automations, not by a per-quote reminder control in the current builder.","answer_long":"Company quote-reminder settings are under **Admin Settings → Automations → Quote Follow-ups**. An authorized user can enable the company setting, review **First Check-in** and **Final Push**, and select **Save Automations**.\n\nThe implemented reminder process considers **Sent** or **Viewed** quotes linked to a client with an email address. Its timing uses the quote’s creation date, not the date you most recently sent it. Approved or Declined quotes are outside those reminder statuses.\n\nThe current Quote Builder does not offer per-quote reminder intervals, maximum-reminder settings, or a follow-up enable switch. Sending also depends on the deployed scheduled process and email setup; saving company settings alone is not proof that a reminder was delivered. Ask the administrator or support to verify reminder operation if needed.","route":"/Quotes","search_terms":["follow up","automatic","quote","reminder","company automations","first check-in","final push","sent viewed"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"quote-followup-template","feature_area":"Quotes","audience":"contractor","question":"Can I customize the automatic quote follow-up email?","answer_short":"The current quote reminder process does not provide a subscriber-editable per-quote follow-up subject or body template.","answer_long":"The current **Quote Builder** does not include a follow-up email-template editor. **Admin Settings → Automations** configures company reminder timing, while the implemented quote-reminder process uses its own reminder subject and message.\n\nFor a manually sent quote email, use **Actions → Send via Email** and edit its subject, message and signature before sending. That manual message editor is separate from automatic follow-ups. Ask support about a required reminder customization rather than assuming the ordinary quote email template changes the automated reminder.","route":"/Quotes","search_terms":["follow up","template","quote","automatic reminder","subject","message","manual email"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"quote-followup-history","feature_area":"Quotes","audience":"contractor","question":"Can I see a history of automatic quote follow-ups?","answer_short":"The current Quote Builder does not display a per-quote automatic follow-up history or delivery-status panel.","answer_long":"The current **Quote Builder** does not show an automatic follow-up history panel with reminder number, recipient, subject, or delivery status.\n\nCompany reminder settings can be reviewed in **Admin Settings → Automations**, but a configured schedule or a quote’s **Sent** status is not proof that a specific reminder was delivered. Quote view tracking is a separate feature and should not be treated as reminder-delivery history.\n\nIf you need to confirm whether a reminder went out, ask the administrator or support to check the scheduled reminder process and email delivery using the quote number and approximate time. Do not repeatedly send a manual reminder before checking whether the customer already received one.","route":"/Quotes","search_terms":["follow up history","sent","failed","bounced","delivery","reminder","quote viewed"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"resource-library","feature_area":"Resource Library","audience":"contractor","question":"What can I store in the Resource Library?","answer_short":"Use the Resource Library page for reusable company files such as flyers, licenses and blank forms; it is separate from Pricebook.","answer_long":"Open **Client Forms** in company navigation to reach the page headed **Resource Library**. It is separate from the Products/Pricebook page.\n\nUse **Upload File** to store a clearly named flyer, license, certificate or blank form, with an optional project link. Confirm the uploaded file opens with **View**.\n\nIn Quote Builder, use the resource picker under **Attached Documents** to open **Company Resources**, select **Attach**, and save the quote. Attaching a form does not create a general electronic-signature workflow, and uploading a warranty document does not enable warranty claims. Project drawings belong in the project’s Plans & Elevations workflow.","route":"/ClientForms","search_terms":["resource library","client forms","flyer","license","form","upload file","company resources","attach"],"priority":75,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"},{"slug":"quote-internal-notes","feature_area":"Quotes","audience":"contractor","question":"Can I add notes to a quote that the client cannot see?","answer_short":"Use quote-level or phase-level internal notes for saved private reminders, and verify them after saving. Do not rely on line-item notes persisting.","answer_long":"Use the quote’s **Internal Notes** or the phase’s private notes field under **Settings** for saved team reminders. These fields are separate from the client-facing scope and message. Save and reopen the quote to confirm the notes you need are retained.\n\nThe line-item editor also displays an internal-notes field, but the current quote-save workflow does not retain that field with the saved line item. Copy important line-item reminders into the quote or phase internal notes before saving. Do not put private information in the item description, which is shown to the client.","route":"/Quotes","search_terms":["internal notes","hidden","client","quote","phase notes","private","line item notes","not saved"],"priority":50,"requires_admin":false,"is_active":true,"last_verified_at":"2026-10-04","article_type":"faq","read_minutes":2,"related_slugs":[],"source_key":"help_articles_faq_correction"}]$articles$::jsonb)
AS a(slug text,feature_area text,audience text,question text,answer_short text,answer_long text,route text,search_terms text[],priority smallint,requires_admin boolean,is_active boolean,last_verified_at date,article_type text,read_minutes smallint,related_slugs text[],source_key text)
ON CONFLICT (slug) DO UPDATE SET
 feature_area=EXCLUDED.feature_area,
 audience=EXCLUDED.audience,
 question=EXCLUDED.question,
 answer_short=EXCLUDED.answer_short,
 answer_long=EXCLUDED.answer_long,
 route=EXCLUDED.route,
 search_terms=EXCLUDED.search_terms,
 priority=EXCLUDED.priority,
 requires_admin=EXCLUDED.requires_admin,
 is_active=EXCLUDED.is_active,
 last_verified_at=EXCLUDED.last_verified_at,
 article_type=EXCLUDED.article_type,
 read_minutes=EXCLUDED.read_minutes,
 related_slugs=EXCLUDED.related_slugs,
 source_key=EXCLUDED.source_key,
 embedding=CASE WHEN (help_faqs.question,help_faqs.answer_short,help_faqs.answer_long) IS NOT DISTINCT FROM (EXCLUDED.question,EXCLUDED.answer_short,EXCLUDED.answer_long) THEN help_faqs.embedding ELSE NULL END;
